package com.hardcoreworldtoolkit;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

/**
 * Anonymous, stable id for one game account: a salted SHA-256 of RuneLite's account hash. It lets the server keep
 * one account's trades together without ever learning the account hash or the player's name.
 */
final class AccountId
{
	/**
	 * Part of the id's format, specific to this plugin. Changing it would give every account a new id (the server's
	 * per-account data and trust would start over).
	 */
	static final String PREFIX = "hardcore-world-tool-kit:";
	private static final char[] HEX = "0123456789abcdef".toCharArray();

	private AccountId()
	{
	}

	/** Lowercase hex SHA-256 of {@code "hardcore-world-tool-kit:" + accountHash} (UTF-8): always 64 characters. */
	static String of(long accountHash)
	{
		MessageDigest md;
		try
		{
			md = MessageDigest.getInstance("SHA-256");
		}
		catch (NoSuchAlgorithmException e)
		{
			// Every Java platform is required to provide SHA-256.
			throw new IllegalStateException(e);
		}
		byte[] digest = md.digest((PREFIX + accountHash).getBytes(StandardCharsets.UTF_8));
		char[] out = new char[digest.length * 2];
		for (int i = 0; i < digest.length; i++)
		{
			out[i * 2] = HEX[(digest[i] >> 4) & 0xf];
			out[i * 2 + 1] = HEX[digest[i] & 0xf];
		}
		return new String(out);
	}
}

package com.hardcoreworldtoolkit;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.function.IntFunction;
import lombok.Value;

/**
 * One of the player's own GE offers that is still open (active and not fully filled), as an immutable snapshot for
 * the panel. Built on the client thread from {@link OfferTracker}'s slots.
 */
@Value
public class ActiveOffer
{
	int slot;
	String offerKey;
	int itemId;
	String name;
	boolean buy;
	/** Offer price per item. */
	long price;
	int totalQty;
	int filled;
	/** When the offer was placed (unix s). */
	long placedAt;

	/**
	 * The open offers in slot order.
	 *
	 * @param names item names by id (on the client thread, the item manager)
	 */
	static List<ActiveOffer> fromTracker(OfferTracker t, IntFunction<String> names)
	{
		List<ActiveOffer> out = new ArrayList<>();
		for (int slot = 0; slot < OfferTracker.SLOTS; slot++)
		{
			OfferTracker.SlotState s = t.getSlot(slot);
			if (s == null || s.getStatus() != OfferTracker.Status.ACTIVE || s.getSold() >= s.getTotalQty())
			{
				continue;
			}
			out.add(new ActiveOffer(slot, s.getOfferKey(), s.getItemId(), names.apply(s.getItemId()), s.isBuy(),
				s.getPrice(), s.getTotalQty(), s.getSold(), s.getPlacedAt()));
		}
		return Collections.unmodifiableList(out);
	}
}

package com.hardcoreworldtoolkit;

import java.util.Collection;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;

/**
 * Decides when an offer alert may notify (pure apart from its own state; thread safe). Only a change into UNDERCUT or
 * OUTBID notifies, the same offer and flag at most once per {@link #COOLDOWN_MS}, and any two alerts at least
 * {@link #GLOBAL_GAP_MS} apart.
 */
final class AlertGate
{
	static final long COOLDOWN_MS = 30 * 60_000L;
	static final long GLOBAL_GAP_MS = 60_000L;

	/** The last flag seen per offer key. */
	private final Map<String, OfferWatch.Flag> lastFlag = new HashMap<>();
	/** When "offerKey|flag" last notified (epoch ms). */
	private final Map<String, Long> lastFired = new HashMap<>();
	private long lastAny = Long.MIN_VALUE;

	/**
	 * Record the offer's current flag and say whether to notify now.
	 *
	 * @param nowMs epoch ms
	 */
	synchronized boolean shouldNotify(String offerKey, OfferWatch.Flag flag, long nowMs)
	{
		OfferWatch.Flag prev = lastFlag.put(offerKey, flag);
		if ((flag != OfferWatch.Flag.UNDERCUT && flag != OfferWatch.Flag.OUTBID) || flag == prev)
		{
			return false;
		}
		String key = offerKey + "|" + flag;
		Long fired = lastFired.get(key);
		if (fired != null && nowMs - fired < COOLDOWN_MS)
		{
			// Already told recently; this change is used up.
			return false;
		}
		if (lastAny != Long.MIN_VALUE && nowMs - lastAny < GLOBAL_GAP_MS)
		{
			// Too soon after another alert: forget we saw it, so the next check (a minute later) tries again.
			restore(offerKey, prev);
			return false;
		}
		lastFired.put(key, nowMs);
		lastAny = nowMs;
		return true;
	}

	/** Forget offers that are no longer open. */
	synchronized void retain(Collection<String> openOfferKeys)
	{
		Set<String> keep = new HashSet<>(openOfferKeys);
		lastFlag.keySet().retainAll(keep);
		lastFired.keySet().removeIf(k -> !keep.contains(k.substring(0, k.lastIndexOf('|'))));
	}

	private void restore(String offerKey, OfferWatch.Flag prev)
	{
		if (prev == null)
		{
			lastFlag.remove(offerKey);
		}
		else
		{
			lastFlag.put(offerKey, prev);
		}
	}
}

package com.hardcoreworldtoolkit;

import java.awt.Dimension;
import java.awt.Graphics2D;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.ui.overlay.Overlay;

/**
 * Never registered with the OverlayManager and never drawn. It only carries the plugin in an OverlayMenuClicked
 * event, which RuneLite's config plugin answers by opening this plugin's configuration page (the panel's gear button).
 */
class ConfigLinkOverlay extends Overlay
{
	ConfigLinkOverlay(Plugin plugin)
	{
		super(plugin);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		return null;
	}
}

package com.hardcoreworldtoolkit;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import java.io.IOException;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.function.Consumer;
import lombok.extern.slf4j.Slf4j;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.Response;

/**
 * "Delete my shared data": asks the server to delete everything this install sent ({@link ServerApi#deleteMe},
 * DELETE v1/me with the install token), then disconnects and starts over as a new, unlinkable install id. Only ever
 * started by the player (the panel's Privacy menu, after a confirm dialog), and like every request only sent while
 * connected: when not connected nothing is sent ({@link Outcome#NOT_CONNECTED}).
 * <p>
 * Steps: pause the uploader; once no upload is in flight (a callback, never blocking), send the DELETE. Without a
 * token (an install that uploaded before tokens existed) it registers first. A 401 registers once and retries. If
 * that registration gets 409, only the server's explicit "installId deleted" counts as nothing to delete; a 409 for
 * an id held by another token means this PC lost its key, so the data may still be there: the player is told so,
 * with the install id to quote to the privacy contact, and the id is kept. All network calls are OkHttp enqueues; the
 * result callback runs on an OkHttp thread (or the caller's thread when idle and nothing could be started). Identity
 * and config writes happen there too, never on the client thread.
 */
@Slf4j
class DataDeletion
{
	enum Outcome
	{
		/** 200: deleted. */
		DELETED,
		/** 202: the server accepted it and finishes in the background. */
		PENDING,
		/** The server says this install id's data was deleted already. */
		NOTHING,
		/**
		 * The install id is held by a token this PC doesn't have (its key was lost or replaced): nothing could be
		 * deleted, and the data may still be on the server. The id is kept so the player can quote it.
		 */
		KEY_LOST,
		/** Not connected, so nothing was sent; everything stays as it was. */
		NOT_CONNECTED,
		/** Server error, rate limited or unreachable; still connected. */
		FAILED
	}

	/**
	 * The outcome, with the HTTP status for {@link Outcome#FAILED} (-1 when the server couldn't be reached) and, for
	 * {@link Outcome#KEY_LOST}, the install id (not a secret) to quote in an erasure request.
	 */
	static final class Result
	{
		final Outcome outcome;
		final int code;
		final String installId;
		/** Older install ids of this PC whose key was lost: their data can't be deleted from here. */
		final List<String> lostIds;

		Result(Outcome outcome, int code)
		{
			this(outcome, code, null);
		}

		Result(Outcome outcome, int code, String installId)
		{
			this(outcome, code, installId, Collections.emptyList());
		}

		Result(Outcome outcome, int code, String installId, List<String> lostIds)
		{
			this.outcome = outcome;
			this.code = code;
			this.installId = installId;
			this.lostIds = lostIds;
		}

		@Override
		public String toString()
		{
			return outcome + "(" + code + ")";
		}
	}

	private final ServerApi api;
	private final ServerIdentity identity;
	private final InstallAuth auth;
	private final TradeUploader uploader;
	/** Turns the "connected" setting off. */
	private final Runnable disconnect;
	private final AtomicBoolean running = new AtomicBoolean();
	/** Set on plugin shutdown: the result isn't reported any more (the local state is still updated). */
	private volatile boolean cancelled;

	DataDeletion(ServerApi api, Gson gson, ServerIdentity identity, TradeUploader uploader, Runnable disconnect)
	{
		this.api = api;
		this.identity = identity;
		this.auth = new InstallAuth(api, gson, identity);
		this.uploader = uploader;
		this.disconnect = disconnect;
	}

	/** True while a deletion is running. */
	boolean isRunning()
	{
		return running.get();
	}

	/** Stop reporting results (plugin shutdown). Never blocks. */
	void cancel()
	{
		cancelled = true;
	}

	/**
	 * Start a deletion. Returns false (and does nothing) when one is already running.
	 *
	 * @param done called once with the result
	 */
	boolean start(Consumer<Result> done)
	{
		if (!running.compareAndSet(false, true))
		{
			return false;
		}
		uploader.pause();
		uploader.whenIdle(() -> step(done));
		return true;
	}

	/** No upload in flight any more: send the deletion (registering first when there is no token). */
	private void step(Consumer<Result> done)
	{
		try
		{
			String installId = identity.installId();
			String token = identity.token();
			if (token == null)
			{
				registerThenDelete(done);
			}
			else
			{
				delete(installId, token, false, done);
			}
		}
		catch (RuntimeException e)
		{
			log.warn("Data deletion failed", e);
			finish(new Result(Outcome.FAILED, -1), done);
		}
	}

	private void registerThenDelete(Consumer<Result> done)
	{
		// No rotation on 409: the id is either deleted already, or held by a token this PC doesn't have.
		auth.register(false, r ->
		{
			switch (r.getStatus())
			{
				case OK:
					delete(r.getInstallId(), r.getToken(), true, done);
					break;
				case DELETED:
					finish(new Result(Outcome.NOTHING, r.getCode()), done);
					break;
				case CONFLICT:
					finish(new Result(Outcome.KEY_LOST, r.getCode(), r.getInstallId()), done);
					break;
				case NOT_CONNECTED:
					finish(new Result(Outcome.NOT_CONNECTED, -1), done);
					break;
				default:
					finish(new Result(Outcome.FAILED, r.getCode()), done);
			}
		});
	}

	private void delete(String installId, String token, boolean reauthed, Consumer<Result> done)
	{
		JsonObject body = new JsonObject();
		body.addProperty("installId", installId);
		Callback callback = new Callback()
		{
			@Override
			public void onFailure(Call c, IOException e)
			{
				log.debug("Data deletion request failed: {}", e.getClass().getSimpleName());
				finish(new Result(Outcome.FAILED, -1), done);
			}

			@Override
			public void onResponse(Call c, Response response)
			{
				int code;
				try (response)
				{
					code = response.code();
				}
				log.debug("Data deletion: HTTP {}", code);
				if (code == 200)
				{
					finish(new Result(Outcome.DELETED, code), done);
				}
				else if (code == 202)
				{
					finish(new Result(Outcome.PENDING, code), done);
				}
				else if (code == 401 && !reauthed)
				{
					// The token isn't accepted (lost, or the data is already gone): register once and retry.
					identity.clearToken(installId);
					registerThenDelete(done);
				}
				else
				{
					finish(new Result(Outcome.FAILED, code), done);
				}
			}
		};
		try
		{
			api.deleteMe(token, body, callback);
		}
		catch (ServerApi.NotConnectedException e)
		{
			log.debug(e.getMessage());
			finish(new Result(Outcome.NOT_CONNECTED, -1), done);
		}
		catch (RuntimeException e)
		{
			log.warn("Couldn't start data deletion", e);
			finish(new Result(Outcome.FAILED, -1), done);
		}
	}

	/**
	 * Done. After a deletion (or when there was nothing to delete): disconnect, switch to a new install id without a
	 * token and drop anything queued. When the key was lost: disconnect and drop the queue too (the player asked for
	 * their data to go), but keep the install id, which the message shows. After a failure, or when nothing was sent
	 * (not connected): change nothing and resume uploading.
	 */
	private void finish(Result result, Consumer<Result> done)
	{
		try
		{
			if (unchanged(result.outcome))
			{
				uploader.resume();
			}
			else
			{
				disconnect.run();
				if (result.outcome != Outcome.KEY_LOST)
				{
					identity.rotateInstallId();
				}
				uploader.clear();
				uploader.resume();
			}
		}
		catch (RuntimeException e)
		{
			log.warn("Data deletion: couldn't update local state", e);
		}
		finally
		{
			running.set(false);
		}
		if (!unchanged(result.outcome))
		{
			try
			{
				List<String> lost = new ArrayList<>(identity.lostInstallIds());
				lost.remove(result.installId);
				if (!lost.isEmpty())
				{
					result = new Result(result.outcome, result.code, result.installId, lost);
				}
			}
			catch (RuntimeException e)
			{
				log.warn("Data deletion: couldn't read older install ids", e);
			}
		}
		if (cancelled)
		{
			return;
		}
		try
		{
			done.accept(result);
		}
		catch (RuntimeException e)
		{
			log.warn("Data deletion callback failed", e);
		}
	}

	/** Nothing changed on the server (a failure, or not sent at all), so nothing changes here either. */
	private static boolean unchanged(Outcome outcome)
	{
		return outcome == Outcome.FAILED || outcome == Outcome.NOT_CONNECTED;
	}

	/** What to tell the player afterwards. */
	static String message(Result r)
	{
		String m = outcomeMessage(r);
		if (unchanged(r.outcome) || r.lostIds.isEmpty())
		{
			return m;
		}
		return m + " This computer also shared data under older install ids whose key was lost ("
			+ String.join(", ", r.lostIds) + "), which can't be deleted from here. To have it removed, send "
			+ (r.lostIds.size() == 1 ? "that id" : "those ids") + " to the contact on the privacy notice "
			+ "(Privacy > Privacy notice).";
	}

	private static String outcomeMessage(Result r)
	{
		switch (r.outcome)
		{
			case DELETED:
				return "Your shared data was deleted. The plugin is now disconnected.";
			case PENDING:
				return "Your shared data is being deleted; the server finishes this in the background. "
					+ "The plugin is now disconnected.";
			case NOTHING:
				return "The server says this computer's shared data was already deleted, so there was nothing to delete. "
					+ "The plugin is now disconnected.";
			case KEY_LOST:
				return "This computer's key for the server was lost or replaced, so the plugin can't prove the shared data "
					+ "is yours, and nothing was deleted. To have it removed, send your install id " + r.installId
					+ " to the contact on the privacy notice (Privacy > Privacy notice). The plugin is now disconnected.";
			case NOT_CONNECTED:
				return "Nothing was deleted: the plugin only contacts the server while connected. "
					+ "Connect, then try again.";
			default:
				return r.code < 0
					? "Couldn't reach the Hardcore World Tool Kit server. Try again later."
					: "Couldn't delete your data (server error " + r.code + "). Try again later.";
		}
	}
}

package com.hardcoreworldtoolkit;

import java.util.regex.Matcher;
import java.util.regex.Pattern;
import lombok.Value;
import net.runelite.client.util.Text;

/** A Hardcore death broadcast: its text (read by the server) and the victim (to spot the player's own death). */
@Value
class DeathBroadcast
{
	/** The total level: 1000 and up shows as "1K" (or "1.2K"). */
	private static final String LEVEL = "\\((\\d+(?:\\.\\d+)?k?)\\)";
	private static final Pattern KILLED = Pattern.compile(".+? killed (.+?)" + LEVEL + " with an? \\d+ damage hit.*", Pattern.CASE_INSENSITIVE);
	private static final Pattern DIED = Pattern.compile("(.+?)" + LEVEL + " was killed by an? \\d+ damage hit.*", Pattern.CASE_INSENSITIVE);

	String text;
	String victim;

	static DeathBroadcast parse(String message)
	{
		String m = Text.removeTags(message).replace('\u00a0', ' ').trim();
		Matcher k = KILLED.matcher(m);
		Matcher d = DIED.matcher(m);
		if (!k.matches() && !d.matches())
		{
			return null;
		}
		return new DeathBroadcast(m, (k.matches() ? k.group(1) : d.group(1)).replaceAll("@[a-z_]+@", ""));
	}

	int level()
	{
		Matcher m = Pattern.compile(Pattern.quote(victim) + LEVEL, Pattern.CASE_INSENSITIVE).matcher(text);
		if (!m.find())
		{
			return -1;
		}
		String v = m.group(1).toLowerCase();
		return v.endsWith("k") ? (int) (Double.parseDouble(v.substring(0, v.length() - 1)) * 1000) : Integer.parseInt(v);
	}
}

package com.hardcoreworldtoolkit;

import com.google.gson.JsonObject;
import java.io.IOException;
import java.util.List;
import java.util.concurrent.ThreadLocalRandom;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.util.Text;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.Response;

/** Reports deaths: the text of each death broadcast, plus the tile of the player's own death (and its killer). */
class DeathReporter
{
	private static final long OWN_WAIT = 60;
	/** Everyone online sees each broadcast: each player sends about one in this many (always their own death). */
	static final int REPORT_ONE_IN = 15;
	private static final Callback IGNORE = new Callback()
	{
		@Override
		public void onFailure(Call call, IOException e)
		{
		}

		@Override
		public void onResponse(Call call, Response response)
		{
			response.close();
		}
	};

	private final ServerApi api;
	private final ServerIdentity identity;
	private final int oneIn;
	/** A monster that stopped attacking this many game ticks (0.6 s each) before the death still counts as the killer. */
	static final int RECENT_TICKS = 10;
	private WorldPoint ownTile;
	private String ownKiller;
	private long ownAt;

	/** oneIn: send about one in this many broadcasts of other players' deaths (1: every one). */
	DeathReporter(ServerApi api, ServerIdentity identity, int oneIn)
	{
		this.api = api;
		this.identity = identity;
		this.oneIn = Math.max(1, oneIn);
	}

	/** The player's own death: its tile, and the monster that was attacking them (null: none seen, or a player was). */
	synchronized void ownDeath(WorldPoint tile, String killer, long now)
	{
		ownTile = tile;
		ownKiller = killer;
		ownAt = now;
	}

	synchronized void broadcast(DeathBroadcast d, String me, long now)
	{
		boolean own = ownTile != null && me != null && now - ownAt <= OWN_WAIT
			&& Text.standardize(me).equals(Text.standardize(d.getVictim()));
		if (own)
		{
			send(d.getText(), ownTile, null, now); // the broadcast names the killer
			ownTile = null;
			ownKiller = null;
		}
		else if (ThreadLocalRandom.current().nextInt(oneIn) == 0)
		{
			send(d.getText(), null, null, now);
		}
	}

	/** An own death with no broadcast: sent with the tile and the monster that was attacking, if one was. */
	synchronized void tick(long now)
	{
		if (ownTile != null && now - ownAt > OWN_WAIT)
		{
			send(null, ownTile, ownKiller, ownAt);
			ownTile = null;
			ownKiller = null;
		}
	}

	private void send(String text, WorldPoint tile, String killer, long ts)
	{
		String token = identity.token();
		if (token == null)
		{
			return;
		}
		api.postDeath(token, body(identity.installId(), text, tile, killer, ts), IGNORE);
	}

	/**
	 * One report: the broadcast's text, plus the tile of the player's own death. An own death no broadcast named carries
	 * the monster that was attacking instead (a monster's name only, never a player's).
	 */
	static JsonObject body(String installId, String text, WorldPoint tile, String killer, long ts)
	{
		JsonObject b = new JsonObject();
		b.addProperty("installId", installId);
		b.addProperty("ts", ts);
		b.addProperty("text", text);
		if (tile != null)
		{
			b.addProperty("own", true);
			b.addProperty("x", tile.getX());
			b.addProperty("y", tile.getY());
			b.addProperty("plane", tile.getPlane());
			if (text == null && killer != null)
			{
				b.addProperty("killer", killer);
			}
		}
		return b;
	}

	/**
	 * What killed the player: a monster attacking them when they died (the one that last turned on them, when several
	 * were), else the last one that did within RECENT_TICKS. Null when a player was attacking them: player names come
	 * from the broadcasts only, never with a tile.
	 */
	static String killerOf(List<String> attackingNow, boolean playerAttacking, String last, int lastTick, int tick)
	{
		if (playerAttacking)
		{
			return null;
		}
		if (last != null && attackingNow.contains(last))
		{
			return last;
		}
		if (!attackingNow.isEmpty())
		{
			return attackingNow.get(0);
		}
		return last != null && tick - lastTick <= RECENT_TICKS ? last : null;
	}
}

package com.hardcoreworldtoolkit;

import java.util.Locale;
import java.util.Optional;
import java.util.function.Consumer;
import lombok.Value;
import net.runelite.api.events.CommandExecuted;
import net.runelite.client.eventbus.Subscribe;

/**
 * The {@code ::hwtk} developer command: a fresh-install preview of the panel and re-arming the one-time hints.
 * Registered on the event bus only in developer mode; normal installs never see it. Runs on the client thread.
 */
final class DevCommands
{
	static final String COMMAND = "hwtk";
	static final String USAGE = "Usage: ::hwtk fresh | fresh off | hints";

	enum Action
	{
		/** Show the panel as a brand-new install would (UI only; nothing real changes). */
		FRESH_ON,
		/** Back to the real state. */
		FRESH_OFF,
		/** Re-arm the one-time chat hint and show it now. */
		HINTS,
	}

	@Value
	static class Command
	{
		Action action;
	}

	/** What the command drives. */
	interface Target
	{
		void freshPreview(boolean on);

		void resetHints();
	}

	private final Target target;
	/** Shows a line in the local chatbox only. */
	private final Consumer<String> chat;

	DevCommands(Target target, Consumer<String> chat)
	{
		this.target = target;
		this.chat = chat;
	}

	@Subscribe
	public void onCommandExecuted(CommandExecuted e)
	{
		if (COMMAND.equalsIgnoreCase(e.getCommand()))
		{
			run(e.getArguments());
		}
	}

	/** Run {@code ::hwtk <args>}. Client thread. */
	void run(String[] args)
	{
		Optional<Command> parsed = parse(args);
		if (!parsed.isPresent())
		{
			chat.accept(USAGE);
			return;
		}
		switch (parsed.get().getAction())
		{
			case FRESH_ON:
				target.freshPreview(true);
				chat.accept("Fresh-install preview on (panel only; nothing real changed). ::hwtk fresh off to end it.");
				break;
			case FRESH_OFF:
				target.freshPreview(false);
				chat.accept("Fresh-install preview off.");
				break;
			case HINTS:
				target.resetHints();
				break;
		}
	}

	/** {@code fresh [on|off]} or {@code hints}; case-insensitive. */
	static Optional<Command> parse(String[] args)
	{
		if (args == null || args.length == 0)
		{
			return Optional.empty();
		}
		String first = args[0].toLowerCase(Locale.ROOT);
		String second = args.length > 1 ? args[1].toLowerCase(Locale.ROOT) : null;
		switch (first)
		{
			case "fresh":
				if (args.length > 2)
				{
					return Optional.empty();
				}
				if (second == null || second.equals("on"))
				{
					return Optional.of(new Command(Action.FRESH_ON));
				}
				return second.equals("off") ? Optional.of(new Command(Action.FRESH_OFF)) : Optional.empty();
			case "hints":
				return args.length == 1 ? Optional.of(new Command(Action.HINTS)) : Optional.empty();
			default:
				return Optional.empty();
		}
	}
}

package com.hardcoreworldtoolkit;

import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import java.util.function.Predicate;
import java.util.function.Supplier;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import lombok.Value;

/**
 * Parses the in-game Grand Exchange History tab and works out which rows are new since we last read it.
 * The tab lists completed trades newest-first with no timestamps.
 */
public final class GeHistory
{
	private static final Pattern NUMBER = Pattern.compile("\\d[\\d,]*");
	private static final Pattern TAGS = Pattern.compile("<[^>]*>");

	private GeHistory()
	{
	}

	/** The bits of a history-list widget we care about. */
	@Value
	public static class Cell
	{
		String text;
		int itemId;
		int itemQty;
	}

	@Value
	public static class Entry
	{
		boolean buy;
		int itemId;
		int qty;
		long total;

		String signature()
		{
			return OfferTracker.signature(buy, itemId, qty, total);
		}
	}

	/**
	 * Walk the list's children in order, collecting a side label ("Bought"/"Sold"), an item, and a coin total into
	 * each entry. Order-tolerant, so small layout changes in the interface don't break it.
	 */
	public static List<Entry> parse(List<Cell> cells)
	{
		List<Entry> out = new ArrayList<>();
		Boolean buy = null;
		int itemId = -1, qty = 0;
		long total = -1;

		for (Cell c : cells)
		{
			String text = c.text == null ? "" : TAGS.matcher(c.text.replace("<br>", " ")).replaceAll("").trim();
			if (c.itemId > 0)
			{
				itemId = c.itemId;
				qty = c.itemQty;
			}
			else if (text.startsWith("Bought"))
			{
				buy = true;
			}
			else if (text.startsWith("Sold"))
			{
				buy = false;
			}
			else if (text.toLowerCase(Locale.ROOT).contains("coin"))
			{
				Matcher m = NUMBER.matcher(text);
				if (m.find())
				{
					try
					{
						total = Long.parseLong(m.group().replace(",", ""));
					}
					catch (NumberFormatException e)
					{
						total = -1;
					}
				}
			}

			if (buy != null && itemId > 0 && qty > 0 && total > 0)
			{
				out.add(new Entry(buy, itemId, qty, total));
				buy = null;
				itemId = -1;
				qty = 0;
				total = -1;
			}
		}
		return out;
	}

	/**
	 * Given the previous and current list of row signatures (both newest-first), return how many rows at the top of
	 * {@code current} are new. Finds the smallest offset at which the rest of {@code current} lines up with the
	 * start of {@code previous}.
	 */
	public static int countNew(List<String> previous, List<String> current)
	{
		if (previous == null || previous.isEmpty())
		{
			return current.size();
		}
		for (int k = 0; k < current.size(); k++)
		{
			int overlap = Math.min(current.size() - k, previous.size());
			boolean match = true;
			for (int j = 0; j < overlap; j++)
			{
				if (!current.get(k + j).equals(previous.get(j)))
				{
					match = false;
					break;
				}
			}
			if (match)
			{
				return k;
			}
		}
		return current.size();
	}

	/**
	 * Build events for the {@code fresh} new rows at the top of {@code entries}, oldest first so matching against
	 * offers tracked live happens in trade order. Rows {@code seenLive} accepts were already recorded live and are
	 * skipped.
	 */
	public static List<TradeEvent> newEvents(List<Entry> entries, int fresh, Predicate<String> seenLive, long ts, int world,
		Supplier<String> idGen)
	{
		List<TradeEvent> events = new ArrayList<>();
		for (int i = fresh - 1; i >= 0; i--)
		{
			Entry en = entries.get(i);
			if (seenLive.test(en.signature()))
			{
				continue;
			}
			events.add(TradeEvent.builder()
				.id(idGen.get())
				.kind(TradeEvent.HISTORY)
				.side(TradeEvent.sideOf(en.isBuy()))
				.itemId(en.getItemId())
				.qty(en.getQty())
				.price(TradeEvent.avgPrice(en.getTotal(), en.getQty()))
				.total(en.getTotal())
				.ts(ts)
				.late(true)
				.world(world)
				.build());
		}
		return events;
	}
}

package com.hardcoreworldtoolkit;

import net.runelite.client.util.QuantityFormatter;
import net.runelite.client.util.Text;

/**
 * The Hardcore price line in the GE offer setup's description text (pure).
 * <p>
 * The game builds that text in a script that hands it to RuneLite's "geBuyExamineText" / "geSellExamineText"
 * callbacks before setting it: examine text, then (when there is one) the fee line last, with an info icon placed
 * after the last line. Core's GE plugin appends its own lines before the fee. This adds one line marked
 * {@link #MARKER}, also before the fee, and removes any earlier one first, so applying it twice never duplicates it
 * and nothing else in the text changes.
 */
final class GePriceText
{
	static final String MARKER = "<col=ff981f>HC</col>";
	private static final String BR = "<br>";
	/** Visible characters a line may have before the bid / ask part is dropped. */
	static final int MAX_VISIBLE = 60;

	private GePriceText()
	{
	}

	/**
	 * {@code out} with {@code line} added: before {@code fee} when the text ends with it (so the fee stays last and its
	 * icon stays in place), otherwise as a new last line. An earlier HC line is replaced.
	 *
	 * @param out  the text the script will set
	 * @param fee  the fee text the script got, or empty
	 * @param line from {@link #line}
	 */
	static String insert(String out, String fee, String line)
	{
		String base = strip(out == null ? "" : out);
		if (fee != null && !fee.isEmpty() && base.endsWith(fee))
		{
			return base.substring(0, base.length() - fee.length()) + line + BR + fee;
		}
		return base.isEmpty() ? line : base + BR + line;
	}

	/** {@code text} without any HC line (and the line break that introduced it). */
	static String strip(String text)
	{
		String s = text;
		int at;
		while ((at = s.indexOf(MARKER)) >= 0)
		{
			int end = s.indexOf(BR, at);
			boolean afterBreak = at >= BR.length() && s.startsWith(BR, at - BR.length());
			if (afterBreak)
			{
				// "...<br>HC ...<br>rest" -> "...<br>rest"; "...<br>HC ..." -> "..."
				s = s.substring(0, at - BR.length()) + (end < 0 ? "" : s.substring(end));
			}
			else
			{
				// The HC line is first: drop it and its trailing break.
				s = s.substring(0, at) + (end < 0 ? "" : s.substring(end + BR.length()));
			}
		}
		return s;
	}

	/** The line for an item's market summary, e.g. "HC last 1.25M/1.24M · bid 1.23M ask 1.26M · 523/24h". */
	static String line(MarketData.Summary s)
	{
		if (s == null)
		{
			return MARKER + " no trades yet";
		}
		return line(s.getLastBuy(), s.getLastSell(), s.getBestBid(), s.getBestAsk(), s.getVol24());
	}

	/** The line stays within {@link #MAX_VISIBLE} visible characters: when it would be longer, the bid / ask part goes. */
	static String line(Long lastBuy, Long lastSell, Long bestBid, Long bestAsk, long vol24)
	{
		if (lastBuy == null && lastSell == null && bestBid == null && bestAsk == null && vol24 <= 0)
		{
			return MARKER + " no trades yet";
		}
		String last = " last " + gp(lastBuy) + "/" + gp(lastSell);
		String book = " · bid " + gp(bestBid) + " ask " + gp(bestAsk);
		String vol = " · " + QuantityFormatter.quantityToStackSize(Math.max(0, vol24)) + "/24h";
		String full = MARKER + last + book + vol;
		return fits(full) ? full : MARKER + last + vol;
	}

	private static boolean fits(String line)
	{
		return Text.removeTags(line).length() <= MAX_VISIBLE;
	}

	/** Compact gp ("1.25M", "9,999"), or "-" when unknown. */
	static String gp(Long v)
	{
		return v == null ? "-" : QuantityFormatter.quantityToStackSize(v);
	}
}

