	/**
	 * One local log line: the event plus "acct", the hashed account id (when known), so per-account numbers can be
	 * rebuilt from the log. Reading a line back as a TradeEvent ignores "acct".
	 */
	static JsonObject logLine(Gson gson, TradeEvent ev, String accountId)
	{
		JsonObject o = gson.toJsonTree(ev).getAsJsonObject();
		if (accountId != null)
		{
			o.addProperty("acct", accountId);
		}
		return o;
	}

	/** Must be called on the client thread. */
	private TradeEvent withName(TradeEvent ev)
	{
		return ev.toBuilder().name(itemManager.getItemComposition(ev.getItemId()).getName()).build();
	}

	/** Older log lines have no item name. Must be called on the client thread. */
	private TradeEvent withNameIfMissing(TradeEvent ev)
	{
		return ev.getName() == null ? withName(ev) : ev;
	}

	private void notifyMyTradesChanged()
	{
		SwingUtilities.invokeLater(() ->
		{
			HardcoreWorldToolKitPanel p = panel;
			if (p != null)
			{
				p.onMyTradesChanged();
			}
		});
	}

	/** Client thread only. Captures the name now; the icon is only referenced and gets PNG-encoded during flush. */
	private void queueItemInfo(TradeUploader up, int itemId)
	{
		if (!up.needsItem(itemId))
		{
			return;
		}
		String name = itemManager.getItemComposition(itemId).getName();
		AsyncBufferedImage img = itemManager.getImage(itemId);
		up.addItem(itemId, name, img, geLimit(itemId));
		img.onLoaded(() -> up.setIcon(itemId, img));
	}

	/**
	 * The item's GE buy limit from RuneLite's item stats (an in-memory lookup, no IO), or 0 when unknown. The server
	 * uses it to reject buys over the 4-hour limit; it only accepts the value from trusted sources. Client thread.
	 */
	private int geLimit(int itemId)
	{
		ItemStats stats = itemManager.getItemStats(itemId);
		return stats != null && stats.getGeLimit() > 0 ? stats.getGeLimit() : 0;
	}

	/**
	 * Load the local trade log so "My trades" survives restarts. Runs off the client thread.
	 *
	 * @param session {@link MyTrades#session()} when the plugin started; if the plugin has been stopped since, the
	 *                result is dropped rather than merged into a later session
	 */
	private void loadLocalLog(int session)
	{
		List<TradeEvent> newest;
		try
		{
			// Only the newest shown events, read from the end of the newest files; the rest of the log isn't parsed.
			newest = LocalTradeLog.readNewest(getPluginDirectory(), gson, MyTrades.MAX);
		}
		catch (IOException ex)
		{
			log.debug("Couldn't read local trade log", ex);
			return;
		}
		if (newest.isEmpty())
		{
			return;
		}

		// Item names are filled in on the client thread. Item definitions only exist once the client has loaded the game
		// cache (login screen or later); at startup this runs earlier, so retry on each tick until then.
		clientThread.invokeLater(() ->
		{
			if (client.getGameState().getState() < GameState.LOGIN_SCREEN.getState())
			{
				return false;
			}
			if (myTrades.mergeLoaded(session, newest, this::withNameIfMissing))
			{
				notifyMyTradesChanged();
			}
			else
			{
				log.debug("Dropped a local trade log load from a previous session");
			}
			return true;
		});
	}

	private static BufferedImage buildIcon()
	{
		return SkullIcon.draw(16, SkullIcon.BONE);
	}

	/** @return true if the lines were written */
	private boolean appendLocalLog(YearMonth month, List<String> lines)
	{
		try
		{
			LocalTradeLog.append(getPluginDirectory(), month, lines);
			return true;
		}
		catch (IOException ex)
		{
			log.warn("Couldn't write local trade log", ex);
			return false;
		}
	}

	/**
	 * Your open offers, sent to the panel when they changed so the item view can show them at once. Client thread.
	 *
	 * @param t the tracker, or null when logged out / not on a Hardcore World (no offers)
	 */
	private void publishOffers(OfferTracker t)
	{
		List<ActiveOffer> offers = t == null ? Collections.emptyList()
			: ActiveOffer.fromTracker(t, id -> itemManager.getItemComposition(id).getName());
		if (offers.equals(publishedOffers))
		{
			return;
		}
		publishedOffers = offers;
		OfferMarketWatch watch = offerWatch;
		if (watch != null)
		{
			watch.setOffers(offers);
		}
		SwingUtilities.invokeLater(() ->
		{
			HardcoreWorldToolKitPanel p = panel;
			if (p != null)
			{
				p.onOffersChanged(offers);
			}
		});
	}

	/** The server accepted trades of these items (OkHttp thread): let the item view fetch the new market data. */
	private void onUploaded(Set<Integer> itemIds)
	{
		SwingUtilities.invokeLater(() ->
		{
			HardcoreWorldToolKitPanel p = panel;
			if (p != null)
			{
				p.onUploaded(itemIds);
			}
		});
	}

	/**
	 * Upload in about {@link #FLUSH_SOON_SECONDS} instead of at the next scheduled flush, so a fill shows up in the
	 * market data quickly. Requests while one is pending are merged into it.
	 */
	private void requestFlushSoon()
	{
		ScheduledFuture<?> pending = soonFlush.get();
		if (pending != null && !pending.isDone())
		{
			return;
		}
		ScheduledFuture<?> next = executor.schedule(() -> flushSoon(1), FLUSH_SOON_SECONDS, TimeUnit.SECONDS);
		if (!soonFlush.compareAndSet(pending, next))
		{
			// Another request scheduled one first.
			next.cancel(false);
		}
	}

	/** The one-shot upload; if a request is still running, try again a little later (a few times at most). */
	private void flushSoon(int attempt)
	{
		if (tracker == null)
		{
			// Stopped meanwhile; shutDown already flushed.
			return;
		}
		TradeUploader up = uploader;
		if (up != null && up.isInFlight() && attempt < FLUSH_SOON_TRIES)
		{
			soonFlush.set(executor.schedule(() -> flushSoon(attempt + 1), FLUSH_SOON_SECONDS, TimeUnit.SECONDS));
			return;
		}
		// Clear first, so a fill recorded during this upload schedules its own.
		soonFlush.set(null);
		scheduledFlush();
	}

	/** Whether the side panel is open; any thread. */
	private boolean panelShown()
	{
		HardcoreWorldToolKitPanel p = panel;
		return p != null && p.isPanelActive();
	}

	/** The periodic offer check (executor). Only starts a request when due; catches everything to keep the task alive. */
	private void checkOffers()
	{
		try
		{
			OfferMarketWatch w = offerWatch;
			if (w != null)
			{
				w.refresh(false);
			}
		}
		catch (RuntimeException ex)
		{
			warnOnce("Offer check failed", ex);
		}
	}

	/** Failures of the repeating tasks already logged as a warning; the next ones go to debug. */
	private final Set<String> warned = ConcurrentHashMap.newKeySet();

	/** A scheduled task failed: a warning the first time, debug after that (it runs every few seconds). */
	private void warnOnce(String what, RuntimeException ex)
	{
		if (warned.add(what))
		{
			log.warn(what, ex);
		}
		else
		{
			log.debug("{}: {}", what, ex.toString());
		}
	}

	/** The scheduled upload. Catches everything: an exception would cancel the fixed-delay task for the session. */
	private void scheduledFlush()
	{
		try
		{
			flush();
			DeathReporter d = deaths;
			if (d != null && config.connected() && config.shareDeaths())
			{
				d.tick(now());
			}
		}
		catch (RuntimeException ex)
		{
			warnOnce("Trade upload flush failed", ex);
		}
		saveSpool();
	}

	/** Write the uploads still waiting to the spool file (or remove it). Executor thread. */
	private void saveSpool()
	{
		UploadSpool sp = spool;
		TradeUploader up = uploader;
		if (sp != null && up != null)
		{
			try
			{
				sp.save(up.pending());
			}
			catch (RuntimeException ex)
			{
				warnOnce("Couldn't save pending uploads", ex);
			}
		}
	}

	/**
	 * Enabled while logged in on a Hardcore World: the game sends no offer events for slots that haven't changed, so compare
	 * all 8 with the saved state now. Whatever differs happened while the plugin wasn't watching, so it is recorded as
	 * late (never as a live trade at this moment). Slots the game shows as empty are cleared. Client thread.
	 */
	private void reconcileSlots()
	{
		OfferTracker t = tracker;
		if (!isTrackedWorld() || !ensureProfileLoaded(t))
		{
			return;
		}
		GrandExchangeOffer[] offers = client.getGrandExchangeOffers();
		if (offers == null)
		{
			return;
		}
		long ts = now();
		for (int slot = 0; slot < offers.length && slot < OfferTracker.SLOTS; slot++)
		{
			GrandExchangeOffer offer = offers[slot];
			if (offer == null)
			{
				continue;
			}
			List<TradeEvent> events = t.update(slot, OfferTracker.Snapshot.of(offer), true, ts, HARDCORE_ECONOMY);
			store.saveSlot(t, slot);
			if (!events.isEmpty())
			{
				store.saveCompleted(t);
				record(events);
			}
		}
		publishOffers(t);
	}

	private void flush()
	{
		TradeUploader up = uploader;
		if (up == null)
		{
			return;
		}
		if (!shareEnabled())
		{
			up.clear();
			return;
		}
		up.flush();
	}

	/** Your offers that are still open, serialized now since the slot state keeps changing. Client thread only. */
	private List<JsonObject> buildOpenOffers(OfferTracker t, TradeUploader up)
	{
		List<JsonObject> offers = new ArrayList<>();
		for (int slot = 0; slot < OfferTracker.SLOTS; slot++)
		{
			OfferTracker.SlotState s = t.getSlot(slot);
			if (s == null || s.getStatus() != OfferTracker.Status.ACTIVE || s.getSold() >= s.getTotalQty())
			{
				continue;
			}
			offers.add(TradeUploader.offerJson(slot, s));
			queueItemInfo(up, s.getItemId());
		}
		return offers;
	}

	/* ---------------------------------------------------- persistence */

	/**
	 * Load slot state for the current account's RuneLite profile.
	 *
	 * @param t the tracker, read once by the caller (null after shutDown)
	 */
	private boolean ensureProfileLoaded(OfferTracker t)
	{
		if (t == null || !store.ensureLoaded(t))
		{
			return false;
		}
		String profile = store.loadedProfile();
		if (profile != null && !profile.equals(announcedProfile))
		{
			announceAccount(profile);
			publishOffers(t);
		}
		return true;
	}

	/* ---------------------------------------------------------- helpers */

	/** Only the Hardcore Worlds, which the world list marks with {@link WorldType#HARDCORE_MAIN}. */
	private boolean isTrackedWorld()
	{
		return devAnyWorld || client.getWorldType().contains(WorldType.HARDCORE_MAIN);
	}

	private boolean deathsOn()
	{
		return config.connected() && config.shareDeaths() && isTrackedWorld();
	}

	private static long now()
	{
		return Instant.now().getEpochSecond();
	}
}

package com.hardcoreworldtoolkit;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.io.BufferedReader;
import java.io.BufferedWriter;
import java.io.IOException;
import java.nio.file.AtomicMoveNotSupportedException;
import java.nio.file.StandardCopyOption;
import java.nio.file.StandardOpenOption;
import java.util.HashMap;
import java.util.Map;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.util.Filepath;
import okhttp3.HttpUrl;

/**
 * Where this computer's install id and install token live: a small JSON file in the plugin's data folder, not the
 * RuneLite config. ConfigManager logs every value it saves at debug level (so a token would end up in client.log with
 * --debug), broadcasts it to all plugins in a ConfigChanged event, and syncs the config to RuneLite's servers for
 * players with a RuneLite account; a synced install id would also make two PCs fight over one id.
 * <p>
 * The file is read once (lazily) and cached; every change is written straight away (temp file, then rename). When the
 * folder can't be written, the values stay in memory for this session. Values are never logged.
 * Not thread-safe on its own: {@link InstallIdentity} serialises all calls.
 */
@Slf4j
final class IdentityFile implements InstallIdentity.Store
{
	static final String FILE_NAME = "server-identity.json";

	private final ProfitStore.Dir dir;
	private final Gson gson;
	/** {@link #FILE_NAME} for the production server, another name for any other server ({@link #fileNameFor}). */
	private volatile String fileName = FILE_NAME;
	private Map<String, String> values;
	/**
	 * The file is there but couldn't be read (locked by another program, no permission): this session works from memory
	 * and never writes over it, so the install keeps its id and key for the next start.
	 */
	private boolean readOnly;

	IdentityFile(ProfitStore.Dir dir, Gson gson)
	{
		this.dir = dir;
		this.gson = gson;
	}

	/**
	 * The file for {@code server}: the production server keeps {@value #FILE_NAME}, any other server (the local one the
	 * developer-mode client uses) gets a file of its own. A test server that refuses the real token, and already knows
	 * the install id, would otherwise make the plugin switch the real install to a new id.
	 */
	static String fileNameFor(HttpUrl server, HttpUrl production)
	{
		if (server.host().equals(production.host()) && server.port() == production.port())
		{
			return FILE_NAME;
		}
		return "server-identity-" + (server.host() + "-" + server.port()).replaceAll("[^A-Za-z0-9.-]", "_") + ".json";
	}

	/** Use the file {@code name} (from {@link #fileNameFor}) in the plugin folder. Call before the identity is used. */
	void useFileName(String name)
	{
		if (!name.equals(fileName))
		{
			fileName = name;
			values = null;
			readOnly = false;
		}
	}

	@Override
	public String get(String key)
	{
		return load().get(key);
	}

	@Override
	public void set(String key, String value)
	{
		load().put(key, value);
		save();
	}

	@Override
	public void unset(String key)
	{
		if (load().remove(key) != null)
		{
			save();
		}
	}

	/** True once the file was read (so a caller on the EDT can avoid triggering the read). */
	boolean loaded()
	{
		return values != null;
	}

	private Map<String, String> load()
	{
		if (values != null)
		{
			return values;
		}
		values = new HashMap<>();
		Filepath file = null;
		try
		{
			file = dir.get().joinSegment(fileName);
		}
		catch (IOException | RuntimeException ex)
		{
			log.debug("Couldn't open the plugin data folder: {}", ex.getClass().getSimpleName());
		}
		if (file != null && file.isFile())
		{
			// Read first, then parse: Gson reports a failed read as a syntax error, and the two must differ here.
			String text = null;
			try
			{
				text = readText(file);
			}
			catch (IOException | RuntimeException ex)
			{
				// Unreadable right now (locked by another program, no permission), not broken: don't replace it with a
				// new id, which would lose the key for good.
				log.debug("Couldn't read the install identity file: {}", ex.getClass().getSimpleName());
				readOnly = true;
			}
			if (text != null)
			{
				try
				{
					JsonObject o = gson.fromJson(text, JsonObject.class);
					if (o != null)
					{
						for (String k : new String[]{InstallIdentity.KEY_INSTALL_ID, InstallIdentity.KEY_INSTALL_TOKEN,
							InstallIdentity.KEY_LOST_IDS})
						{
							JsonElement e = o.get(k);
							if (e != null && e.isJsonPrimitive())
							{
								values.put(k, e.getAsString());
							}
						}
					}
				}
				catch (RuntimeException ex)
				{
					// Not JSON: nothing in it can be used, so it is replaced on the next save.
					log.debug("Couldn't parse the install identity file: {}", ex.getClass().getSimpleName());
				}
			}
		}
		return values;
	}

	private static String readText(Filepath file) throws IOException
	{
		StringBuilder sb = new StringBuilder();
		char[] buf = new char[1024];
		try (BufferedReader r = file.openBufferedReader())
		{
			int n;
			while ((n = r.read(buf)) != -1)
			{
				sb.append(buf, 0, n);
			}
		}
		return sb.toString();
	}

	/** Writes the values (temp file, then rename). False when the folder can't be written; never logs a value. */
	private boolean save()
	{
		if (readOnly)
		{
			return false;
		}
		try
		{
			Filepath d = dir.get();
			if (!d.exists())
			{
				d.createDirectories();
			}
			JsonObject o = new JsonObject();
			for (Map.Entry<String, String> e : values.entrySet())
			{
				o.addProperty(e.getKey(), e.getValue());
			}
			String name = fileName;
			Filepath file = d.joinSegment(name);
			Filepath tmp = d.joinSegment(name + ".tmp");
			try (BufferedWriter w = tmp.openBufferedWriter(StandardOpenOption.CREATE, StandardOpenOption.TRUNCATE_EXISTING,
				StandardOpenOption.WRITE))
			{
				gson.toJson(o, w);
			}
			try
			{
				tmp.moveTo(file, StandardCopyOption.REPLACE_EXISTING, StandardCopyOption.ATOMIC_MOVE);
			}
			catch (AtomicMoveNotSupportedException ex)
			{
				tmp.moveTo(file, StandardCopyOption.REPLACE_EXISTING);
			}
			return true;
		}
		catch (IOException | RuntimeException ex)
		{
			log.debug("Couldn't save the install identity file: {}", ex.getClass().getSimpleName());
			return false;
		}
	}
}

package com.hardcoreworldtoolkit;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.io.IOException;
import java.util.function.Consumer;
import lombok.extern.slf4j.Slf4j;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.Response;
import okhttp3.ResponseBody;

/**
 * Gets an install token from the collection server ({@link ServerApi#postRegister}, POST v1/register {installId}) and
 * stores it in the {@link ServerIdentity}. Asynchronous (OkHttp enqueue); the callback runs exactly once, on an OkHttp
 * thread, or on the caller's thread when the request isn't sent (not connected) or can't even be started.
 * <p>
 * The token is a secret for this install: it is never logged, and neither are response bodies or request headers.
 * Only status codes are logged, at debug level.
 */
@Slf4j
class InstallAuth
{
	/** The server's 409 error for an install id whose data was deleted (vs "installId already registered"). */
	static final String DELETED_ERROR = "installId deleted";

	enum Status
	{
		/** A token was issued; {@link Result#getToken()} has it. */
		OK,
		/**
		 * 409 "installId already registered": another token holds this install id (this PC's was lost or replaced, or
		 * the id isn't ours). Only when not rotating.
		 */
		CONFLICT,
		/** 409 "installId deleted": this install id's data was deleted already. Only when not rotating. */
		DELETED,
		/** Not sent: the plugin isn't connected ({@link ServerApi.NotConnectedException}). */
		NOT_CONNECTED,
		/** Rate limited, server error, bad response or network failure. */
		FAILED
	}

	/** The outcome of a registration. Deliberately has no toString, so the token can't end up in a log line. */
	static final class Result
	{
		private final Status status;
		private final String installId;
		private final String token;
		/** HTTP status, or -1 for a network failure. */
		private final int code;

		Result(Status status, String installId, String token, int code)
		{
			this.status = status;
			this.installId = installId;
			this.token = token;
			this.code = code;
		}

		Status getStatus()
		{
			return status;
		}

		/** The install id the token was issued for (after any rotation). */
		String getInstallId()
		{
			return installId;
		}

		String getToken()
		{
			return token;
		}

		int getCode()
		{
			return code;
		}
	}

	private final ServerApi api;
	private final Gson gson;
	private final ServerIdentity identity;

	InstallAuth(ServerApi api, Gson gson, ServerIdentity identity)
	{
		this.api = api;
		this.gson = gson;
		this.identity = identity;
	}

	/**
	 * Register the current install id.
	 *
	 * @param rotateOnConflict on 409, switch to a new random install id and try once more (uploads); when false a
	 *                         409 is reported as {@link Status#CONFLICT} (deleting data: the id is gone or not ours)
	 * @param done             called exactly once with the outcome
	 */
	void register(boolean rotateOnConflict, Consumer<Result> done)
	{
		String installId = identity.installId();
		JsonObject body = new JsonObject();
		body.addProperty("installId", installId);
		Callback callback = new Callback()
		{
			@Override
			public void onFailure(Call c, IOException e)
			{
				log.debug("Registration failed: {}", e.getClass().getSimpleName());
				deliver(done, new Result(Status.FAILED, installId, null, -1));
			}

			@Override
			public void onResponse(Call c, Response response)
			{
				Result result;
				boolean retry = false;
				try (response)
				{
					int code = response.code();
					log.debug("Registration: HTTP {}", code);
					if (code == 200)
					{
						String token = readToken(response.body());
						if (InstallIdentity.isToken(token))
						{
							identity.setToken(installId, token);
							result = new Result(Status.OK, installId, token, code);
						}
						else
						{
							result = new Result(Status.FAILED, installId, null, code);
						}
					}
					else if (code == 409 && rotateOnConflict)
					{
						// Someone else holds this id (or it was deleted): continue as a new random install. When it is held by
						// another token, this PC's key for it was lost, and what it shared under it may still be on the server.
						if (DELETED_ERROR.equals(readError(response.body())))
						{
							identity.rotateInstallId();
						}
						else
						{
							identity.replaceInstallId();
						}
						retry = true;
						result = null;
					}
					else if (code == 409)
					{
						// Only an explicit "deleted" counts as already deleted; anything else may still have data.
						result = new Result(DELETED_ERROR.equals(readError(response.body())) ? Status.DELETED : Status.CONFLICT,
							installId, null, code);
					}
					else
					{
						result = new Result(Status.FAILED, installId, null, code);
					}
				}
				catch (RuntimeException e)
				{
					log.debug("Bad registration response: {}", e.getClass().getSimpleName());
					result = new Result(Status.FAILED, installId, null, -1);
				}
				if (retry)
				{
					register(false, done);
				}
				else
				{
					deliver(done, result);
				}
			}
		};
		try
		{
			api.postRegister(body, callback);
		}
		catch (ServerApi.NotConnectedException e)
		{
			log.debug(e.getMessage());
			deliver(done, new Result(Status.NOT_CONNECTED, installId, null, -1));
		}
		catch (RuntimeException e)
		{
			log.warn("Couldn't start registration", e);
			deliver(done, new Result(Status.FAILED, installId, null, -1));
		}
	}

	/** The "error" field of an error response, or null. */
	private String readError(ResponseBody body)
	{
		if (body == null)
		{
			return null;
		}
		try
		{
			JsonObject o = gson.fromJson(body.charStream(), JsonObject.class);
			JsonElement e = o == null ? null : o.get("error");
			return e != null && e.isJsonPrimitive() ? e.getAsString() : null;
		}
		catch (RuntimeException ex)
		{
			return null;
		}
	}

	/** The "token" field of a register response, or null. Never logs the body. */
	private String readToken(ResponseBody body)
	{
		if (body == null)
		{
			return null;
		}
		JsonObject o = gson.fromJson(body.charStream(), JsonObject.class);
		JsonElement t = o == null ? null : o.get("token");
		return t != null && t.isJsonPrimitive() ? t.getAsString() : null;
	}

	private static void deliver(Consumer<Result> done, Result result)
	{
		try
		{
			done.accept(result);
		}
		catch (RuntimeException e)
		{
			log.warn("Registration callback failed", e);
		}
	}
}

package com.hardcoreworldtoolkit;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.function.Supplier;
import java.util.regex.Pattern;

/**
 * {@link ServerIdentity} over a small key-value {@link Store} ("installId", "installToken"): the plugin's
 * {@link IdentityFile} (a map in tests). All methods are synchronized, so two first-run callers can't each create and
 * save a different id.
 */
class InstallIdentity implements ServerIdentity
{
	static final String KEY_INSTALL_ID = "installId";
	static final String KEY_INSTALL_TOKEN = "installToken";
	/** Comma-separated older install ids whose key was lost ({@link #replaceInstallId()}). */
	static final String KEY_LOST_IDS = "lostInstallIds";
	private static final int MAX_LOST_IDS = 8;
	/** The server's token format: base64url of 32 random bytes, no padding. Anything else is treated as no token. */
	private static final Pattern TOKEN = Pattern.compile("^[A-Za-z0-9_-]{43}$");

	/** Where the values live (a file in the plugin's data folder, a map in tests). */
	interface Store
	{
		String get(String key);

		void set(String key, String value);

		void unset(String key);
	}

	private final Store store;
	private final Supplier<String> newId;

	InstallIdentity(Store store, Supplier<String> newId)
	{
		this.store = store;
		this.newId = newId;
	}

	/** True for a value shaped like a server-issued token. */
	static boolean isToken(String s)
	{
		return s != null && TOKEN.matcher(s).matches();
	}

	@Override
	public synchronized String installId()
	{
		return TrackerStore.installId(() -> store.get(KEY_INSTALL_ID), id -> store.set(KEY_INSTALL_ID, id), newId);
	}

	@Override
	public synchronized String token()
	{
		String t = store.get(KEY_INSTALL_TOKEN);
		return isToken(t) ? t : null;
	}

	@Override
	public synchronized void setToken(String installId, String token)
	{
		if (isToken(token) && installId != null && installId.equals(store.get(KEY_INSTALL_ID)))
		{
			store.set(KEY_INSTALL_TOKEN, token);
		}
	}

	@Override
	public synchronized void clearToken(String installId)
	{
		if (installId != null && installId.equals(store.get(KEY_INSTALL_ID)) && store.get(KEY_INSTALL_TOKEN) != null)
		{
			store.unset(KEY_INSTALL_TOKEN);
		}
	}

	@Override
	public synchronized String rotateInstallId()
	{
		if (store.get(KEY_INSTALL_TOKEN) != null)
		{
			store.unset(KEY_INSTALL_TOKEN);
		}
		String id = newId.get();
		store.set(KEY_INSTALL_ID, id);
		return id;
	}

	@Override
	public synchronized String replaceInstallId()
	{
		String old = store.get(KEY_INSTALL_ID);
		if (old != null && old.length() == TrackerStore.INSTALL_ID_LENGTH)
		{
			List<String> lost = new ArrayList<>(lostInstallIds());
			lost.remove(old);
			lost.add(old);
			while (lost.size() > MAX_LOST_IDS)
			{
				lost.remove(0);
			}
			store.set(KEY_LOST_IDS, String.join(",", lost));
		}
		return rotateInstallId();
	}

	@Override
	public synchronized List<String> lostInstallIds()
	{
		String v = store.get(KEY_LOST_IDS);
		if (v == null || v.isEmpty())
		{
			return Collections.emptyList();
		}
		List<String> out = new ArrayList<>();
		for (String id : v.split(","))
		{
			if (id.length() == TrackerStore.INSTALL_ID_LENGTH)
			{
				out.add(id);
			}
		}
		return out;
	}
}

package com.hardcoreworldtoolkit;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.function.Consumer;

/**
 * Recent market summaries per item for the GE price line. Lookups never block; a missing or old entry starts one
 * background fetch (never two at once for an item) and calls back when it arrives. Thread safe.
 */
class ItemQuoteCache
{
	/** Refetch entries older than this. */
	static final long TTL_MS = 30_000;
	/** Entries older than this aren't shown at all while a newer one is fetched. */
	static final long MAX_AGE_MS = 5 * 60_000;
	static final int MAX_ENTRIES = 64;

	/** Fetches one item; callbacks may run on any thread. */
	interface Fetcher
	{
		void fetch(int itemId, Consumer<MarketData.ItemDetail> ok, Consumer<String> err);
	}

	private static final class Entry
	{
		MarketData.ItemDetail detail;
		long fetchedAt;
		/** When the last fetch was started (also after a failure, so a failing server isn't hammered). */
		long requestedAt = Long.MIN_VALUE;
		boolean inFlight;
		final List<Runnable> waiting = new ArrayList<>();
	}

	private final Fetcher fetcher;
	private final Map<Integer, Entry> entries = new LinkedHashMap<Integer, Entry>(16, 0.75f, true)
	{
		@Override
		protected boolean removeEldestEntry(Map.Entry<Integer, Entry> eldest)
		{
			return size() > MAX_ENTRIES;
		}
	};

	ItemQuoteCache(Fetcher fetcher)
	{
		this.fetcher = fetcher;
	}

	/**
	 * The item's summary if one is held and not older than {@link #MAX_AGE_MS}; fetches a newer one in the background
	 * when it is older than {@link #TTL_MS} (or missing), then runs {@code onReady}.
	 *
	 * @param now    epoch ms
	 * @param onReady run (on the fetching thread) when new data has been stored; may be null
	 */
	MarketData.ItemDetail request(int itemId, long now, Runnable onReady)
	{
		MarketData.ItemDetail shown;
		synchronized (this)
		{
			Entry e = entries.computeIfAbsent(itemId, k -> new Entry());
			boolean has = e.detail != null;
			shown = has && now - e.fetchedAt <= MAX_AGE_MS ? e.detail : null;
			boolean fresh = has && now - e.fetchedAt <= TTL_MS;
			boolean recentlyTried = e.requestedAt != Long.MIN_VALUE && now - e.requestedAt < TTL_MS;
			if (fresh || recentlyTried && !e.inFlight)
			{
				return shown;
			}
			if (onReady != null)
			{
				e.waiting.add(onReady);
			}
			if (e.inFlight)
			{
				return shown;
			}
			e.inFlight = true;
			e.requestedAt = now;
		}
		fetcher.fetch(itemId, d -> done(itemId, d, now), err -> done(itemId, null, now));
		return shown;
	}

	/** The held summary if not older than {@link #MAX_AGE_MS}, without fetching. */
	synchronized MarketData.ItemDetail peek(int itemId, long now)
	{
		Entry e = entries.get(itemId);
		return e != null && e.detail != null && now - e.fetchedAt <= MAX_AGE_MS ? e.detail : null;
	}

	synchronized void clear()
	{
		entries.clear();
	}

	/** @param requestedAt when the fetch started; the data counts as of then */
	private void done(int itemId, MarketData.ItemDetail detail, long requestedAt)
	{
		List<Runnable> run;
		synchronized (this)
		{
			Entry e = entries.get(itemId);
			if (e == null)
			{
				// Cleared or evicted meanwhile.
				return;
			}
			e.inFlight = false;
			run = new ArrayList<>(e.waiting);
			e.waiting.clear();
			if (detail == null)
			{
				return;
			}
			e.detail = detail;
			e.fetchedAt = requestedAt;
		}
		run.forEach(Runnable::run);
	}
}

package com.hardcoreworldtoolkit;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import java.io.BufferedReader;
import java.io.BufferedWriter;
import java.io.IOException;
import java.nio.file.StandardOpenOption;
import java.time.Instant;
import java.time.YearMonth;
import java.time.ZoneOffset;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.function.BiConsumer;
import java.util.stream.Collectors;
import java.util.stream.Stream;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.util.Filepath;

/**
 * The local trade log in the plugin's data folder: one JSON object per line (a {@link TradeEvent} plus "acct", the
 * hashed account id), in one file per month ({@code trades-YYYY-MM.jsonl}, by the event time in UTC). Does disk IO,
 * so only call it from the executor, never the client thread.
 */
@Slf4j
final class LocalTradeLog
{
	private LocalTradeLog()
	{
	}

	/** The file that events at {@code month} (UTC) go to. */
	static String fileName(YearMonth month)
	{
		return String.format("trades-%04d-%02d.jsonl", month.getYear(), month.getMonthValue());
	}

	/** The month (UTC) of a unix-seconds timestamp. */
	static YearMonth monthOf(long ts)
	{
		return YearMonth.from(Instant.ofEpochSecond(ts).atZone(ZoneOffset.UTC));
	}

	/** Append already-serialized lines to {@code month}'s file, creating the folder and file if needed. */
	static void append(Filepath dir, YearMonth month, List<String> lines) throws IOException
	{
		// getPluginDirectory() doesn't create this plugin's own folder.
		if (!dir.exists())
		{
			dir.createDirectories();
		}
		Filepath file = dir.joinSegment(fileName(month));
		try (BufferedWriter w = file.openBufferedWriter(StandardOpenOption.CREATE, StandardOpenOption.APPEND))
		{
			for (String line : lines)
			{
				w.write(line);
				w.newLine();
			}
		}
	}

	/** Names of the log files in {@code dir}, in no particular order (empty if the folder doesn't exist). */
	static List<String> listNames(Filepath dir) throws IOException
	{
		if (!dir.isDirectory())
		{
			return Collections.emptyList();
		}
		try (Stream<Filepath> s = dir.walk(1))
		{
			return s.filter(Filepath::isFile).map(Filepath::getFileName).collect(Collectors.toList());
		}
	}

	/**
	 * The newest {@code maxShown} events that "My trades" shows ({@link MyTrades#isShown}), oldest first. Reads files
	 * newest month first, each from its end, and stops as soon as it has enough, so older months are never opened.
	 * Lines that don't parse, or have no kind, are skipped.
	 */
	static List<TradeEvent> readNewest(Filepath dir, Gson gson, int maxShown) throws IOException
	{
		return readNewest(dir, gson, maxShown, ReverseLineReader.DEFAULT_CHUNK);
	}

	static List<TradeEvent> readNewest(Filepath dir, Gson gson, int maxShown, int chunk) throws IOException
	{
		List<TradeEvent> newestFirst = new ArrayList<>();
		if (maxShown <= 0)
		{
			return newestFirst;
		}
		for (String name : LogFiles.newestFirst(listNames(dir)))
		{
			Filepath file = dir.joinSegment(name);
			try (ReverseLineReader r = new ReverseLineReader(file.openFileChannel(StandardOpenOption.READ), chunk))
			{
				String line;
				while ((line = r.readLine()) != null)
				{
					TradeEvent ev = parse(gson, line);
					if (ev != null && MyTrades.isShown(ev))
					{
						newestFirst.add(ev);
						if (newestFirst.size() >= maxShown)
						{
							Collections.reverse(newestFirst);
							return newestFirst;
						}
					}
				}
			}
		}
		Collections.reverse(newestFirst);
		return newestFirst;
	}

	/**
	 * Stream every log line, oldest file first and each file front to back, as the raw object (for "acct") and the
	 * parsed event. Bad lines are skipped. For rebuilding totals from the whole log; this reads everything.
	 */
	static void forEachOldestFirst(Filepath dir, Gson gson, BiConsumer<JsonObject, TradeEvent> consumer) throws IOException
	{
		for (String name : LogFiles.oldestFirst(listNames(dir)))
		{
			forEachInFile(dir, name, gson, consumer);
		}
	}

	/** Stream one log file front to back; see {@link #forEachOldestFirst}. Does nothing if the file is missing. */
	static void forEachInFile(Filepath dir, String name, Gson gson, BiConsumer<JsonObject, TradeEvent> consumer) throws IOException
	{
		Filepath file = dir.joinSegment(name);
		if (!file.isFile())
		{
			return;
		}
		try (BufferedReader r = file.openBufferedReader())
		{
			String line;
			while ((line = r.readLine()) != null)
			{
				if (line.isEmpty())
				{
					continue;
				}
				try
				{
					JsonObject obj = gson.fromJson(line, JsonObject.class);
					if (obj == null)
					{
						continue;
					}
					TradeEvent ev = gson.fromJson(obj, TradeEvent.class);
					if (ev != null && ev.getKind() != null)
					{
						consumer.accept(obj, ev);
					}
				}
				catch (RuntimeException ex)
				{
					log.debug("Skipping bad trade log line", ex);
				}
			}
		}
	}

	/** The event on one log line, or null if it doesn't parse or has no kind. "acct" is ignored. */
	static TradeEvent parse(Gson gson, String line)
	{
		try
		{
			TradeEvent ev = gson.fromJson(line, TradeEvent.class);
			return ev != null && ev.getKind() != null ? ev : null;
		}
		catch (RuntimeException ex)
		{
			log.debug("Skipping bad trade log line", ex);
			return null;
		}
	}
}

package com.hardcoreworldtoolkit;

import java.time.YearMonth;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Which files in the plugin folder make up the local trade log, and in what order. Pure.
 * <p>
 * The log is one file per month, {@code trades-YYYY-MM.jsonl}.
 */
final class LogFiles
{
	private static final Pattern MONTHLY = Pattern.compile("^trades-([0-9]{4})-([0-9]{2})[.]jsonl$");

	private LogFiles()
	{
	}

	static boolean isMonthly(String name)
	{
		return name != null && MONTHLY.matcher(name).matches();
	}

	/** The month of a monthly log file's name, or null for any other name. */
	static YearMonth monthOf(String name)
	{
		Matcher m = name == null ? null : MONTHLY.matcher(name);
		if (m == null || !m.matches())
		{
			return null;
		}
		int month = Integer.parseInt(m.group(2));
		return month >= 1 && month <= 12 ? YearMonth.of(Integer.parseInt(m.group(1)), month) : null;
	}

	/** Monthly log files, newest month first. Other names are ignored. */
	static List<String> newestFirst(List<String> names)
	{
		List<String> monthly = new ArrayList<>();
		for (String n : names)
		{
			if (isMonthly(n))
			{
				monthly.add(n);
			}
		}
		// Zero-padded year and month, so name order is time order.
		monthly.sort(Collections.reverseOrder());
		return monthly;
	}

	/** The reverse of {@link #newestFirst}: each month oldest first. */
	static List<String> oldestFirst(List<String> names)
	{
		List<String> list = newestFirst(names);
		Collections.reverse(list);
		return list;
	}
}

package com.hardcoreworldtoolkit;

import net.runelite.api.GameState;

/**
 * Tells a real login (or world hop / reconnect) apart from the LOGGED_IN that follows every loading screen.
 * The client goes LOGGED_IN -> LOADING -> LOGGED_IN on each region change, so a LOGGED_IN only counts as a login
 * when the state before it (ignoring LOADING) was the login screen, logging in, hopping or a lost connection.
 * Client thread only.
 */
class LoginDetector
{
	/** The last game state seen other than LOADING, or null when unknown. */
	private GameState previous;
	/**
	 * Reset while a loading screen was showing (mid-login or mid region change): the next LOGGED_IN is treated as a
	 * login so the open offers still get sent, at the cost of at most one extra short late window.
	 */
	private boolean resetDuringLoading;

	/** Start over from the client's current state, e.g. when the plugin is enabled. */
	void reset(GameState current)
	{
		resetDuringLoading = current == GameState.LOADING;
		previous = resetDuringLoading ? null : current;
	}

	/** Feed a game state change. Returns true if it is a login. */
	boolean update(GameState state)
	{
		if (state == GameState.LOADING)
		{
			// Loading screens sit between the states we care about; skip over them.
			return false;
		}
		boolean login = isLogin(previous, state) || (resetDuringLoading && state == GameState.LOGGED_IN);
		resetDuringLoading = false;
		previous = state;
		return login;
	}

	/** True when moving from {@code previous} (ignoring LOADING) to {@code current} is a login. */
	static boolean isLogin(GameState previous, GameState current)
	{
		if (current != GameState.LOGGED_IN || previous == null)
		{
			return false;
		}
		switch (previous)
		{
			case LOGIN_SCREEN:
			case LOGIN_SCREEN_AUTHENTICATOR:
			case LOGGING_IN:
			case HOPPING:
			case CONNECTION_LOST:
				return true;
			default:
				return false;
		}
	}
}

package com.hardcoreworldtoolkit;

import com.google.gson.Gson;
import java.io.IOException;
import java.util.Collection;
import java.util.Random;
import java.util.TreeSet;
import java.util.stream.Collectors;
import java.util.concurrent.Executor;
import java.util.function.Consumer;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.Response;
import okhttp3.ResponseBody;

/**
 * Read side of the collection server. Requests go through {@link ServerApi#getMarketData} (only while connected;
 * otherwise {@code err} gets {@link #NOT_CONNECTED}) and run on OkHttp's pool; the public methods deliver their
 * callbacks on the Swing EDT, the package-private ones ({@link #itemAsync}, {@link #items}) on the OkHttp thread.
 */
@Slf4j
public class MarketClient
{
	/** Events per Market feed request; the panel also uses it to spot a possible gap in an incremental load. */
	public static final int RECENT_LIMIT = 60;
	private static final int ITEM_LIMIT = 40;
	/**
	 * The Market feed shows live fills only. GE History rows are old trades with no real time, and a player's first
	 * connect sends dozens of them at once; they still count in the item views and prices. The panel filters too.
	 */
	static final String RECENT_KINDS = TradeEvent.FILL;
	/** Error messages passed to the {@code err} callbacks; {@link #shortReason} makes a status-line version. */
	public static final String UNREACHABLE = "Can't reach the Hardcore World Tool Kit server.";
	public static final String BAD_RESPONSE = "Unexpected server response.";
	/** Nothing was sent: the Connect setting is off. */
	public static final String NOT_CONNECTED = "Not connected to the Hardcore World Tool Kit server.";
	private static final String SERVER_ERROR_PREFIX = "Server error (";
	/**
	 * Opt-in extra fields: confirmed / trusted figures and fill-only last prices. Older servers ignore the parameter
	 * and the fields stay null.
	 */
	static final String INCLUDE = "trust,fill";
	private static final Executor EDT = SwingUtilities::invokeLater;
	/** Runs callbacks on the OkHttp thread that received the response. */
	private static final Executor DIRECT = Runnable::run;

	private final ServerApi api;
	private final Gson gson;
	private final HttpUrl base;
	private final int world;

	/** Shared with the uploader (see setBackoff), so one busy answer pauses both. */
	private ServerBackoff backoff = new ServerBackoff(System::currentTimeMillis, new Random());

	void setBackoff(ServerBackoff backoff)
	{
		this.backoff = backoff;
	}

	MarketClient(ServerApi api, Gson gson, HttpUrl base, int world)
	{
		this.api = api;
		this.gson = gson;
		this.base = base;
		this.world = world;
	}

	/**
	 * The Market feed and headline stats.
	 *
	 * @param afterId only events with a higher id, or 0 for the newest page. Older servers ignore it and return the
	 *                newest page, so callers must de-duplicate by id.
	 */
	public void recent(long afterId, Consumer<MarketData.Recent> ok, Consumer<String> err)
	{
		HttpUrl.Builder url = url("v1/recent")
			.addQueryParameter("limit", String.valueOf(RECENT_LIMIT))
			.addQueryParameter("kinds", RECENT_KINDS);
		if (afterId > 0)
		{
			url.addQueryParameter("after", String.valueOf(afterId));
		}
		get(url, false, MarketData.Recent.class, EDT, ok, err);
	}

	/** @param fresh skip any HTTP cache (a refresh the user asked for, or right after an upload) */
	public void item(int itemId, boolean fresh, Consumer<MarketData.ItemDetail> ok, Consumer<String> err)
	{
		get(url("v1/item/" + itemId).addQueryParameter("limit", String.valueOf(ITEM_LIMIT)), fresh,
			MarketData.ItemDetail.class, EDT, ok, err);
	}

	/**
	 * Price history. Newer servers return just {@code range}; older ones ignore it and return a year's worth of
	 * {@code step} buckets (365 of them), so callers trim to the range.
	 *
	 * @param range how far back, as the server names it (24h, 7d, 30d, 90d or 1y)
	 * @param step  bucket size, as the server names it (5m, 1h, 6h or 24h)
	 */
	public void series(int itemId, String range, String step, boolean fresh, Consumer<MarketData.Series> ok,
		Consumer<String> err)
	{
		get(url("v1/item/" + itemId + "/series").addQueryParameter("range", range).addQueryParameter("step", step),
			fresh, MarketData.Series.class, EDT, ok, err);
	}

	/**
	 * One item's summary for the GE price line, with callbacks on the OkHttp thread (never the EDT or client thread).
	 * Only the summary is used; it asks with the item view's limit, so both share one cached answer on the server.
	 */
	void itemAsync(int itemId, Consumer<MarketData.ItemDetail> ok, Consumer<String> err)
	{
		get(url("v1/item/" + itemId).addQueryParameter("limit", String.valueOf(ITEM_LIMIT)), false, MarketData.ItemDetail.class, DIRECT, ok, err);
	}

	/**
	 * Summaries of a few items, with callbacks on the OkHttp thread. Older servers ignore {@code ids} and return every
	 * item, so callers filter ({@link OfferQuotes#filter}).
	 */
	void items(Collection<Integer> ids, boolean fresh, Consumer<MarketData.ItemsResponse> ok, Consumer<String> err)
	{
		String list = new TreeSet<>(ids).stream().map(String::valueOf).collect(Collectors.joining(","));
		get(url("v1/items").addQueryParameter("ids", list), fresh, MarketData.ItemsResponse.class, DIRECT, ok, err);
	}

	public void flips(long gold, Consumer<MarketData.Flips> ok, Consumer<String> err)
	{
		get(url("v1/flips").addQueryParameter("capital", String.valueOf(gold)).addQueryParameter("limit", "200"), false, MarketData.Flips.class, EDT, ok, err);
	}

	public void gaps(Consumer<MarketData.Gaps> ok, Consumer<String> err)
	{
		get(url("v1/gaps").addQueryParameter("limit", "200"), false, MarketData.Gaps.class, EDT, ok, err);
	}

	/** The estimated Hardcore : OSRS gold rate, from what an Old school bond costs on each market. */
	public void swapRate(Consumer<MarketData.SwapRate> ok, Consumer<String> err)
	{
		get(url("v1/swap-rate"), false, MarketData.SwapRate.class, EDT, ok, err);
	}

	/** The error message for an HTTP error status. */
	static String serverError(int code)
	{
		return SERVER_ERROR_PREFIX + code + ").";
	}

	/**
	 * A few words for a status line from an error message: "server unreachable", "server error 500", "bad response"
	 * or "not connected"; anything else as given, without a trailing period.
	 */
	public static String shortReason(String message)
	{
		if (message == null || message.isEmpty())
		{
			return "unknown error";
		}
		if (UNREACHABLE.equals(message))
		{
			return "server unreachable";
		}
		if (NOT_CONNECTED.equals(message))
		{
			return "not connected";
		}
		if (BAD_RESPONSE.equals(message))
		{
			return "bad response";
		}
		if (message.startsWith(SERVER_ERROR_PREFIX) && message.endsWith(").") && message.length() > SERVER_ERROR_PREFIX.length() + 2)
		{
			return "server error " + message.substring(SERVER_ERROR_PREFIX.length(), message.length() - 2);
		}
		return message.endsWith(".") ? message.substring(0, message.length() - 1) : message;
	}

	private HttpUrl.Builder url(String path)
	{
		return base.newBuilder()
			.addPathSegments(path)
			.addQueryParameter("world", String.valueOf(world))
			.addQueryParameter("include", INCLUDE);
	}

	/** @param callbacks where {@code ok} / {@code err} run */
	private <T> void get(HttpUrl.Builder url, boolean fresh, Class<T> type, Executor callbacks, Consumer<T> ok,
		Consumer<String> err)
	{
		if (!fresh && backoff.waiting())
		{
			// The server said it is overloaded: keep showing what we have, ask again after the wait.
			callbacks.execute(() -> err.accept(serverError(503)));
			return;
		}
		Callback callback = new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.debug("Market request failed: {}", call.request().url(), e);
				if (!call.isCanceled())
				{
					backoff.failed(0);
				}
				callbacks.execute(() -> err.accept(UNREACHABLE));
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				backoff.observe(response.code(), response.header("Retry-After"));
				try (response)
				{
					ResponseBody body = response.body();
					if (!response.isSuccessful() || body == null)
					{
						int code = response.code();
						callbacks.execute(() -> err.accept(serverError(code)));
						return;
					}
					T data = gson.fromJson(body.charStream(), type);
					if (data == null)
					{
						callbacks.execute(() -> err.accept(BAD_RESPONSE));
						return;
					}
					callbacks.execute(() -> ok.accept(data));
				}
				catch (RuntimeException e)
				{
					log.debug("Bad market response", e);
					callbacks.execute(() -> err.accept(BAD_RESPONSE));
				}
			}
		};
		try
		{
			api.getMarketData(url.build(), fresh, callback);
		}
		catch (ServerApi.NotConnectedException e)
		{
			callbacks.execute(() -> err.accept(NOT_CONNECTED));
		}
	}
}

package com.hardcoreworldtoolkit;

import java.util.Collections;
import java.util.List;
import lombok.EqualsAndHashCode;
import lombok.Getter;
import net.runelite.client.util.Text;

/**
 * Response bodies of the collection server's read API, parsed by Gson. Field names are the server's JSON contract.
 * Some fields aren't shown in the panel yet; they're kept to document what the server sends.
 * <p>
 * List fields default to empty when the server leaves them out. That only works while each class keeps its implicit
 * no-arg constructor, so don't add constructors or make the fields final.
 * <p>
 * Every class has value equality, so the panel can skip re-rendering when a refresh returns the same data.
 * <p>
 * Fields added for {@code ?include=trust,fill} are boxed and stay null when an older server leaves them out.
 */
public final class MarketData
{
	private MarketData()
	{
	}

	/**
	 * An item name from the server, as plain text: the server keeps what players' clients sent, so it is never trusted
	 * as markup (Swing renders text starting with "&lt;html&gt;" as HTML, which could even load remote images). Tags are
	 * removed and no angle bracket is left.
	 */
	static String plainName(String name)
	{
		if (name == null)
		{
			return null;
		}
		return Text.removeTags(name).replace("<", "").replace(">", "").trim();
	}

	@Getter
	@EqualsAndHashCode
	public static class Recent
	{
		private Stats stats;
		private List<FeedEvent> events = Collections.emptyList();
	}

	/** The estimated Hardcore : OSRS gold rate from Old school bond prices (v1/swap-rate). rate is null while unknown. */
	@Getter
	@EqualsAndHashCode
	public static class SwapRate
	{
		private Double rate;
		/** The rate at the highest / lowest recent Hardcore fill: the range. */
		private Double rateLow;
		private Double rateHigh;
		private long main;
		private long hardcore;
	}

	@Getter
	@EqualsAndHashCode
	public static class Stats
	{
		private int openBids;
		private int openAsks;
		private long units24;
		private long gp24;
		private int reporters24;
	}

	@Getter
	@EqualsAndHashCode
	public static class FeedEvent
	{
		private long id;
		private String kind;
		private String side;
		private int itemId;
		private String name;
		private int qty;
		private long price;
		private Long total;
		private long ts;
		private boolean late;
		/** When the server received the event (unix s). */
		private long receivedAt;
		/** Fills only, with ?include=trust: whether the fill is confirmed; null otherwise. */
		private Boolean confirmed;

		public String getName()
		{
			return plainName(name);
		}
