package com.hardcoreworldtoolkit;

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.List;
import java.util.function.UnaryOperator;

/**
 * Your recent trades (newest first), from this session plus the local log. Thread safe.
 */
class MyTrades
{
	static final int MAX = 300;

	private final Deque<TradeEvent> trades = new ArrayDeque<>();
	/** Bumped by {@link #clear}, so a log load started before a plugin restart can't merge into the next session. */
	private int session;

	/**
	 * Fills, GE History rows and cancellations are shown. Offer placements are not trades (users misread
	 * "Buy offer 1,000 x 200" as a purchase), so the list never shows them. They are still logged and uploaded.
	 */
	static boolean isShown(TradeEvent ev)
	{
		return !TradeEvent.PLACED.equals(ev.getKind());
	}

	/** Add events that were just recorded, in the order given. */
	synchronized void addNewest(List<TradeEvent> events)
	{
		for (TradeEvent ev : events)
		{
			if (isShown(ev))
			{
				trades.addFirst(ev);
			}
		}
		while (trades.size() > MAX)
		{
			trades.removeLast();
		}
	}

	/** The current session token; capture it when starting a log load and pass it to {@link #mergeLoaded}. */
	synchronized int session()
	{
		return session;
	}

	/**
	 * Merge in events from {@link LocalTradeLog#readNewest} (oldest first, shown events only), each passed through {@code nameFill}. Live trades
	 * recorded before the log finished loading are merged in by time.
	 *
	 * @param session the {@link #session()} captured when the load started; if the list has been cleared since
	 *                (plugin stopped, maybe restarted), the load is stale and is dropped
	 * @return false if the load was stale and nothing was merged
	 */
	synchronized boolean mergeLoaded(int session, List<TradeEvent> loaded, UnaryOperator<TradeEvent> nameFill)
	{
		if (session != this.session)
		{
			return false;
		}
		for (int i = Math.max(0, loaded.size() - MAX); i < loaded.size(); i++)
		{
			trades.addLast(nameFill.apply(loaded.get(i)));
		}
		// Newest first. The sort is stable, so on equal times live trades stay ahead of loaded ones.
		List<TradeEvent> all = new ArrayList<>(trades);
		all.sort((a, b) -> Long.compare(b.getTs(), a.getTs()));
		trades.clear();
		trades.addAll(all.subList(0, Math.min(MAX, all.size())));
		return true;
	}

	/** Copy of the list, newest first. */
	synchronized List<TradeEvent> snapshot()
	{
		return new ArrayList<>(trades);
	}

	/** Empty the list and start a new session, so in-flight log loads from the old one are dropped. */
	synchronized void clear()
	{
		trades.clear();
		session++;
	}
}

package com.hardcoreworldtoolkit;

import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Set;
import java.util.TreeSet;
import java.util.function.BooleanSupplier;
import java.util.function.Consumer;
import java.util.function.LongSupplier;
import java.util.function.Supplier;

/**
 * Keeps your open offers compared with the market: fetches quotes for their items (at most once a minute on its own,
 * or every {@link #DEMAND_MS} when asked), evaluates them ({@link OfferWatch}) and reports the result, plus an alert
 * text when an offer just got undercut or outbid ({@link AlertGate}).
 * <p>
 * Thread safe: offers arrive from the client thread, the periodic check from the executor, the refresh button from
 * the EDT and responses on an OkHttp thread. Nothing here blocks; listeners must hand work off to their own thread.
 */
class OfferMarketWatch
{
	/** Automatic checks at most this often. */
	static final long AUTO_MS = 60_000;
	/** Checks asked for (refresh button, new item in your offers) at most this often. */
	static final long DEMAND_MS = 10_000;

	/** Fetches item summaries; callbacks may run on any thread. */
	interface Fetcher
	{
		void items(Collection<Integer> ids, boolean fresh, Consumer<MarketData.ItemsResponse> ok, Consumer<String> err);
	}

	/** Both are called on whatever thread produced the result, and must only hand the work off (never block). */
	interface Listener
	{
		/** New statuses (also when the offers changed, evaluated with the quotes already held). */
		void onReport(OfferReport report);

		/** An offer was just undercut or outbid and the alert gate allows notifying. */
		void onAlert(String message);
	}

	private final Fetcher fetcher;
	private final LongSupplier clockMs;
	private final BooleanSupplier connected;
	private final BooleanSupplier notifyEnabled;
	/** Whether the side panel is shown; with notifications off, nothing else uses a check. */
	private final BooleanSupplier panelShown;
	private final LongSupplier staleSecs;
	private final Supplier<List<TradeEvent>> myTrades;
	private final Listener listener;
	private final AlertGate gate = new AlertGate();

	// Guarded by this.
	private List<ActiveOffer> offers = Collections.emptyList();
	private Map<Integer, OfferWatch.Quote> quotes = Collections.emptyMap();
	private long lastRequest = Long.MIN_VALUE;
	private boolean inFlight;
	/** A check was asked for but rate limited; the next periodic call makes it. */
	private boolean demandPending;
	private long checkedAt;
	private String error;
	/** Bumped by {@link #reset}, so responses to older requests are dropped. */
	private int generation;

	OfferMarketWatch(Fetcher fetcher, LongSupplier clockMs, BooleanSupplier connected, BooleanSupplier notifyEnabled,
		BooleanSupplier panelShown, LongSupplier staleSecs, Supplier<List<TradeEvent>> myTrades, Listener listener)
	{
		this.fetcher = fetcher;
		this.clockMs = clockMs;
		this.connected = connected;
		this.notifyEnabled = notifyEnabled;
		this.panelShown = panelShown;
		this.staleSecs = staleSecs;
		this.myTrades = myTrades;
		this.listener = listener;
	}

	/** Your open offers changed. A new item among them asks for a check; otherwise the held quotes are reused. */
	void setOffers(List<ActiveOffer> next)
	{
		boolean newItems;
		synchronized (this)
		{
			newItems = !itemIds(offers).containsAll(itemIds(next));
			offers = next;
			List<String> keys = new ArrayList<>(next.size());
			next.forEach(o -> keys.add(o.getOfferKey()));
			gate.retain(keys);
		}
		if (!(newItems && inUse() && refresh(true, false)))
		{
			reevaluate();
		}
	}

	/** A check's result is only used by the shown panel or by notifications. */
	private boolean inUse()
	{
		return notifyEnabled.getAsBoolean() || panelShown.getAsBoolean();
	}

	/**
	 * Check the market for your offers' items, unless rate limited, not connected, or there are no offers. Automatic
	 * checks are also skipped while nothing would use them (panel hidden and notifications off).
	 *
	 * @param onDemand asked for (button, new item): allowed every {@link #DEMAND_MS} instead of {@link #AUTO_MS}
	 * @return true if a request was started
	 */
	boolean refresh(boolean onDemand)
	{
		return refresh(onDemand, onDemand);
	}

	/** @param fresh skip caches: only for a refresh the player asked for, not for a new item in their offers */
	private boolean refresh(boolean onDemand, boolean fresh)
	{
		Set<Integer> ids;
		int gen;
		synchronized (this)
		{
			if (!connected.getAsBoolean() || offers.isEmpty())
			{
				demandPending = false;
				return false;
			}
			if (inFlight)
			{
				demandPending |= onDemand;
				return false;
			}
			long now = clockMs.getAsLong();
			long since = lastRequest == Long.MIN_VALUE ? Long.MAX_VALUE : now - lastRequest;
			if (onDemand || demandPending)
			{
				if (since < DEMAND_MS)
				{
					demandPending = true;
					return false;
				}
			}
			else if (since < AUTO_MS || !inUse())
			{
				return false;
			}
			demandPending = false;
			inFlight = true;
			lastRequest = now;
			ids = itemIds(offers);
			gen = generation;
		}
		fetcher.items(ids, fresh, r -> onResponse(gen, ids, r), err -> onError(gen, err));
		return true;
	}

	/** Re-evaluate with the quotes held (offers, a fill, or the stale setting changed) and report. */
	void reevaluate()
	{
		report(false);
	}

	/** Forget quotes and pending checks (connection or account changed), then report. */
	void reset()
	{
		synchronized (this)
		{
			generation++;
			quotes = Collections.emptyMap();
			inFlight = false;
			demandPending = false;
			lastRequest = Long.MIN_VALUE;
			checkedAt = 0;
			error = null;
		}
		report(false);
	}

	private void onResponse(int gen, Set<Integer> ids, MarketData.ItemsResponse r)
	{
		synchronized (this)
		{
			if (gen != generation)
			{
				return;
			}
			inFlight = false;
			quotes = OfferQuotes.filter(r, ids);
			checkedAt = clockMs.getAsLong();
			error = null;
		}
		report(true);
	}

	private void onError(int gen, String err)
	{
		synchronized (this)
		{
			if (gen != generation)
			{
				return;
			}
			inFlight = false;
			error = err;
		}
		report(false);
	}

	/** @param alerts after a fresh check: let undercut / outbid changes notify */
	private void report(boolean alerts)
	{
		List<ActiveOffer> current;
		Map<Integer, OfferWatch.OfferStatus> statuses;
		synchronized (this)
		{
			current = offers;
			boolean on = connected.getAsBoolean();
			statuses = on && !current.isEmpty()
				? OfferWatch.evaluate(current, quotes, myTrades.get(), clockMs.getAsLong() / 1000, staleSecs.getAsLong())
				: Collections.emptyMap();
			OfferReport report = new OfferReport(Collections.unmodifiableMap(statuses), checkedAt, on ? error : null);
			// Inside the lock so reports reach the listener in the order they were made (it only hands them off).
			listener.onReport(report);
		}
		if (!alerts || !notifyEnabled.getAsBoolean())
		{
			return;
		}
		long now = clockMs.getAsLong();
		for (ActiveOffer o : current)
		{
			OfferWatch.OfferStatus s = statuses.get(o.getSlot());
			if (s != null && Objects.equals(o.getOfferKey(), s.getOfferKey()) && gate.shouldNotify(o.getOfferKey(), s.getFlag(), now))
			{
				String msg = OfferWatch.alertMessage(o, s);
				if (msg != null)
				{
					listener.onAlert(msg);
				}
			}
		}
	}

	private static Set<Integer> itemIds(List<ActiveOffer> offers)
	{
		Set<Integer> ids = new TreeSet<>();
		offers.forEach(o -> ids.add(o.getItemId()));
		return ids;
	}
}

package com.hardcoreworldtoolkit;

import java.util.Collection;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;

/**
 * Picks the requested items out of a v1/items response (pure). Servers that ignore {@code ids} return every item.
 */
final class OfferQuotes
{
	private OfferQuotes()
	{
	}

	/** Quotes for the requested ids that the response has; items it leaves out are simply missing. */
	static Map<Integer, OfferWatch.Quote> filter(MarketData.ItemsResponse response, Collection<Integer> ids)
	{
		Map<Integer, OfferWatch.Quote> out = new HashMap<>();
		if (response == null || response.getItems() == null)
		{
			return out;
		}
		Set<Integer> wanted = new HashSet<>(ids);
		for (MarketData.ItemSummary s : response.getItems())
		{
			if (s != null && wanted.contains(s.getId()))
			{
				out.put(s.getId(), OfferWatch.Quote.of(s));
			}
		}
		return out;
	}
}

package com.hardcoreworldtoolkit;

import java.util.Collections;
import java.util.Map;
import java.util.Objects;
import lombok.Value;

/** How your open offers compare with the market, for the panel ({@link OfferMarketWatch}). Immutable. */
@Value
public class OfferReport
{
	public static final OfferReport EMPTY = new OfferReport(Collections.emptyMap(), 0, null);

	/** By slot; empty when not connected. Match {@link OfferWatch.OfferStatus#getOfferKey()} to the offer. */
	Map<Integer, OfferWatch.OfferStatus> statuses;
	/** Epoch ms of the last successful market check, or 0. */
	long checkedAt;
	/** Why the last check failed, or null. */
	String error;

	/** The status of the offer in {@code slot}, if it is about that same offer; else null. */
	public OfferWatch.OfferStatus statusOf(ActiveOffer o)
	{
		OfferWatch.OfferStatus s = statuses.get(o.getSlot());
		return s != null && Objects.equals(s.getOfferKey(), o.getOfferKey()) ? s : null;
	}
}

package com.hardcoreworldtoolkit;

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.List;
import java.util.function.Supplier;
import lombok.AllArgsConstructor;
import lombok.Data;
import lombok.NoArgsConstructor;
import lombok.Value;
import net.runelite.api.GrandExchangeOffer;

/**
 * Turns the raw per-slot offer updates the client gives us into trade events by diffing each update
 * against the last state we saw for that slot. Pure logic so it can be unit tested without a client.
 */
public class OfferTracker
{
	public static final int SLOTS = 8;
	private static final int MAX_COMPLETED = 64;

	public enum Status
	{
		EMPTY, ACTIVE, COMPLETE, CANCELLED
	}

	/** What the client currently shows in a slot. */
	@Value
	public static class Snapshot
	{
		int itemId;
		boolean buy;
		long price;
		int totalQty;
		int sold;
		long spent;
		Status status;

		/** Map the client's offer state to ours. */
		public static Snapshot of(GrandExchangeOffer o)
		{
			Status status;
			boolean buy;
			switch (o.getState())
			{
				case BUYING:
					status = Status.ACTIVE;
					buy = true;
					break;
				case BOUGHT:
					status = Status.COMPLETE;
					buy = true;
					break;
				case CANCELLED_BUY:
					status = Status.CANCELLED;
					buy = true;
					break;
				case SELLING:
					status = Status.ACTIVE;
					buy = false;
					break;
				case SOLD:
					status = Status.COMPLETE;
					buy = false;
					break;
				case CANCELLED_SELL:
					status = Status.CANCELLED;
					buy = false;
					break;
				default:
					status = Status.EMPTY;
					buy = false;
					break;
			}
			return new Snapshot(o.getItemId(), buy, o.getPrice(), o.getTotalQuantity(), o.getQuantitySold(), o.getSpent(), status);
		}
	}

	/** What we remember about a slot between updates (persisted per account). */
	@Data
	@NoArgsConstructor
	@AllArgsConstructor
	public static class SlotState
	{
		String offerKey;
		int itemId;
		boolean buy;
		long price;
		int totalQty;
		/** Units filled so far, for buy and sell offers alike. */
		int sold;
		/** Gp that changed hands so far, for buy and sell offers alike. */
		long spent;
		Status status;
		long placedAt;
		/** Last time the client showed us this offer (unix s). */
		long seenAt;
	}

	private final SlotState[] slots = new SlotState[SLOTS];
	/** Signatures of offers we watched finish, used to skip the same trades when they show up in GE History. */
	private final Deque<String> completed = new ArrayDeque<>();
	private final Supplier<String> keyGen;

	public OfferTracker(Supplier<String> keyGen)
	{
		this.keyGen = keyGen;
	}

	public SlotState getSlot(int slot)
	{
		return slots[slot];
	}

	public void setSlot(int slot, SlotState state)
	{
		slots[slot] = state;
	}

	public List<String> getCompleted()
	{
		return new ArrayList<>(completed);
	}

	public void setCompleted(List<String> sigs)
	{
		completed.clear();
		if (sigs != null)
		{
			sigs.stream().skip(Math.max(0, sigs.size() - MAX_COMPLETED)).forEach(completed::addLast);
		}
	}

	/**
	 * Record that every active offer was still unchanged at {@code ts}.
	 *
	 * @return the slots that changed, in slot order, so the caller can save them
	 */
	public List<Integer> markSeen(long ts)
	{
		List<Integer> changed = new ArrayList<>();
		for (int slot = 0; slot < SLOTS; slot++)
		{
			SlotState s = slots[slot];
			if (s != null && s.status == Status.ACTIVE)
			{
				s.seenAt = ts;
				changed.add(slot);
			}
		}
		return changed;
	}

	/**
	 * If a GE History entry matches an offer we already recorded live, consume that match and return true.
	 */
	public boolean consumeCompleted(String signature)
	{
		return completed.removeFirstOccurrence(signature);
	}

	public static String signature(boolean buy, int itemId, int qty, long total)
	{
		return TradeEvent.sideOf(buy) + "|" + itemId + "|" + qty + "|" + total;
	}

	/**
	 * Apply a new snapshot for a slot.
	 *
	 * @param late true while the client is replaying offers on login - anything new we see then happened while we weren't watching
	 * @return events produced by the change (possibly empty)
	 */
	public List<TradeEvent> update(int slot, Snapshot now, boolean late, long ts, int world)
	{
		List<TradeEvent> events = new ArrayList<>();
		SlotState prev = slots[slot];

		if (now.status == Status.EMPTY)
		{
			// Collected / cleared. Anything that filled since our last look was already reported via
			// the non-empty update that preceded collection, or will show up in GE History.
			slots[slot] = null;
			return events;
		}

		// A finished offer never becomes active again, so an active one in its place was placed anew, even with
		// identical terms (the EMPTY update for the collection in between can be missed, e.g. while logged out).
		boolean isNew = prev == null
			|| (prev.status != Status.ACTIVE && now.status == Status.ACTIVE)
			|| prev.itemId != now.itemId
			|| prev.buy != now.buy
			|| prev.price != now.price
			|| prev.totalQty != now.totalQty
			|| now.sold < prev.sold
			|| now.spent < prev.spent;

		SlotState cur;
		if (isNew)
		{
			cur = new SlotState(keyGen.get(), now.itemId, now.buy, now.price, now.totalQty, 0, 0, Status.ACTIVE, ts, 0);
			events.add(base(TradeEvent.PLACED, cur, slot, ts, world)
				.id(cur.offerKey + ":placed")
				.qty(now.totalQty)
				.price(now.price)
				.late(late)
				.build());
		}
		else
		{
			cur = new SlotState(prev.offerKey, prev.itemId, prev.buy, prev.price, prev.totalQty, prev.sold, prev.spent, prev.status, prev.placedAt, prev.seenAt);
		}

		int dQty = now.sold - cur.sold;
		long dSpent = now.spent - cur.spent;
		if (dQty > 0 && dSpent > 0)
		{
			events.add(base(TradeEvent.FILL, cur, slot, ts, world)
				.id(cur.offerKey + ":fill:" + now.sold)
				.qty(dQty)
				.price(TradeEvent.avgPrice(dSpent, dQty))
				.total(dSpent)
				.filled(now.sold)
				.late(late)
				.since(late && cur.seenAt > 0 ? cur.seenAt : null)
				.build());
		}

		if (now.status == Status.CANCELLED && cur.status != Status.CANCELLED && now.sold < now.totalQty)
		{
			events.add(base(TradeEvent.CANCELLED, cur, slot, ts, world)
				.id(cur.offerKey + ":cancelled")
				.qty(now.totalQty - now.sold)
				.price(now.price)
				.late(late)
				.build());
		}

		boolean finished = now.status == Status.COMPLETE || now.status == Status.CANCELLED;
		boolean wasFinished = cur.status == Status.COMPLETE || cur.status == Status.CANCELLED;
		if (finished && !wasFinished && now.sold > 0)
		{
			completed.addLast(signature(now.buy, now.itemId, now.sold, now.spent));
			while (completed.size() > MAX_COMPLETED)
			{
				completed.removeFirst();
			}
		}

		cur.sold = now.sold;
		cur.spent = now.spent;
		cur.status = now.status;
		cur.seenAt = ts;
		slots[slot] = cur;
		return events;
	}

	private static TradeEvent.TradeEventBuilder base(String kind, SlotState s, int slot, long ts, int world)
	{
		return TradeEvent.builder()
			.kind(kind)
			.side(TradeEvent.sideOf(s.buy))
			.itemId(s.itemId)
			.slot(slot)
			.offerKey(s.offerKey)
			.ts(ts)
			.world(world);
	}
}

package com.hardcoreworldtoolkit;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import lombok.Value;
import net.runelite.client.util.QuantityFormatter;

/**
 * Compares your open offers with the market (pure). For each offer it decides whether someone sells below your sell
 * price (undercut), bids above your buy price (outbid), or the offer hasn't filled for a long time (stale).
 * <p>
 * The market's book includes your own offers and can't tell them apart, so comparisons are strict (an order at your
 * own price is never flagged) and prices of your other open offers, and of your own recent fills, on the same item
 * and side are ignored.
 */
public final class OfferWatch
{
	private OfferWatch()
	{
	}

	public enum Flag
	{
		OK, UNDERCUT, OUTBID, STALE
	}

	/**
	 * The market numbers one comparison needs. Any of them may be unknown (null). The last buy / sell must be live
	 * fills only: GE History rows are uploaded with the time they were imported, so a weeks-old trade imported by
	 * someone else would look like a trade made "since you listed".
	 */
	@Value
	public static class Quote
	{
		Long bestBid;
		Long bestAsk;
		Long lastBuy;
		Long lastBuyTime;
		Long lastSell;
		Long lastSellTime;

		/**
		 * From the batch summary: the order book only. Its last buy / sell include GE History rows (timestamped at
		 * import), which can't be told apart, so they are left out. The best bid / ask from trusted sources are
		 * preferred when the server sends them, so fake book entries can't trigger undercut / outbid alerts.
		 */
		public static Quote of(MarketData.ItemSummary s)
		{
			return new Quote(prefer(s.getTrustedBestBid(), s.getBestBid()), prefer(s.getTrustedBestAsk(), s.getBestAsk()),
				null, null, null, null);
		}

		/**
		 * From the item view's detail, which is usually fresher than the batch summary: its order book, plus the
		 * newest live (not late, not GE History) fill per side from its recent trades.
		 */
		public static Quote of(MarketData.Summary s, List<MarketData.Trade> trades)
		{
			MarketData.Trade buy = null, sell = null;
			for (MarketData.Trade t : trades == null ? Collections.<MarketData.Trade>emptyList() : trades)
			{
				if (t == null || !TradeEvent.FILL.equals(t.getKind()) || t.isLate())
				{
					continue;
				}
				if (TradeEvent.BUY.equals(t.getSide()) && (buy == null || t.getTs() > buy.getTs()))
				{
					buy = t;
				}
				else if (TradeEvent.SELL.equals(t.getSide()) && (sell == null || t.getTs() > sell.getTs()))
				{
					sell = t;
				}
			}
			return new Quote(prefer(s.getTrustedBestBid(), s.getBestBid()), prefer(s.getTrustedBestAsk(), s.getBestAsk()),
				buy == null ? null : buy.getPrice(), buy == null ? null : buy.getTs(),
				sell == null ? null : sell.getPrice(), sell == null ? null : sell.getTs());
		}
	}

	/** The trusted value when the server sent one, else the raw one (older servers, or no trusted offers yet). */
	private static Long prefer(Long trusted, Long raw)
	{
		return trusted != null ? trusted : raw;
	}

	/** The verdict for one offer. */
	@Value
	public static class OfferStatus
	{
		/** The offer this is about; a new offer in the same slot gets its own status. */
		String offerKey;
		Flag flag;
		/** The competing price for UNDERCUT / OUTBID, else null. */
		Long competing;
		/** One line for a tooltip, e.g. "Lowest ask 1,240,000". */
		String detail;
		/** Seconds since the last fill (or since placing), or -1 when unknown. */
		long idleSecs;
	}

	/**
	 * Evaluate every offer.
	 *
	 * @param quotes    market quotes by item id; an offer without one is OK ("no market data")
	 * @param myTrades  your recent trades (any order): last fills per offer, and own fill prices to ignore
	 * @param now       unix seconds
	 * @param staleSecs an offer with no fill for longer than this is STALE (when nothing worse applies)
	 * @return statuses by slot, in slot order
	 */
	public static Map<Integer, OfferStatus> evaluate(List<ActiveOffer> offers, Map<Integer, Quote> quotes,
		List<TradeEvent> myTrades, long now, long staleSecs)
	{
		Map<String, Long> lastFill = new HashMap<>();
		Map<String, List<TradeEvent>> ownFills = new HashMap<>();
		for (TradeEvent ev : myTrades)
		{
			if (!TradeEvent.FILL.equals(ev.getKind()))
			{
				continue;
			}
			if (ev.getOfferKey() != null)
			{
				lastFill.merge(ev.getOfferKey(), ev.getTs(), Math::max);
			}
			ownFills.computeIfAbsent(sideKey(ev.getItemId(), TradeEvent.BUY.equals(ev.getSide())), k -> new ArrayList<>())
				.add(ev);
		}

		Map<Integer, OfferStatus> out = new LinkedHashMap<>();
		for (ActiveOffer o : offers)
		{
			// Your fills of this item and side since this offer was placed may be what the market saw last.
			Set<Long> own = new HashSet<>();
			for (TradeEvent f : ownFills.getOrDefault(sideKey(o.getItemId(), o.isBuy()), Collections.emptyList()))
			{
				if (f.getTs() >= o.getPlacedAt())
				{
					own.add(f.getPrice());
				}
			}
			for (ActiveOffer other : offers)
			{
				if (other != o && other.getItemId() == o.getItemId() && other.isBuy() == o.isBuy())
				{
					own.add(other.getPrice());
				}
			}
			out.put(o.getSlot(), evaluate(o, quotes.get(o.getItemId()), own, lastFill.get(o.getOfferKey()), now, staleSecs));
		}
		return out;
	}

	/**
	 * One offer.
	 *
	 * @param ownPrices prices of your other offers and fills on the same item and side, which aren't competition
	 * @param lastFill  when this offer last filled (unix s), or null
	 */
	static OfferStatus evaluate(ActiveOffer o, Quote q, Set<Long> ownPrices, Long lastFill, long now, long staleSecs)
	{
		long since = Math.max(o.getPlacedAt(), lastFill == null ? 0 : lastFill);
		long idle = since > 0 ? Math.max(0, now - since) : -1;
		if (q == null)
		{
			return new OfferStatus(o.getOfferKey(), Flag.OK, null, "No market data", idle);
		}
		long p = o.getPrice();
		long placed = o.getPlacedAt();
		if (!o.isBuy())
		{
			Long ask = q.getBestAsk();
			if (ask != null && ask < p && !ownPrices.contains(ask))
			{
				return new OfferStatus(o.getOfferKey(), Flag.UNDERCUT, ask, "Lowest ask " + gp(ask), idle);
			}
			Long sold = q.getLastSell();
			if (sold != null && sold < p && after(q.getLastSellTime(), placed) && !ownPrices.contains(sold))
			{
				return new OfferStatus(o.getOfferKey(), Flag.UNDERCUT, sold, "Sold for " + gp(sold) + " since you listed", idle);
			}
		}
		else
		{
			Long bid = q.getBestBid();
			if (bid != null && bid > p && !ownPrices.contains(bid))
			{
				return new OfferStatus(o.getOfferKey(), Flag.OUTBID, bid, "Highest bid " + gp(bid), idle);
			}
			Long bought = q.getLastBuy();
			if (bought != null && bought > p && after(q.getLastBuyTime(), placed) && !ownPrices.contains(bought))
			{
				return new OfferStatus(o.getOfferKey(), Flag.OUTBID, bought, "Bought for " + gp(bought) + " since you bid", idle);
			}
		}
		if (idle >= 0 && idle > staleSecs)
		{
			return new OfferStatus(o.getOfferKey(), Flag.STALE, null, "No fill for " + hours(idle), idle);
		}
		return new OfferStatus(o.getOfferKey(), Flag.OK, null, "No better offer seen", idle);
	}

	/** A trade time strictly after the offer was placed; false when either is unknown. */
	private static boolean after(Long ts, long placedAt)
	{
		return ts != null && placedAt > 0 && ts > placedAt;
	}

	private static String sideKey(int itemId, boolean buy)
	{
		return itemId + (buy ? "|b" : "|s");
	}

	/** "7h", or "45m" under an hour. */
	public static String hours(long secs)
	{
		return secs >= 3600 ? (secs / 3600) + "h" : Math.max(0, secs / 60) + "m";
	}

	/** Exact below 10M gp, stack format (e.g. 12.5M) above. */
	public static String gp(long v)
	{
		return v < 10_000_000 ? QuantityFormatter.formatNumber(v) : QuantityFormatter.quantityToStackSize(v);
	}

	/**
	 * The notification text, e.g. "Hardcore World Tool Kit: your Dragon bones sell offer (1,250,000) was undercut at
	 * 1,240,000."; null for flags that don't notify.
	 */
	public static String alertMessage(ActiveOffer o, OfferStatus s)
	{
		if (s.getCompeting() == null || (s.getFlag() != Flag.UNDERCUT && s.getFlag() != Flag.OUTBID))
		{
			return null;
		}
		String name = o.getName() == null ? "item " + o.getItemId() : o.getName();
		return "Hardcore World Tool Kit: your " + name + (o.isBuy() ? " buy" : " sell") + " offer (" + gp(o.getPrice()) + ") was "
			+ (s.getFlag() == Flag.UNDERCUT ? "undercut" : "outbid") + " at " + gp(s.getCompeting()) + ".";
	}
}

package com.hardcoreworldtoolkit;

/**
 * What the "Get started" card on the home view shows, and whether the one-time chat hint is worth sending.
 */
public final class Onboarding
{
	public enum Step
	{
		/** Nothing to do: no card. */
		HIDDEN,
		/** Not connected; GE History is already imported (or unknown while connected). */
		CONNECT,
		/** Connected, but this account's GE History hasn't been imported. */
		IMPORT,
		/** Neither. */
		CONNECT_AND_IMPORT,
		/** All done, and the "Imported N trades" line hasn't been dismissed yet. */
		IMPORTED_NOTICE,
	}

	private Onboarding()
	{
	}

	/**
	 * @param connected       the connected setting
	 * @param historyImported whether the logged-in account's GE History was read at least once; null when not logged
	 *                        in on a Hardcore World, so it isn't known
	 * @param importNotice    trades added by the first import, while that notice is still showing; else null
	 */
	public static Step state(boolean connected, Boolean historyImported, Integer importNotice)
	{
		boolean needConnect = !connected;
		// Unknown (not logged in) only shows the import steps next to the connect block. A connected player who
		// imported long ago shouldn't see the card every time the client sits on the login screen.
		boolean needImport = historyImported == null ? needConnect : !historyImported;
		if (needConnect && needImport)
		{
			return Step.CONNECT_AND_IMPORT;
		}
		if (needConnect)
		{
			return Step.CONNECT;
		}
		if (needImport)
		{
			return Step.IMPORT;
		}
		return importNotice != null ? Step.IMPORTED_NOTICE : Step.HIDDEN;
	}

	/** True when the card's import block should also say to log in on a Hardcore World first. */
	public static boolean needsLogin(Boolean historyImported)
	{
		return historyImported == null;
	}

	/** The one-time chat hint is only worth sending when the player still has something to set up. */
	public static boolean shouldShowChatHint(boolean connected, boolean historyImported)
	{
		return !connected || !historyImported;
	}
}

package com.hardcoreworldtoolkit;

import com.google.gson.JsonObject;
import java.util.List;
import java.util.Objects;

/**
 * Decides when the list of your open offers is worth sending. It used to go out every six minutes for every sharing
 * player, even with no offers and nothing changed, each one a database write on the server. Now it goes out
 * when it differs from what was last sent (at most once per {@link #MIN_GAP_MS}), and as a keep-alive every {@link #KEEP_ALIVE_MS} while offers stay open
 * (the server ignores offers not refreshed for two weeks). An empty list is sent once (it clears what the server has),
 * then not again until something changes. {@link #reset} makes the next one go out (login, sharing switched on).
 * Thread safe.
 */
class OpenOffersGate
{
	static final long KEEP_ALIVE_MS = 30 * 60_000L;
	/** A change is sent at most this often (the old fixed interval), so a fast-filling offer can't send more than before. */
	static final long MIN_GAP_MS = 6 * 60_000L;

	private String lastAccount;
	private String lastSignature;
	private long lastSentAt;

	/** @return true when {@code offers} should be sent now; the call counts as the send, so call it once per decision */
	synchronized boolean shouldSend(String accountId, List<JsonObject> offers, long nowMs)
	{
		String signature = String.valueOf(offers);
		// Another account (or the first call) is sent at once; a change in the offers waits for the minimum gap.
		boolean changed = lastSignature == null || !Objects.equals(accountId, lastAccount)
			|| (!signature.equals(lastSignature) && nowMs - lastSentAt >= MIN_GAP_MS);
		boolean keepAlive = !offers.isEmpty() && nowMs - lastSentAt >= KEEP_ALIVE_MS;
		if (!changed && !keepAlive)
		{
			return false;
		}
		lastAccount = accountId;
		lastSignature = signature;
		lastSentAt = nowMs;
		return true;
	}

	/** Forget what was sent: the next call to {@link #shouldSend} says yes. */
	synchronized void reset()
	{
		lastAccount = null;
		lastSignature = null;
		lastSentAt = 0;
	}
}

package com.hardcoreworldtoolkit;

import java.math.BigInteger;
import java.time.Instant;
import java.time.LocalDate;
import java.time.ZoneId;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;

/**
 * Running profit totals for one account, from its own fills and GE History rows. Pure and not thread safe: the plugin
 * keeps it on its single-threaded executor ({@link ProfitStore}). Also the JSON shape of the per-account profit file
 * (read and written with Gson), so applying an event is O(1) and start-up never replays the trade log.
 * <p>
 * Per item it keeps the units held (bought minus sold, within the tracked data), their cost (moving average) and the
 * realized profit on sells. A sell of more units than are held (bought before the plugin was
 * installed, or while the log was off) has no known cost: those proceeds are counted as "unknown basis", not profit.
 * <p>
 * Daily totals are keyed by the event's local date. GE History rows have no real time; their ts is when they were
 * imported, so they count on the import day, and are also summed separately so the panel can say so.
 */
final class ProfitBook
{
	/** Daily totals older than this (before the newest day) are dropped. */
	static final int DAILY_DAYS = 400;
	/** Items listed in {@link ProfitSnapshot#getTop}. */
	static final int TOP = 5;
	static final int VERSION = 1;

	/** One item's running position. Fields are the file format; never rename them. */
	static final class Position
	{
		String name;
		/** Units bought and not yet sold. */
		long held;
		/** What {@link #held} cost altogether (moving average: sells take the average cost out). */
		long basis;
		/** Profit on sells with a known cost, including {@link #historyRealized}. */
		long realized;
		/** Proceeds of units sold that weren't held, so have no known cost. Not profit. */
		long unknownProceeds;
		long unknownQty;
		/** The part of {@link #realized} from GE History rows (counted when imported). */
		long historyRealized;

		Position()
		{
		}
	}

	// The file format. Gson fills these in; never rename them.
	private int version = VERSION;
	private Map<Integer, Position> items = new HashMap<>();
	private long allTime;
	private long historyAllTime;
	private long unknownProceeds;
	/** Realized profit per local date (ISO yyyy-MM-dd, which sorts by date). */
	private TreeMap<String, Long> daily = new TreeMap<>();

	ProfitBook()
	{
	}

	/** After reading the file: replace anything missing (an older or damaged file) with empty values. */
	ProfitBook sanitized()
	{
		if (items == null)
		{
			items = new HashMap<>();
		}
		items.values().removeIf(p -> p == null);
		if (daily == null)
		{
			daily = new TreeMap<>();
		}
		daily.values().removeIf(v -> v == null);
		version = VERSION;
		return this;
	}

	boolean isEmpty()
	{
		return items.isEmpty();
	}

	/**
	 * Count one of your events. Only fills and GE History rows are trades; placements and cancellations are ignored.
	 *
	 * @param zone the time zone whose date the profit counts on
	 * @return true if anything changed
	 */
	boolean apply(TradeEvent ev, ZoneId zone)
	{
		if (ev == null || !TradeEvent.isTrade(ev.getKind()) || ev.getQty() <= 0)
		{
			return false;
		}
		boolean buy = TradeEvent.BUY.equals(ev.getSide());
		if (!buy && !TradeEvent.SELL.equals(ev.getSide()))
		{
			return false;
		}
		long q = ev.getQty();
		// price * qty fits: both are at most about 2^31.
		long total = ev.getTotal() != null ? ev.getTotal() : ev.getPrice() * q;
		if (total < 0)
		{
			return false;
		}
		Position p = items.computeIfAbsent(ev.getItemId(), k -> new Position());
		if (ev.getName() != null && !ev.getName().isEmpty())
		{
			p.name = ev.getName();
		}
		if (buy)
		{
			p.held += q;
			p.basis += total;
			return true;
		}

		long m = Math.min(q, p.held);
		long knownProceeds = m == q ? total : mulDiv(total, m, q);
		if (m > 0)
		{
			long cost = m == p.held ? p.basis : mulDiv(p.basis, m, p.held);
			long gain = knownProceeds - cost;
			p.realized += gain;
			p.basis -= cost;
			p.held -= m;
			allTime += gain;
			if (TradeEvent.HISTORY.equals(ev.getKind()))
			{
				p.historyRealized += gain;
				historyAllTime += gain;
			}
			daily.merge(dayKey(ev.getTs(), zone), gain, Long::sum);
			prune();
		}
		if (m < q)
		{
			long unknown = total - knownProceeds;
			p.unknownQty += q - m;
			p.unknownProceeds += unknown;
			unknownProceeds += unknown;
		}
		return true;
	}

	static String dayKey(long ts, ZoneId zone)
	{
		return Instant.ofEpochSecond(ts).atZone(zone).toLocalDate().toString();
	}

	private void prune()
	{
		if (daily.size() <= DAILY_DAYS)
		{
			return;
		}
		String cutoff = LocalDate.parse(daily.lastKey()).minusDays(DAILY_DAYS).toString();
		daily.headMap(cutoff).clear();
	}

	/**
	 * An immutable copy for the panel: totals, the daily totals it needs from {@code today} on, the top items and every
	 * item's numbers.
	 */
	ProfitSnapshot snapshot(LocalDate today, boolean rebuilding, boolean logAvailable)
	{
		Map<Integer, ProfitSnapshot.ItemProfit> byId = new HashMap<>(items.size() * 2);
		List<ProfitSnapshot.ItemProfit> withProfit = new ArrayList<>();
		for (Map.Entry<Integer, Position> e : items.entrySet())
		{
			Position p = e.getValue();
			ProfitSnapshot.ItemProfit ip = new ProfitSnapshot.ItemProfit(e.getKey(), p.name, p.held,
				p.held > 0 ? mulDiv(p.basis, 1, p.held) : 0, p.realized, p.unknownProceeds, p.unknownQty, p.historyRealized);
			byId.put(e.getKey(), ip);
			if (p.realized != 0)
			{
				withProfit.add(ip);
			}
		}
		withProfit.sort((a, b) ->
		{
			int c = Long.compare(b.getRealized(), a.getRealized());
			return c != 0 ? c : Integer.compare(a.getItemId(), b.getItemId());
		});
		List<ProfitSnapshot.ItemProfit> top = new ArrayList<>(withProfit.subList(0, Math.min(TOP, withProfit.size())));
		TreeMap<String, Long> recent = new TreeMap<>(daily.tailMap(today.minusDays(6).toString(), true));
		return new ProfitSnapshot(allTime, historyAllTime, unknownProceeds, Collections.unmodifiableSortedMap(recent),
			Collections.unmodifiableList(top), Collections.unmodifiableMap(byId), rebuilding, logAvailable);
	}

	// For tests.

	Position position(int itemId)
	{
		return items.get(itemId);
	}

	long getAllTime()
	{
		return allTime;
	}

	long getHistoryAllTime()
	{
		return historyAllTime;
	}

	long getUnknownProceeds()
	{
		return unknownProceeds;
	}

	Map<String, Long> daily()
	{
		return Collections.unmodifiableMap(daily);
	}

	/** Same totals as {@code o} (for comparing a rebuild with live counting). */
	boolean sameAs(ProfitBook o)
	{
		if (allTime != o.allTime || historyAllTime != o.historyAllTime || unknownProceeds != o.unknownProceeds
			|| !daily.equals(o.daily) || !items.keySet().equals(o.items.keySet()))
		{
			return false;
		}
		for (Map.Entry<Integer, Position> e : items.entrySet())
		{
			Position a = e.getValue(), b = o.items.get(e.getKey());
			if (a.held != b.held || a.basis != b.basis || a.realized != b.realized || a.unknownProceeds != b.unknownProceeds
				|| a.unknownQty != b.unknownQty || a.historyRealized != b.historyRealized)
			{
				return false;
			}
		}
		return true;
	}

	/** a * b / c rounded half up, for non-negative a, b and positive c, without overflowing. */
	static long mulDiv(long a, long b, long c)
	{
		try
		{
			long prod = Math.multiplyExact(a, b);
			long q = prod / c, r = prod % c;
			return r >= c - r ? q + 1 : q;
		}
		catch (ArithmeticException ex)
		{
			BigInteger big = BigInteger.valueOf(c);
			BigInteger[] qr = BigInteger.valueOf(a).multiply(BigInteger.valueOf(b)).divideAndRemainder(big);
			long q = qr[0].longValue();
			return qr[1].shiftLeft(1).compareTo(big) >= 0 ? q + 1 : q;
		}
	}
}

package com.hardcoreworldtoolkit;

import java.time.LocalDate;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import java.util.SortedMap;
import java.util.TreeMap;
import lombok.Value;

/**
 * Immutable profit numbers for the account shown in the panel, made by {@link ProfitBook#snapshot} on the executor
 * and handed to the EDT. Amounts are gp; realized profit includes GE History rows (counted when imported).
 */
@Value
public class ProfitSnapshot
{
	public static final ProfitSnapshot EMPTY = new ProfitSnapshot(0, 0, 0, Collections.unmodifiableSortedMap(new TreeMap<>()),
		Collections.emptyList(), Collections.emptyMap(), false, false);

	long allTime;
	/** The part of {@link #allTime} from GE History rows. */
	long historyAllTime;
	/** Proceeds of sells with no known cost (not counted as profit). */
	long unknownProceeds;
	/** Realized profit per local date (ISO), from 6 days before the snapshot was made. */
	SortedMap<String, Long> recentDaily;
	/** The items with the most realized profit, best first. */
	List<ItemProfit> top;
	Map<Integer, ItemProfit> items;
	/** A rebuild from the local log is running. */
	boolean rebuilding;
	/** The local trade log has files a rebuild could read. */
	boolean logAvailable;

	/** One item's numbers. */
	@Value
	public static class ItemProfit
	{
		int itemId;
		String name;
		long held;
		/** Average cost of the units held; 0 when none are. */
		long avgCost;
		long realized;
		long unknownProceeds;
		long unknownQty;
		long historyRealized;
	}

	/** True once any of your trades was counted. */
	public boolean hasData()
	{
		return !items.isEmpty();
	}

	/** Realized profit on {@code day} (your time zone when the trades were counted). */
	public long today(LocalDate day)
	{
		return between(day, day);
	}

	/** Realized profit over the 7 days ending on {@code day}. */
	public long last7(LocalDate day)
	{
		return between(day.minusDays(6), day);
	}

	private long between(LocalDate from, LocalDate to)
	{
		long sum = 0;
		for (long v : recentDaily.subMap(from.toString(), to.plusDays(1).toString()).values())
		{
			sum += v;
		}
		return sum;
	}

	/** The item's numbers, or null if none of its trades were counted. */
	public ItemProfit item(int itemId)
	{
		return items.get(itemId);
	}
}

package com.hardcoreworldtoolkit;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.io.BufferedReader;
import java.io.BufferedWriter;
import java.io.IOException;
import java.nio.file.AtomicMoveNotSupportedException;
import java.nio.file.StandardCopyOption;
import java.nio.file.StandardOpenOption;
import java.time.Clock;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import java.util.function.Consumer;
import java.util.regex.Pattern;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.util.Filepath;

/**
 * Keeps the logged-in account's {@link ProfitBook} and saves it to {@code profit-<account id prefix>.json} in the
 * plugin folder, so start-up reads one small file instead of replaying the trade log.
 * <p>
 * Confined to the plugin's single-threaded executor: every method must run there (no locks needed). The log append
 * for an event runs in the same executor before its {@link #apply}, which is what makes {@link #rebuild} race free:
 * the rebuild reads one log file per task, and reads the newest file in the same task that swaps in the new book, so
 * every event is counted exactly once whether it was appended before or after the rebuild started.
 */
@Slf4j
final class ProfitStore
{
	static final int SAVE_DELAY_SECONDS = 5;
	/** Characters of the (hex, hashed) account id used in the file name. */
	static final int FILE_ID_LENGTH = 16;
	private static final Pattern ACCOUNT_ID = Pattern.compile("^[0-9a-f]{" + FILE_ID_LENGTH + ",}$");

	private final Dir dir;
	private final Gson gson;
	private final ScheduledExecutorService executor;
	private final Clock clock;
	private final Consumer<ProfitSnapshot> listener;

	/** The account whose book is loaded, or null before the first login. */
	private String account;
	private ProfitBook book;
	private boolean dirty;
	private ScheduledFuture<?> pendingSave;
	/** Whether the trade log has any files; null when not checked since the last load. */
	private Boolean logAvailable;
	private Rebuild rebuild;
	private boolean closed;

	/** The plugin folder; finding it may do IO. */
	interface Dir
	{
		Filepath get() throws IOException;
	}

	/** A rebuild in progress: the account it's for, the log files in order, and the book being built. */
	private static final class Rebuild
	{
		final String account;
		final List<String> files;
		final ProfitBook book = new ProfitBook();
		int next;

		Rebuild(String account, List<String> files)
		{
			this.account = account;
			this.files = new ArrayList<>(files);
		}
	}

	/**
	 * @param dir      the plugin folder (also holds the trade log)
	 * @param clock    gives the time zone and today's date for daily totals
	 * @param listener receives a new snapshot after every change; called on the executor
	 */
	ProfitStore(Dir dir, Gson gson, ScheduledExecutorService executor, Clock clock,
		Consumer<ProfitSnapshot> listener)
	{
		this.dir = dir;
		this.gson = gson;
		this.executor = executor;
		this.clock = clock;
		this.listener = listener;
	}

	/** The profit file for a hashed account id; null if it doesn't look like one (never a name). */
	static String fileName(String accountId)
	{
		if (accountId == null || !ACCOUNT_ID.matcher(accountId).matches())
		{
			return null;
		}
		return "profit-" + accountId.substring(0, FILE_ID_LENGTH) + ".json";
	}

	/** Switch to {@code accountId}'s book (saving the previous one), then publish it. */
	void load(String accountId)
	{
		if (closed || fileName(accountId) == null)
		{
			return;
		}
		if (!accountId.equals(account))
		{
			saveNow();
			account = accountId;
			book = read(accountId);
			dirty = false;
			logAvailable = null;
		}
		publish();
	}

	/**
	 * Count events just recorded (after their log append, if any).
	 *
	 * @param accountId the account they belong to; switches to it if another is loaded
	 * @param logged    the events were also written to the trade log
	 */
	void apply(String accountId, List<TradeEvent> events, boolean logged)
	{
		if (closed)
		{
			return;
		}
		if (accountId != null && !accountId.equals(account))
		{
			load(accountId);
		}
		if (logged)
		{
			logAvailable = true;
		}
		if (book == null)
		{
			return;
		}
		boolean changed = false;
		for (TradeEvent ev : events)
		{
			changed |= book.apply(ev, clock.getZone());
		}
		if (changed)
		{
			dirty = true;
			scheduleSave();
			publish();
		}
	}

	/**
	 * Recount the loaded account from the whole trade log, one file per executor task. Lines carrying another
	 * account's id are skipped; lines without one (written while the account id wasn't known) count for this account. Always
	 * publishes, so the panel's button resets even when nothing is done.
	 */
	void rebuild()
	{
		if (closed)
		{
			return;
		}
		if (account == null || rebuild != null)
		{
			publish();
			return;
		}
		List<String> files;
		try
		{
			files = LogFiles.oldestFirst(LocalTradeLog.listNames(dir.get()));
		}
		catch (IOException ex)
		{
			log.warn("Couldn't list the trade log for a profit rebuild", ex);
			publish();
			return;
		}
		rebuild = new Rebuild(account, files);
		publish();
		executor.execute(this::rebuildStep);
	}

	private void rebuildStep()
	{
		Rebuild r = rebuild;
		if (closed || r == null)
		{
			return;
		}
		try
		{
			if (r.next < r.files.size())
			{
				readInto(r, r.files.get(r.next++));
				if (r.next < r.files.size())
				{
					// Let other executor work (appends, live profit) run between files.
					executor.execute(this::rebuildStep);
					return;
				}
			}
			// Same task as the newest file: a month that began during the rebuild has a file we haven't read.
			for (String name : LogFiles.oldestFirst(LocalTradeLog.listNames(dir.get())))
			{
				if (!r.files.contains(name))
				{
					r.files.add(name);
					readInto(r, name);
				}
			}
			finish(r);
		}
		catch (IOException | RuntimeException ex)
		{
			log.warn("Profit rebuild failed", ex);
			rebuild = null;
			publish();
		}
	}

	/**
	 * Count one log file's events for the rebuild's account, in time order (sorted, stable, so equal times keep their
	 * order).
	 */
	private void readInto(Rebuild r, String file) throws IOException
	{
		List<TradeEvent> events = new ArrayList<>();
		LocalTradeLog.forEachInFile(dir.get(), file, gson, (obj, ev) ->
		{
			if (belongsTo(obj, r.account))
			{
				events.add(ev);
			}
		});
		events.sort((a, b) -> Long.compare(a.getTs(), b.getTs()));
		for (TradeEvent ev : events)
		{
			r.book.apply(ev, clock.getZone());
		}
	}

	/** A log line counts for {@code accountId} if it carries that id, or no id at all (written before it was known). */
	static boolean belongsTo(JsonObject line, String accountId)
	{
		JsonElement a = line.get("acct");
		if (a == null || a.isJsonNull())
		{
			return true;
		}
		return a.isJsonPrimitive() && accountId.equals(a.getAsString());
	}

	private void finish(Rebuild r)
	{
		rebuild = null;
		logAvailable = !r.files.isEmpty();
		if (r.account.equals(account))
		{
			book = r.book;
			dirty = true;
			saveNow();
		}
		else
		{
			// The account changed meanwhile; the rebuilt book is still complete for the one it was made for.
			try
			{
				write(r.account, r.book);
			}
			catch (IOException | RuntimeException ex)
			{
				log.warn("Couldn't save rebuilt profit", ex);
			}
		}
		log.debug("Profit rebuilt from {} log files", r.files.size());
		publish();
	}

	/** Final save (plugin stopping); later calls do nothing. */
	void close()
	{
		if (closed)
		{
			return;
		}
		if (pendingSave != null)
		{
			pendingSave.cancel(false);
			pendingSave = null;
		}
		saveNow();
		closed = true;
		rebuild = null;
	}

	private void scheduleSave()
	{
		if (pendingSave != null && !pendingSave.isDone())
		{
			return;
		}
		pendingSave = executor.schedule(() ->
		{
			pendingSave = null;
			saveNow();
		}, SAVE_DELAY_SECONDS, TimeUnit.SECONDS);
	}

	/** Write the loaded book if it changed. */
	void saveNow()
	{
		if (!dirty || account == null || book == null)
		{
			return;
		}
		try
		{
			write(account, book);
			dirty = false;
		}
		catch (IOException | RuntimeException ex)
		{
			log.warn("Couldn't save profit", ex);
		}
	}

	private void write(String accountId, ProfitBook b) throws IOException
	{
		Filepath d = dir.get();
		if (!d.exists())
		{
			d.createDirectories();
		}
		String name = fileName(accountId);
		Filepath file = d.joinSegment(name);
		Filepath tmp = d.joinSegment(name + ".tmp");
		try (BufferedWriter w = tmp.openBufferedWriter(StandardOpenOption.CREATE, StandardOpenOption.TRUNCATE_EXISTING,
			StandardOpenOption.WRITE))
		{
			gson.toJson(b, w);
		}
		// Write then rename, so a crash mid-write never leaves a half file.
		try
		{
			tmp.moveTo(file, StandardCopyOption.REPLACE_EXISTING, StandardCopyOption.ATOMIC_MOVE);
		}
		catch (AtomicMoveNotSupportedException ex)
		{
			tmp.moveTo(file, StandardCopyOption.REPLACE_EXISTING);
		}
	}

	private ProfitBook read(String accountId)
	{
		String name = fileName(accountId);
		try
		{
			Filepath file = dir.get().joinSegment(name);
			if (!file.isFile())
			{
				return new ProfitBook();
			}
			try (BufferedReader r = file.openBufferedReader())
			{
				ProfitBook b = gson.fromJson(r, ProfitBook.class);
				return b == null ? new ProfitBook() : b.sanitized();
			}
		}
		catch (IOException | RuntimeException ex)
		{
			log.warn("Couldn't read profit file {}; starting from zero (Rebuild recounts it from the trade log)", name, ex);
			return new ProfitBook();
		}
	}

	private void publish()
	{
		if (closed)
		{
			return;
		}
		if (logAvailable == null)
		{
			try
			{
				logAvailable = !LogFiles.newestFirst(LocalTradeLog.listNames(dir.get())).isEmpty();
			}
			catch (IOException ex)
			{
				logAvailable = false;
			}
		}
		ProfitBook b = book == null ? new ProfitBook() : book;
		listener.accept(b.snapshot(LocalDate.now(clock), rebuild != null, logAvailable));
	}

	// For tests.

	boolean isRebuilding()
	{
		return rebuild != null;
	}

	ProfitBook book()
	{
		return book;
	}
}

package com.hardcoreworldtoolkit;

import java.io.Closeable;
import java.io.IOException;
import java.nio.ByteBuffer;
import java.nio.channels.SeekableByteChannel;
import java.nio.charset.StandardCharsets;

/**
 * Reads a text file's lines from the end towards the start, a chunk at a time, so the newest lines of a large
 * append-only log can be read without parsing the rest. Lines are split on the '\n' byte, which never occurs inside
 * a multi-byte UTF-8 sequence, so a character split across two chunks is decoded correctly. A trailing '\r' is
 * removed and empty lines are skipped. Not thread safe.
 */
final class ReverseLineReader implements Closeable
{
	static final int DEFAULT_CHUNK = 64 * 1024;

	private final SeekableByteChannel channel;
	private final int chunk;
	/** File offset of {@code data[0]}; everything before it hasn't been read yet. */
	private long pos;
	/** Bytes [pos, pos + len) of the file that haven't been returned as lines yet. */
	private byte[] data = new byte[0];
	private int len;

	ReverseLineReader(SeekableByteChannel channel) throws IOException
	{
		this(channel, DEFAULT_CHUNK);
	}

	ReverseLineReader(SeekableByteChannel channel, int chunkSize) throws IOException
	{
		if (chunkSize < 1)
		{
			throw new IllegalArgumentException("chunk size " + chunkSize);
		}
		this.channel = channel;
		this.chunk = chunkSize;
		this.pos = channel.size();
	}

	/** The line before the one returned last (the last line on the first call), or null at the start of the file. */
	String readLine() throws IOException
	{
		while (true)
		{
			int nl = lastNewline();
			if (nl >= 0)
			{
				String line = decode(nl + 1, len);
				len = nl;
				if (line != null)
				{
					return line;
				}
				continue;
			}
			if (pos == 0)
			{
				// The first line of the file has no newline before it.
				String line = decode(0, len);
				len = 0;
				return line;
			}
			readChunk();
		}
	}

	private int lastNewline()
	{
		for (int i = len - 1; i >= 0; i--)
		{
			if (data[i] == '\n')
			{
				return i;
			}
		}
		return -1;
	}

	/** Bytes [from, to) as a line without a trailing '\r', or null if that leaves it empty. */
	private String decode(int from, int to)
	{
		if (to > from && data[to - 1] == '\r')
		{
			to--;
		}
		return to > from ? new String(data, from, to - from, StandardCharsets.UTF_8) : null;
	}

	/** Read the chunk before {@link #pos} in front of the bytes not yet returned. */
	private void readChunk() throws IOException
	{
		int n = (int) Math.min(chunk, pos);
		byte[] next = new byte[n + len];
		System.arraycopy(data, 0, next, n, len);
		ByteBuffer buf = ByteBuffer.wrap(next, 0, n);
		long start = pos - n;
		channel.position(start);
		while (buf.hasRemaining())
		{
			if (channel.read(buf) < 0)
			{
				throw new IOException("File shrank while reading");
			}
		}
		data = next;
		len += n;
		pos = start;
	}

	@Override
	public void close() throws IOException
	{
		channel.close();
	}
}

package com.hardcoreworldtoolkit;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import okhttp3.CacheControl;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;

/**
 * Every HTTP request the plugin makes, one method per request. They all go to the Hardcore World Tool Kit server
 * through RuneLite's OkHttpClient; no other class calls OkHttp.
 * <p>
 * Opt-in: each method first checks the "Connect to Hardcore World Tool Kit server" setting (uploads also "Share my
 * trades") and throws {@link NotConnectedException} when it is off, so nothing is sent unless the player connected.
 * The rest of each method is only the request, enqueued on OkHttp's thread pool; the callback gets the response on an
 * OkHttp thread. Request bodies are built, and responses read, by the callers: {@link InstallAuth},
 * {@link TradeUploader}, {@link DataDeletion} and {@link MarketClient}.
 */
class ServerApi
{
	private static final MediaType JSON = MediaType.parse("application/json; charset=utf-8");
	/** No Cache-Control header: OkHttp's normal caching. */
	private static final CacheControl NORMAL_CACHE = new CacheControl.Builder().build();

	/** Thrown by the request methods while the setting they need is off. Nothing was sent. */
	static final class NotConnectedException extends IllegalStateException
	{
		NotConnectedException(String message)
		{
			super(message);
		}
	}

	private final OkHttpClient http;
	private final Gson gson;
	private final HardcoreWorldToolKitConfig config;
	private final HttpUrl registerUrl;
	private final HttpUrl submitUrl;
	private final HttpUrl meUrl;
	private final HttpUrl deathsUrl;

	ServerApi(OkHttpClient http, Gson gson, HttpUrl base, HardcoreWorldToolKitConfig config)
	{
		this.http = http;
		this.gson = gson;
		this.config = config;
		this.registerUrl = base.newBuilder().addPathSegments("v1/register").build();
		this.submitUrl = base.newBuilder().addPathSegments("v1/submit").build();
		this.meUrl = base.newBuilder().addPathSegments("v1/me").build();
		this.deathsUrl = base.newBuilder().addPathSegments("v1/deaths").build();
	}

	/** HTTP request: POST v1/register with the install id, for a new install token. Only while connected. */
	void postRegister(JsonObject body, Callback callback)
	{
		if (!config.connected())
		{
			throw new NotConnectedException("Not connected: registration not sent");
		}
		http.newCall(new Request.Builder()
			.url(registerUrl)
			.post(RequestBody.create(JSON, gson.toJson(body)))
			.build()).enqueue(callback);
	}

	/** HTTP request: POST v1/submit, a batch of trades with the install token. Only while connected and sharing. */
	void postSubmit(String token, JsonObject body, Callback callback)
	{
		if (!config.connected() || !config.shareTrades())
		{
			throw new NotConnectedException("Not connected or not sharing: upload not sent");
		}
		http.newCall(new Request.Builder()
			.url(submitUrl)
			.header("Authorization", "Bearer " + token)
			.post(RequestBody.create(JSON, gson.toJson(body)))
			.build()).enqueue(callback);
	}

	/** HTTP request: POST v1/deaths, one death (region, killer, own tile) with the install token. Only while connected and sharing deaths. */
	void postDeath(String token, JsonObject body, Callback callback)
	{
		if (!config.connected() || !config.shareDeaths())
		{
			throw new NotConnectedException("Not connected or not sharing deaths: death not sent");
		}
		http.newCall(new Request.Builder()
			.url(deathsUrl)
			.header("Authorization", "Bearer " + token)
			.post(RequestBody.create(JSON, gson.toJson(body)))
			.build()).enqueue(callback);
	}

	/**
	 * HTTP request: DELETE v1/me with the install token, deleting everything this install shared ("Delete my shared
	 * data"). Only while connected.
	 */
	void deleteMe(String token, JsonObject body, Callback callback)
	{
		if (!config.connected())
		{
			throw new NotConnectedException("Not connected: deletion not sent");
		}
		http.newCall(new Request.Builder()
			.url(meUrl)
			.header("Authorization", "Bearer " + token)
			.delete(RequestBody.create(JSON, gson.toJson(body)))
			.build()).enqueue(callback);
	}

	/**
	 * HTTP request: GET market data from the server, one of v1/recent, v1/item/{id}, v1/item/{id}/series, v1/items or
	 * v1/swap-rate (the URL is built by {@link MarketClient}). No token. Only while connected.
	 *
	 * @param fresh skip any HTTP cache
	 */
	void getMarketData(HttpUrl url, boolean fresh, Callback callback)
	{
		if (!config.connected())
		{
			throw new NotConnectedException("Not connected: market request not sent");
		}
		http.newCall(new Request.Builder()
			.url(url)
			.cacheControl(fresh ? CacheControl.FORCE_NETWORK : NORMAL_CACHE)
			.get()
			.build()).enqueue(callback);
	}
}

package com.hardcoreworldtoolkit;

import java.util.Random;
import java.util.function.LongSupplier;

/**
 * Waits before asking again when the server says it is overloaded (503 or 429) or can't be reached: at least its
 * Retry-After, otherwise 30 s, doubling up to 5 minutes, with some random spread so players don't all retry together.
 * One success ends it. Thread safe: requests start on several threads, responses arrive on OkHttp's.
 */
final class ServerBackoff
{
	private static final long BASE_MS = 30_000L;
	private static final long MAX_MS = 300_000L;
	private static final double SPREAD = 0.2;

	private final LongSupplier clock;
	private final Random random;
	private long until;
	private int failures;

	ServerBackoff(LongSupplier clock, Random random)
	{
		this.clock = clock;
		this.random = random;
	}

	/** True while requests should wait. */
	synchronized boolean waiting()
	{
		return clock.getAsLong() < until;
	}

	/** @param retryAfterSeconds the server's Retry-After, or 0 if it gave none */
	synchronized void failed(long retryAfterSeconds)
	{
		long wait = BASE_MS << Math.min(failures, 4);
		failures++;
		wait = Math.max(Math.min(wait, MAX_MS), Math.min(retryAfterSeconds * 1000L, MAX_MS));
		long spread = (long) (wait * SPREAD * random.nextDouble());
		until = clock.getAsLong() + wait + spread;
	}

	synchronized void succeeded()
	{
		failures = 0;
		until = 0;
	}

	/** Records a response: 503 / 429 start or lengthen the wait, any other answer below 500 ends it. */
	void observe(int code, String retryAfter)
	{
		if (code == 503 || code == 429)
		{
			failed(parseSeconds(retryAfter));
		}
		else if (code < 500)
		{
			succeeded();
		}
	}

	static long parseSeconds(String value)
	{
		try
		{
			return value == null ? 0 : Math.max(0, Long.parseLong(value.trim()));
		}
		catch (NumberFormatException e)
		{
			return 0;
		}
	}
}

package com.hardcoreworldtoolkit;

import java.util.List;

/**
 * This install's identity towards the collection server: the random install id and the install token the server
 * issued for it (POST v1/register). The token only authorises this install's uploads and the deletion of its data;
 * it must never be logged. Implementations are thread-safe (used from the executor, OkHttp threads and the EDT).
 */
interface ServerIdentity
{
	/** The install id, created (and saved) on first use. */
	String installId();

	/** The token issued for the current install id, or null when there is none yet. */
	String token();

	/** Store {@code token} for {@code installId}; ignored when the install id has changed meanwhile. */
	void setToken(String installId, String token);

	/** Forget the token of {@code installId} (the server refused it); ignored when the install id has changed. */
	void clearToken(String installId);

	/** Start over as a new, unlinkable source: a new random install id and no token. Returns the new id. */
	String rotateInstallId();

	/**
	 * Like {@link #rotateInstallId()}, for when the server gave the current id to another token (this PC's key was lost
	 * or replaced): what this PC shared under the old id may still be on the server, and can no longer be deleted from
	 * here, so the old id is remembered ({@link #lostInstallIds()}) for the player to quote in an erasure request.
	 */
	String replaceInstallId();

	/** Older install ids of this PC whose key was lost (oldest first; not secrets). */
	List<String> lostInstallIds();
}

package com.hardcoreworldtoolkit;

import com.google.gson.Gson;
import java.io.IOException;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.UUID;
import java.util.function.Consumer;
import java.util.function.Supplier;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;

/**
 * Per-account offer state and GE History signatures (in the RuneLite profile config), plus the install id and install
 * token ({@link ServerIdentity}, in a file in the plugin's data folder: {@link IdentityFile}). Each account / game mode
 * has its own RuneLite profile.
 */
@Slf4j
class TrackerStore implements ServerIdentity
{
	private static final String KEY_SLOT = "slot";
	private static final String KEY_COMPLETED = "completed";
	private static final String KEY_HISTORY = "history";
	/** Length of a UUID string; anything else stored under the install id key is replaced. */
	static final int INSTALL_ID_LENGTH = 36;

	private final ConfigManager configManager;
	private final Gson gson;
	private final InstallIdentity identity;
	private final IdentityFile identityFile;
	/** The plugin's data folder (set in startUp, before anything uses the identity). */
	private volatile ProfitStore.Dir dataDir;
	/** Read on the client thread, reset from startUp/shutDown. */
	private volatile String loadedProfile;

	@Inject
	TrackerStore(ConfigManager configManager, Gson gson)
	{
		this.configManager = configManager;
		this.gson = gson;
		this.identityFile = new IdentityFile(() ->
		{
			ProfitStore.Dir d = dataDir;
			if (d == null)
			{
				throw new IOException("no data folder yet");
			}
			return d.get();
		}, gson);
		this.identity = new InstallIdentity(identityFile, () -> UUID.randomUUID().toString());
	}

	/**
	 * Where the install id and token file lives (the plugin's data folder) and its name ({@link IdentityFile#fileNameFor}:
	 * one per server). Call before using the identity.
	 */
	void useDataDir(ProfitStore.Dir dir, String identityFileName)
	{
		this.dataDir = dir;
		identityFile.useFileName(identityFileName);
	}

	/** Reads the identity file now (off the client thread and the EDT: the executor at startUp). */
	void loadIdentity()
	{
		identity.token();
	}

	/**
	 * Whether this PC holds a token, without reading the file when that hasn't happened yet (EDT callers; startUp
	 * reads it on the executor right away).
	 */
	boolean hasToken()
	{
		synchronized (identity)
		{
			return identityFile.loaded() && identity.token() != null;
		}
	}

	/** Forget which profile was loaded, so the next {@link #ensureLoaded} reads it again. */
	void reset()
	{
		loadedProfile = null;
	}

	/** Load slot state for the current account into {@code tracker}, unless it's already loaded. */
	boolean ensureLoaded(OfferTracker tracker)
	{
		String profile = configManager.getRSProfileKey();
		if (profile == null)
		{
			return false;
		}
		if (profile.equals(loadedProfile))
		{
			return true;
		}
		for (int slot = 0; slot < OfferTracker.SLOTS; slot++)
		{
			String json = configManager.getRSProfileConfiguration(HardcoreWorldToolKitConfig.GROUP, KEY_SLOT + slot);
			OfferTracker.SlotState state = null;
			if (json != null)
			{
				try
				{
					state = gson.fromJson(json, OfferTracker.SlotState.class);
				}
				catch (RuntimeException ex)
				{
					log.debug("Bad saved slot {}", slot, ex);
				}
			}
			tracker.setSlot(slot, state);
		}
		tracker.setCompleted(loadList(KEY_COMPLETED));
		loadedProfile = profile;
		return true;
	}

	void saveSlot(OfferTracker tracker, int slot)
	{
		OfferTracker.SlotState s = tracker.getSlot(slot);
		if (s == null)
		{
			configManager.unsetRSProfileConfiguration(HardcoreWorldToolKitConfig.GROUP, KEY_SLOT + slot);
		}
		else
		{
			setProfileValue(KEY_SLOT + slot, gson.toJson(s));
		}
	}

	void saveCompleted(OfferTracker tracker)
	{
		setProfileValue(KEY_COMPLETED, gson.toJson(tracker.getCompleted()));
	}

	/** Row signatures from the last GE History read, newest first. */
	List<String> loadHistory()
	{
		return loadList(KEY_HISTORY);
	}

	/**
	 * True once this account's GE History has been read at least once. {@link #saveHistory} always writes the key
	 * (even an empty list), so players who imported before this existed count too. Needs a loaded profile.
	 */
	boolean historyImported()
	{
		return configManager.getRSProfileConfiguration(HardcoreWorldToolKitConfig.GROUP, KEY_HISTORY) != null;
	}

	/** The RS profile {@link #ensureLoaded} last loaded, or null. */
	String loadedProfile()
	{
		return loadedProfile;
	}

	void saveHistory(List<String> signatures)
	{
		setProfileValue(KEY_HISTORY, gson.toJson(signatures));
	}

	/**
	 * Random id for this RuneLite install (pseudonymous: the server stores it with the hashed account id). Never the
	 * player's name. Synchronized (in {@link InstallIdentity}) so that two first-run callers (the upload executor and a
	 * shutdown flush) can't each create and save a different id.
	 */
	@Override
	public String installId()
	{
		return identity.installId();
	}

	/** The install token, or null. Never log it. */
	@Override
	public String token()
	{
		return identity.token();
	}

	@Override
	public void setToken(String installId, String token)
	{
		identity.setToken(installId, token);
	}

	@Override
	public void clearToken(String installId)
	{
		identity.clearToken(installId);
	}

	@Override
	public String rotateInstallId()
	{
		return identity.rotateInstallId();
	}

	@Override
	public String replaceInstallId()
	{
		return identity.replaceInstallId();
	}

	@Override
	public List<String> lostInstallIds()
	{
		return identity.lostInstallIds();
	}

	/** The stored id, or a new one (saved) when there is none or it isn't a UUID. Not atomic; callers lock. */
	static String installId(Supplier<String> read, Consumer<String> write, Supplier<String> newId)
	{
		String id = read.get();
		if (id == null || id.length() != INSTALL_ID_LENGTH)
		{
			id = newId.get();
			write.accept(id);
		}
		return id;
	}

	private void setProfileValue(String key, String value)
	{
		configManager.setRSProfileConfiguration(HardcoreWorldToolKitConfig.GROUP, key, value);
	}

	private List<String> loadList(String key)
	{
		String json = configManager.getRSProfileConfiguration(HardcoreWorldToolKitConfig.GROUP, key);
		if (json == null)
		{
			return new ArrayList<>();
		}
		try
		{
			String[] list = gson.fromJson(json, String[].class);
			return list == null ? new ArrayList<>() : new ArrayList<>(Arrays.asList(list));
		}
		catch (RuntimeException ex)
		{
			return new ArrayList<>();
		}
	}
}

package com.hardcoreworldtoolkit;

import lombok.Builder;
import lombok.Value;

/**
 * One observed Grand Exchange event. Field names match the server's JSON contract.
 */
@Value
@Builder(toBuilder = true)
public class TradeEvent
{
	public static final String PLACED = "placed";
	public static final String FILL = "fill";
	public static final String CANCELLED = "cancelled";
	public static final String HISTORY = "history";

	public static final String BUY = "buy";
	public static final String SELL = "sell";

	/**
	 * Unique, stable id for this event (derived from the offer key, or "hist:" plus a random UUID for a GE History row),
	 * so retried uploads are de-duplicated server side.
	 */
	String id;
	String kind;
	/** {@link #BUY} or {@link #SELL}. */
	String side;
	int itemId;
	/** placed: total quantity; fill/history: units traded; cancelled: units left unfilled. */
	int qty;
	/**
	 * Per-item price: offer price for placed/cancelled, actual average price for fill/history.
	 */
	long price;
	/** Total gp that changed hands (fill/history). */
	Long total;
	Integer slot;
	String offerKey;
	/** Unix seconds when the event was observed. */
	long ts;
	/** True when the event happened while logged out (or before install) and ts is only when we noticed it. */
	boolean late;
	/** fill only: cumulative units filled on the offer after this event. */
	Integer filled;
	/** Late fills only: last time we saw this offer before the fill, so the server can pair it with the counterparty. */
	Long since;
	int world;
	/** Item name, for display in the panel and the local log. */
	String name;

	/**
	 * True for a completed trade (a live fill or a GE History row), as opposed to an offer placed or cancelled.
	 */
	public static boolean isTrade(String kind)
	{
		return FILL.equals(kind) || HISTORY.equals(kind);
	}

	static String sideOf(boolean buy)
	{
		return buy ? BUY : SELL;
	}

	/** Average per-item price of {@code qty} units that cost {@code total} gp altogether. */
	static long avgPrice(long total, int qty)
	{
		return Math.round((double) total / qty);
	}
}

package com.hardcoreworldtoolkit;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import java.awt.image.BufferedImage;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Base64;
import java.util.Deque;
import java.util.HashSet;
import java.util.Iterator;
import java.util.List;
import java.util.Map;
import java.util.Random;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ConcurrentLinkedDeque;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicReference;
import java.util.function.BooleanSupplier;
import java.util.function.Consumer;
import javax.imageio.ImageIO;
import javax.imageio.ImageWriter;
import javax.imageio.stream.ImageOutputStream;
import javax.imageio.stream.MemoryCacheImageOutputStream;
import lombok.Value;
import lombok.extern.slf4j.Slf4j;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.Response;

/**
 * Queues trade events and ships them to the collection server in batches. Every request goes through
 * {@link ServerApi}, on OkHttp's own thread pool via enqueue(). Item icons are only referenced when added (on the
 * client thread) and PNG-encoded later, in {@link #flush}, off the client thread.
 * <p>
 * One request carries one world and one account: events and open offers are grouped by {@link BatchKey}.
 * <p>
 * Every upload carries the install token of the {@link ServerIdentity} ({@code Authorization: Bearer}).
 * When there is no token yet, the flush first registers (POST v1/register) as part of the same in-flight chain; a 409
 * there switches to a new random install id. A 401 on submit clears the token, registers again and resends the batch
 * once per flush; a second 401 leaves the queue as it is until the next flush. The token is never logged.
 */
@Slf4j
class TradeUploader
{
	private static final int MAX_BATCH = 200;
	private static final int MAX_QUEUE = 5000;
	private static final int MAX_ITEMS_PER_BATCH = 50;

	private final ServerApi api;
	private final Gson gson;
	/** Told the item ids of each batch of events the server accepted (on an OkHttp thread). */
	private final Consumer<Set<Integer>> onSent;

	private final Deque<Queued> queue = new ConcurrentLinkedDeque<>();
	/** Item names/icons waiting to be sent, keyed by item id. */
	private final Map<Integer, ItemInfo> pendingItems = new ConcurrentHashMap<>();
	/** Items the server already has. */
	private final Set<Integer> sentItems = ConcurrentHashMap.newKeySet();
	/** Latest open offers per world and account, replaced wholesale on each login/heartbeat. */
	private final Map<BatchKey, List<JsonObject>> pendingOffers = new ConcurrentHashMap<>();
	private final AtomicBoolean inFlight = new AtomicBoolean();
	private final ServerIdentity identity;
	private final InstallAuth auth;
	/** Whether uploading (and registering) is allowed now: connected and sharing. Re-checked before each request. */
	private final BooleanSupplier allowed;
	/** While paused (a data deletion is running), flush does nothing. */
	private volatile boolean paused;
	/** Run once the in-flight chain (if any) has finished; see {@link #whenIdle}. */
	private final AtomicReference<Runnable> idleAction = new AtomicReference<>();

	/** A queued event and the hashed account ({@link AccountId}) it belongs to; null when unknown. */
	@Value
	static class Queued
	{
		TradeEvent event;
		String accountId;
	}

	/** What one request may contain: a single world and a single account (null account = unknown). */
	@Value
	static class BatchKey
	{
		int world;
		String accountId;

		static BatchKey of(Queued q)
		{
			return new BatchKey(q.getEvent().getWorld(), q.getAccountId());
		}
	}

	static class ItemInfo
	{
		final int id;
		final String name;
		/** GE buy limit (RuneLite's ItemStats), or 0 when unknown. */
		final int limit;
		/** The item's image, encoded into {@link #icon} during flush once {@link #imageReady} is set. */
		volatile BufferedImage image;
		/** Set when the image has been rendered (AsyncBufferedImage starts out blank). */
		volatile boolean imageReady;
		/** Base64 PNG, or null if not encoded yet. */
		volatile String icon;

		ItemInfo(int id, String name)
		{
			this(id, name, 0);
		}

		ItemInfo(int id, String name, int limit)
		{
			this.id = id;
			this.name = name;
			this.limit = Math.max(0, limit);
		}
	}

	/** Shared with the market client (see setBackoff), so one busy answer pauses both. */
	private ServerBackoff backoff = new ServerBackoff(System::currentTimeMillis, new Random());

	void setBackoff(ServerBackoff backoff)
	{
		this.backoff = backoff;
	}

	/**
	 * The plugin's uploader: uploads carry the install token, registering first when there is none.
	 *
	 * @param onSent   called with the item ids of the events in each batch the server accepted (not for batches with
	 *                 only open offers or items). Runs on an OkHttp thread and must be quick.
	 * @param identity the install id and token
	 * @param allowed  whether uploading (and registering) is allowed now, i.e. connected and sharing; checked by
	 *                 {@link #flush()} and again before each follow-up request of a chain
	 */
	TradeUploader(ServerApi api, Gson gson, Consumer<Set<Integer>> onSent, ServerIdentity identity,
		BooleanSupplier allowed)
	{
		this.api = api;
		this.gson = gson;
		this.onSent = onSent;
		this.identity = identity;
		this.auth = new InstallAuth(api, gson, identity);
		this.allowed = allowed;
	}

	/** @param accountId the hashed account id ({@link AccountId}), or null when unknown */
	void add(TradeEvent e, String accountId)
	{
		queue.addLast(new Queued(e, accountId));
		while (queue.size() > MAX_QUEUE)
		{
			queue.pollFirst();
		}
	}

	boolean needsItem(int itemId)
	{
		return !sentItems.contains(itemId) && !pendingItems.containsKey(itemId);
	}

	/** Queue an item's name and image. Cheap: the image is only referenced here and PNG-encoded during flush. */
	void addItem(int itemId, String name, BufferedImage image)
	{
		addItem(itemId, name, image, 0);
	}

	/** {@link #addItem(int, String, BufferedImage)} with the item's GE buy limit (0 = unknown). */
	void addItem(int itemId, String name, BufferedImage image, int limit)
	{
		ItemInfo info = new ItemInfo(itemId, name, limit);
		info.image = image;
		pendingItems.put(itemId, info);
	}

	/** The item's image has finished rendering, so flush may encode it. Cheap; safe on the client thread. */
	void setIcon(int itemId, BufferedImage image)
	{
		ItemInfo info = pendingItems.get(itemId);
		if (info != null)
		{
			info.image = image;
			info.imageReady = true;
		}
	}

	void setOpenOffers(int world, String accountId, List<JsonObject> offers)
	{
		pendingOffers.put(new BatchKey(world, accountId), offers);
	}

	/** Everything still waiting to be sent, oldest first (for {@link UploadSpool}). Includes a batch in flight. */
	List<Queued> pending()
	{
		return new ArrayList<>(queue);
	}

	/** Put spooled uploads from a previous session back, ahead of anything queued since; the oldest go if too many. */
	void restore(List<Queued> spooled)
	{
		for (int i = spooled.size() - 1; i >= 0; i--)
		{
			queue.addFirst(spooled.get(i));
		}
		while (queue.size() > MAX_QUEUE)
		{
			queue.pollFirst();
		}
	}

	/** Drop everything not sent yet. Items already sent are remembered, since the server keeps them. */
	void clear()
	{
		queue.clear();
		pendingItems.clear();
		pendingOffers.clear();
	}

	/**
	 * Send one batch with the install token, registering first when there is none. Does nothing while not
	 * {@code allowed}, while paused, while another request is running, or when there's nothing to send (so nothing,
	 * registration included, is ever sent before Connect). Never throws: a failure here would otherwise leave
	 * {@link #inFlight} stuck, or kill the scheduled task that calls this.
	 */
	void flush()
	{
		// The in-flight flag is claimed before the queues are looked at, so a concurrent clear() can't leave it set.
		if (paused || !allowed.getAsBoolean() || !claim())
		{
			return;
		}
		boolean enqueued = false;
		try
		{
			if (firstKey() == null)
			{
				return;
			}
			String installId = identity.installId();
			String token = identity.token();
			if (token == null)
			{
				enqueued = true;
				registerThenSend();
			}
			else
			{
				enqueued = send(installId, token, false);
			}
		}
		catch (RuntimeException e)
		{
			log.warn("Trade upload failed", e);
		}
		finally
		{
			if (!enqueued)
			{
				release();
			}
		}
	}

	/**
	 * Part of an in-flight chain: register, then send the batch with the new token, for the id it was issued for.
	 * The chain always ends by releasing the in-flight flag.
	 */
	private void registerThenSend()
	{
		auth.register(true, r ->
		{
			boolean enqueued = false;
			try
			{
				if (r.getStatus() == InstallAuth.Status.OK && !paused && allowed.getAsBoolean())
				{
					// A fresh token: a 401 now means something else is wrong, so no further re-registration.
					enqueued = send(r.getInstallId(), r.getToken(), true);
				}
				else
				{
					log.debug("Upload registration: {} (HTTP {}), will retry", r.getStatus(), r.getCode());
				}
			}
			catch (RuntimeException e)
			{
				log.warn("Trade upload failed", e);
			}
			finally
			{
				if (!enqueued)
				{
					release();
				}
			}
		});
	}

	/** Take the in-flight flag; false when paused or a request is already running. */
	private boolean claim()
	{
		if (paused || !inFlight.compareAndSet(false, true))
		{
			return false;
		}
		if (paused)
		{
			release();
			return false;
		}
		return true;
	}

	/** End of an in-flight chain: clear the flag, then run a waiting {@link #whenIdle} action. */
	private void release()
	{
		inFlight.set(false);
		Runnable action = idleAction.getAndSet(null);
		if (action != null)
		{
			try
			{
				action.run();
			}
			catch (RuntimeException e)
			{
				log.warn("Upload idle action failed", e);
			}
		}
	}

	/** True while a request is running. For tests. */
	boolean isInFlight()
	{
		return inFlight.get();
	}

	/** True when events or open offers are waiting to be sent. For tests. */
	boolean hasPending()
	{
		return firstKey() != null;
	}

	/** Events waiting in the queue. For tests. */
	int queued()
	{
		return queue.size();
	}

	/** {@link #nextKey} for the oldest queued event. */
	private BatchKey firstKey()
	{
		return nextKey(queue.peekFirst(), pendingOffers);
	}

	/** Stop uploading: flush does nothing until {@link #resume()}. A request already running still completes. */
	void pause()
	{
		paused = true;
	}

	void resume()
	{
		paused = false;
	}

	boolean isPaused()
	{
		return paused;
	}

	/**
	 * Run {@code action} once no upload is in flight: right away (on this thread) when idle, else on the OkHttp
	 * thread that finishes the running chain. Never blocks. Call {@link #pause()} first, so no new upload starts in
	 * between.
	 */
	void whenIdle(Runnable action)
	{
		idleAction.set(action);
		if (inFlight.compareAndSet(false, true))
		{
			release();
		}
	}

	/**
	 * The world and account to send next: those of the oldest queued event, else of any pending open offers, else
	 * null when there's nothing to send. Copes with the offers map being emptied concurrently.
	 */
	static BatchKey nextKey(Queued head, Map<BatchKey, ?> offers)
	{
		if (head != null)
		{
			return BatchKey.of(head);
		}
		// ConcurrentHashMap iterators never throw on concurrent removal; an empty map just yields nothing.
		for (BatchKey key : offers.keySet())
		{
			return key;
		}
		return null;
	}

	/**
	 * Build and enqueue one request. Returns false (nothing enqueued) when there is nothing to send, or when no longer
	 * connected and sharing.
	 *
	 * @param token    the install token for {@code installId}
	 * @param reauthed the token was just issued in this chain, so a 401 isn't answered by registering again
	 */
	private boolean send(String installId, String token, boolean reauthed)
	{
		// One request = one world and one account.
		BatchKey key = firstKey();
		if (key == null)
		{
			return false;
		}

		List<Queued> batch = new ArrayList<>();
		List<TradeEvent> events = new ArrayList<>();
		for (Queued q : queue)
		{
			if (batch.size() >= MAX_BATCH)
			{
				break;
			}
			if (!key.equals(BatchKey.of(q)))
			{
				continue;
			}
			batch.add(q);
			events.add(q.getEvent());
		}

		List<JsonObject> offers = pendingOffers.get(key);

		List<ItemInfo> items = new ArrayList<>();
		for (ItemInfo info : pendingItems.values())
		{
			if (items.size() >= MAX_ITEMS_PER_BATCH)
			{
				break;
			}
			encodeIcon(info);
			items.add(info);
		}

		JsonObject body = buildBody(gson, installId, key, Instant.now().getEpochSecond(), events, offers, items);

		Callback callback = new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.debug("Trade upload failed, will retry", e);
				backoff.failed(0);
				release();
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				boolean continued = false;
				backoff.observe(response.code(), response.header("Retry-After"));
				try (response)
				{
					if (response.code() == 401)
					{
						if (!reauthed && !paused && allowed.getAsBoolean())
						{
							// The server doesn't accept this token (lost, or the install was deleted): get a new
							// one and resend the batch, once.
							log.debug("Trade upload got HTTP 401, registering again");
							identity.clearToken(installId);
							continued = true;
							registerThenSend();
						}
						else
						{
							log.debug("Trade upload got HTTP 401 again, will retry later");
						}
					}
					else if (response.isSuccessful())
					{
						queue.removeAll(batch);
						pendingOffers.remove(key, offers);
						for (ItemInfo info : items)
						{
							// Keep retrying items whose icon wasn't rendered yet.
							if (info.icon != null)
							{
								pendingItems.remove(info.id, info);
								sentItems.add(info.id);
							}
						}
						notifySent(events);
					}
					else if (response.code() == 400)
					{
						// Server rejected the payload; drop it rather than retry forever.
						log.debug("Trade upload rejected: {}", response.code());
						queue.removeAll(batch);
						pendingOffers.remove(key, offers);
					}
					else
					{
						log.debug("Trade upload got HTTP {}, will retry", response.code());
					}
				}
				catch (RuntimeException e)
				{
					log.warn("Trade upload response handling failed", e);
				}
				finally
				{
					if (!continued)
					{
						release();
					}
				}
			}
		};
		if (backoff.waiting())
		{
			// The server said it is overloaded: the batch stays queued for a later flush.
			log.debug("Server busy: upload not sent");
			return false;
		}
		try
		{
			api.postSubmit(token, body, callback);
		}
		catch (ServerApi.NotConnectedException e)
		{
			// Switched off since flush checked: nothing was sent, and the batch stays queued.
			log.debug(e.getMessage());
			return false;
		}
		return true;
	}

	private void notifySent(List<TradeEvent> events)
	{
		Set<Integer> ids = itemIds(events);
		if (ids.isEmpty())
		{
			return;
		}
		try
		{
			onSent.accept(ids);
		}
		catch (RuntimeException e)
		{
			log.warn("Upload listener failed", e);
		}
	}

	/** The distinct item ids of {@code events}. */
	static Set<Integer> itemIds(List<TradeEvent> events)
	{
		Set<Integer> ids = new HashSet<>();
		for (TradeEvent e : events)
		{
			ids.add(e.getItemId());
		}
		return ids;
	}

	/**
	 * The submit request body. Key names and order are the server's contract; "accountId" is newer, so it comes last
	 * and only when known (older servers ignore unknown fields).
	 */
	static JsonObject buildBody(Gson gson, String installId, BatchKey key, long sentAt, List<TradeEvent> batch,
		List<JsonObject> offers, List<ItemInfo> items)
	{
		JsonObject body = new JsonObject();
		body.addProperty("installId", installId);
		body.addProperty("world", key.getWorld());
		// Lets the server correct for this PC's clock when pairing buyer and seller reports.
		body.addProperty("sentAt", sentAt);
		body.add("events", gson.toJsonTree(batch));

		if (offers != null)
		{
			JsonArray arr = new JsonArray();
			offers.forEach(arr::add);
			body.add("offers", arr);
		}

		JsonArray itemArr = new JsonArray();
		for (ItemInfo info : items)
		{
			JsonObject o = new JsonObject();
			o.addProperty("id", info.id);
			o.addProperty("name", info.name);
			if (info.icon != null)
			{
				o.addProperty("icon", info.icon);
			}
			if (info.limit > 0)
			{
				// Newer field, last in the entry; older servers ignore it.
				o.addProperty("limit", info.limit);
			}
			itemArr.add(o);
		}
		body.add("items", itemArr);
		if (key.getAccountId() != null)
		{
			body.addProperty("accountId", key.getAccountId());
		}
		return body;
	}

	/** One open offer, as sent in the submit body's "offers" list. */
	static JsonObject offerJson(int slot, OfferTracker.SlotState s)
	{
		JsonObject o = new JsonObject();
		o.addProperty("slot", slot);
		o.addProperty("offerKey", s.getOfferKey());
		o.addProperty("side", TradeEvent.sideOf(s.isBuy()));
		o.addProperty("itemId", s.getItemId());
		o.addProperty("price", s.getPrice());
		o.addProperty("totalQty", s.getTotalQty());
		o.addProperty("filledQty", s.getSold());
		o.addProperty("placedAt", s.getPlacedAt());
		return o;
	}

	/** PNG-encode the item's image once it has rendered. Runs in flush, off the client thread. */
	static void encodeIcon(ItemInfo info)
	{
		BufferedImage img = info.image;
		if (info.icon == null && info.imageReady && img != null)
		{
			info.icon = encodePng(img);
		}
	}

	private static String encodePng(BufferedImage img)
	{
		if (img == null || isBlank(img))
		{
			return null;
		}
		// An in-memory stream: ImageIO.write to an OutputStream would buffer through a temp file on disk.
		Iterator<ImageWriter> writers = ImageIO.getImageWritersByFormatName("png");
		if (!writers.hasNext())
		{
			return null;
		}
		ImageWriter writer = writers.next();
		ByteArrayOutputStream out = new ByteArrayOutputStream();
		try (ImageOutputStream ios = new MemoryCacheImageOutputStream(out))
		{
			writer.setOutput(ios);
			writer.write(img);
		}
		catch (IOException e)
		{
			return null;
		}
		finally
		{
			writer.dispose();
		}
		return Base64.getEncoder().encodeToString(out.toByteArray());
	}

	/** AsyncBufferedImage starts fully transparent until the sprite is rendered. */
	private static boolean isBlank(BufferedImage img)
	{
		for (int y = 0; y < img.getHeight(); y++)
		{
			for (int x = 0; x < img.getWidth(); x++)
			{
				if ((img.getRGB(x, y) >>> 24) != 0)
				{
					return false;
				}
			}
		}
		return true;
	}
}

package com.hardcoreworldtoolkit;

import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import java.io.BufferedReader;
import java.io.BufferedWriter;
import java.io.IOException;
import java.nio.file.StandardCopyOption;
import java.nio.file.StandardOpenOption;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.util.Filepath;

/**
 * Uploads not sent yet, kept in {@value #FILE_NAME} in the plugin's data folder so closing RuneLite (or a crash)
 * doesn't lose them. The server ignores events it already has (it de-duplicates
 * by event id), so resending a spooled event that did reach it is harmless. The file is removed when nothing is waiting,
 * which includes when sharing is turned off (the queue is cleared then). Executor thread only: this is disk IO.
 */
@Slf4j
final class UploadSpool
{
	static final String FILE_NAME = "pending-uploads.json";

	/** The plugin's data folder; may do disk IO. */
	interface Dir
	{
		Filepath get() throws IOException;
	}

	private final Dir dir;
	private final Gson gson;
	/** What was last written, so an unchanged queue isn't rewritten every 30 seconds. */
	private List<TradeUploader.Queued> lastSaved = Collections.emptyList();
	/** A failed save was already logged as a warning. */
	private boolean warned;

	UploadSpool(Dir dir, Gson gson)
	{
		this.dir = dir;
		this.gson = gson;
	}

	/** The spooled uploads, oldest first; empty when there is no file or it can't be read. */
	List<TradeUploader.Queued> load()
	{
		try
		{
			Filepath file = dir.get().joinSegment(FILE_NAME);
			if (!file.exists())
			{
				return Collections.emptyList();
			}
			TradeUploader.Queued[] list;
			try (BufferedReader r = file.openBufferedReader())
			{
				list = gson.fromJson(r, TradeUploader.Queued[].class);
			}
			List<TradeUploader.Queued> out = new ArrayList<>();
			if (list != null)
			{
				for (TradeUploader.Queued q : list)
				{
					if (q != null && q.getEvent() != null && q.getEvent().getId() != null && q.getEvent().getKind() != null)
					{
						out.add(q);
					}
				}
			}
			lastSaved = out;
			return out;
		}
		catch (IOException | JsonParseException ex)
		{
			log.warn("Couldn't read the pending uploads file; those uploads are skipped", ex);
			return Collections.emptyList();
		}
	}

	/** Write what's still waiting (or remove the file when nothing is). Atomic: a temp file is moved into place. */
	void save(List<TradeUploader.Queued> pending)
	{
		if (pending.equals(lastSaved))
		{
			return;
		}
		try
		{
			Filepath folder = dir.get();
			Filepath file = folder.joinSegment(FILE_NAME);
			if (pending.isEmpty())
			{
				file.deleteIfExists();
			}
			else
			{
				if (!folder.exists())
				{
					folder.createDirectories();
				}
				Filepath tmp = folder.joinSegment(FILE_NAME + ".tmp");
				try (BufferedWriter w = tmp.openBufferedWriter(StandardOpenOption.CREATE, StandardOpenOption.TRUNCATE_EXISTING))
				{
					gson.toJson(pending.toArray(new TradeUploader.Queued[0]), w);
				}
				tmp.moveTo(file, StandardCopyOption.REPLACE_EXISTING);
			}
			lastSaved = new ArrayList<>(pending);
			warned = false;
		}
		catch (IOException ex)
		{
			// Retried every 30 seconds: warn once, then only at debug level until a save works again.
			if (!warned)
			{
				warned = true;
				log.warn("Couldn't save the pending uploads file", ex);
			}
			else
			{
				log.debug("Couldn't save the pending uploads file: {}", ex.getClass().getSimpleName());
			}
		}
	}
}

package com.hardcoreworldtoolkit.ui;

import com.hardcoreworldtoolkit.MarketData;
import java.util.ArrayList;
import java.util.List;

/**
 * The price chart's time ranges and the bucket size requested for each. The chart always spans the whole range,
 * whatever data comes back.
 */
enum ChartRange
{
	H24("24h", "24 hours", 86_400, "5m", 300, 6),
	D7("7d", "7 days", 7 * 86_400, "1h", 3_600, 3),
	D30("30d", "30 days", 30 * 86_400, "6h", 21_600, 2),
	D90("90d", "90 days", 90 * 86_400, "6h", 21_600, 3),
	Y1("1y", "year", 365 * 86_400, "24h", 86_400, 3);

	static final ChartRange DEFAULT = D7;

	private final String label;
	private final String longLabel;
	private final long seconds;
	private final String step;
	private final long stepSeconds;
	private final int maxGapBuckets;

	ChartRange(String label, String longLabel, long seconds, String step, long stepSeconds, int maxGapBuckets)
	{
		this.label = label;
		this.longLabel = longLabel;
		this.seconds = seconds;
		this.step = step;
		this.stepSeconds = stepSeconds;
		this.maxGapBuckets = maxGapBuckets;
	}

	/** Button text, and the server's name for the range (the series request's range parameter). */
	String label()
	{
		return label;
	}

	/** For "No trades in the last ...". */
	String longLabel()
	{
		return longLabel;
	}

	long seconds()
	{
		return seconds;
	}

	/** The server's name for the bucket size requested with this range (the step parameter). */
	String step()
	{
		return step;
	}

	long stepSeconds()
	{
		return stepSeconds;
	}

	/** Two points further apart than this many buckets aren't joined by a line. */
	int maxGapBuckets()
	{
		return maxGapBuckets;
	}

	/**
	 * The buckets overlapping the range ending at {@code now} (unix s), in time order: a bucket that starts before
	 * the range but ends inside it is kept (its trades are in the range). Older servers ignore the range and send more
	 * history, so this always runs.
	 */
	List<MarketData.Point> trim(List<MarketData.Point> points, long now)
	{
		List<MarketData.Point> out = new ArrayList<>();
		if (points == null)
		{
			return out;
		}
		long from = now - seconds;
		for (MarketData.Point p : points)
		{
			if (p != null && p.getTimestamp() + stepSeconds() > from)
			{
				out.add(p);
			}
		}
		out.sort((a, b) -> Long.compare(a.getTimestamp(), b.getTimestamp()));
		return out;
	}
}

