/**
 * Home card: the "Get started" card (when there is something to set up), your open offers, your profit, Market / My trades tabs, an "updated" line
 * with a refresh button, a stats line and the list. The two lists are separate {@link RowList}s, so switching tabs
 * or refreshing never rebuilds rows that are already there. EDT only.
 */
class HomeView
{
	private final JPanel panel = column();
	private final JPanel tabs = new JPanel(new GridLayout(1, 3, 0, 0));
	private final JLabel statsLabel = mutedLabel("");
	/** The bond rate row, above the tabs; hidden until the server has a rate. */
	private final JPanel bond = new JPanel(new BorderLayout());
	private final ItemManager itemManager;
	private final BiConsumer<Integer, String> onOpen;
	private final JLabel updatedLabel = mutedLabel("");
	/** "Updated Xs ago" plus the refresh button; only on the Market tab once it has data. */
	private final JPanel updatedRow = new JPanel(new BorderLayout(4, 0));
	private final JTextComponent message = (JTextComponent) wrapText("", ColorScheme.LIGHT_GRAY_COLOR);
	private final RowList<MarketRows.Row> marketList;
	private final RowList<RowList.Keyed<TradeEvent>> mineList;
	private final RowList<MarketData.Flip> flipsList;
	private final RowList<MarketData.Gap> gapsList;
	private final JPanel subTabs = new JPanel(new FlowLayout(FlowLayout.CENTER, 0, 0));

	/** 0 Market, 1 Flips, 2 Gaps. */
	private int tab;
	/** Under Market: My trades instead of Live. */
	private boolean showMine;
	/** Epoch ms of the last successful market load, or 0. */
	private long lastUpdated;
	private boolean hasMarketData;
	/** The Market tab's stats text from its last load, put back when switching to it. */
	private String marketStats = "";
	/** Why the last market refresh failed, while its old data is still shown; null if it didn't. */
	private String failed;

	/**
	 * @param welcome   the "Get started" card, shown above the tabs (it hides itself when not needed)
	 * @param offers    "Your offers", below the welcome card (it hides itself when you have none)
	 * @param profit    "Profit", below your offers (it hides itself until there are numbers)
	 * @param onTab     run when a tab is clicked, to load it
	 * @param onRefresh the refresh button
	 * @param onOpen    opens an item from a row
	 */
	HomeView(ItemManager itemManager, JComponent welcome, JComponent offers, JComponent profit, Runnable onTab, Runnable onRefresh,
		BiConsumer<Integer, String> onOpen)
	{
		this.itemManager = itemManager;
		this.onOpen = onOpen;
		marketList = new RowList<>(r -> r.getEvent().getId(), r -> when(r.getEvent().getKind(), r.getEvent().getReceivedAt()),
			r -> marketRow(itemManager, r, onOpen));
		marketList.setEmptyText("No trades yet.");
		mineList = new RowList<>(k -> k.key, k -> when(k.value.getKind(), k.value.getTs()),
			k -> row(itemManager, k.value.getItemId(), k.value.getName(), k.value.getKind(), k.value.getSide(),
				k.value.getQty(), k.value.getPrice(), k.value.getTs(), onOpen));
		mineList.setEmptyText("No trades recorded yet. Trade on a Hardcore World or open your GE History.");
		flipsList = new RowList<>(f -> f.getId(), f -> f.getBuy() + ":" + f.getSell() + ":" + f.getQty() + ":" + f.getProfitHigh(),
			f -> tradeRow(itemManager, f.getId(), f.getName(), compact(f.getBuy()) + " \u2192 " + compact(f.getSell()) + " \u00b7 " + compact(f.getQty()),
				"+" + compact(f.getProfitLow()) + "\u2013" + compact(f.getProfitHigh()), true, onOpen));
		flipsList.setEmptyText("No flips for this much gold right now.");
		gapsList = new RowList<>(g -> g.getId(), g -> g.getWanted() + ":" + g.getBid() + ":" + g.getOffered() + ":" + g.getRevenue(),
			g -> tradeRow(itemManager, g.getId(), g.getName(), compact(g.getWanted()) + " @ " + compact(g.getBid()) + " \u00b7 " + compact(g.getOffered()) + " sell",
				compact(g.getRevenue()) + "/h", true, onOpen));
		gapsList.setEmptyText("No gaps right now.");

		tabs.setOpaque(false);
		JButton marketTab = tabButton("Market");
		JButton flips = tabButton("Flips");
		JButton gaps = tabButton("Gaps");
		JButton live = segButton("Live");
		JButton mine = segButton("My trades");
		Runnable style = () ->
		{
			styleTab(marketTab, tab == 0);
			styleTab(flips, tab == 1);
			styleTab(gaps, tab == 2);
			styleSeg(live, !showMine);
			styleSeg(mine, showMine);
			subTabs.setVisible(tab == 0 && tabs.isVisible());
		};
		marketTab.addActionListener(e -> selectTab(0, showMine, style, onTab));
		flips.addActionListener(e -> selectTab(1, showMine, style, onTab));
		gaps.addActionListener(e -> selectTab(2, showMine, style, onTab));
		live.addActionListener(e -> selectTab(0, false, style, onTab));
		mine.addActionListener(e -> selectTab(0, true, style, onTab));
		style.run();
		tabs.add(marketTab);
		tabs.add(flips);
		tabs.add(gaps);
		JPanel toggle = new JPanel(new GridLayout(1, 2, 0, 0));
		toggle.setBorder(new LineBorder(ColorScheme.MEDIUM_GRAY_COLOR));
		toggle.add(live);
		toggle.add(mine);
		subTabs.setOpaque(false);
		subTabs.setBorder(new EmptyBorder(10, 0, 8, 0));
		subTabs.add(toggle);
		subTabs.setMaximumSize(new Dimension(Integer.MAX_VALUE, 52));
		subTabs.setAlignmentX(Component.LEFT_ALIGNMENT);
		tabs.setMaximumSize(new Dimension(Integer.MAX_VALUE, 28));
		tabs.setAlignmentX(Component.LEFT_ALIGNMENT);

		updatedRow.setOpaque(false);
		updatedRow.setVisible(false);
		updatedRow.add(updatedLabel, BorderLayout.CENTER);
		JButton refresh = iconButton(Icons.refresh(), "Refresh now", 22);
		refresh.addActionListener(e -> onRefresh.run());
		updatedRow.add(refresh, BorderLayout.EAST);
		updatedRow.setAlignmentX(Component.LEFT_ALIGNMENT);
		updatedRow.setMaximumSize(new Dimension(Integer.MAX_VALUE, 22));
		statsLabel.setAlignmentX(Component.LEFT_ALIGNMENT);

		panel.add(welcome);
		panel.add(offers);
		panel.add(profit);
		bond.setOpaque(false);
		bond.setVisible(false);
		bond.setBorder(new EmptyBorder(0, 0, 6, 0));
		bond.setAlignmentX(Component.LEFT_ALIGNMENT);
		panel.add(bond);
		panel.add(tabs);
		panel.add(subTabs);
		panel.add(Box.createVerticalStrut(4));
		panel.add(updatedRow);
		panel.add(Box.createVerticalStrut(2));
		panel.add(statsLabel);
		panel.add(Box.createVerticalStrut(6));
		message.setVisible(false);
		panel.add(message);
		panel.add(marketList.getComponent());
		panel.add(mineList.getComponent());
		mineList.getComponent().setVisible(false);
		panel.add(flipsList.getComponent());
		flipsList.getComponent().setVisible(false);
		panel.add(gapsList.getComponent());
		gapsList.getComponent().setVisible(false);
		// The Market tab is selected first: say it's loading rather than show an empty list.
		showLoading();
	}

	/** A Market row: an item's latest trade, as one "Traded" row when both sides of it were reported. */
	private static JComponent marketRow(ItemManager itemManager, MarketRows.Row r, BiConsumer<Integer, String> onOpen)
	{
		MarketData.FeedEvent e = r.getEvent();
		if (!r.isBothSides())
		{
			return row(itemManager, e.getItemId(), e.getName(), e.getKind(), e.getSide(), e.getQty(), e.getPrice(),
				e.getReceivedAt(), onOpen);
		}
		return tradeRow(itemManager, e.getItemId(), e.getName(), Format.traded(e.getQty(), e.getPrice()),
			Format.when(e.getKind(), e.getReceivedAt()), onOpen);
	}

	/** An item row. */
	private static JComponent row(ItemManager itemManager, int itemId, String name, String kind, String side, int qty,
		long price, long ts, BiConsumer<Integer, String> onOpen)
	{
		String line2 = describe(kind, side, qty, price);
		return tradeRow(itemManager, itemId, name, line2, Format.when(kind, ts), onOpen);
	}

	private void selectTab(int newTab, boolean mine, Runnable style, Runnable onTab)
	{
		if (newTab != tab || mine != showMine)
		{
			tab = newTab;
			showMine = mine;
			// A different tab starts at its first page and doesn't flash rows as new.
			(tab == 1 ? flipsList : tab == 2 ? gapsList : mine ? mineList : marketList).reset();
			showOnly(null);
			if (tab != 0)
			{
				setStats("");
				showMessage("Loading\u2026");
			}
			else if (!mine)
			{
				if (hasMarketData)
				{
					// Show the feed we have right away; the load that follows only adds what's new.
					setStats(marketStats);
					message.setVisible(false);
					marketList.getComponent().setVisible(true);
				}
				else
				{
					showLoading();
				}
			}
		}
		style.run();
		onTab.run();
	}

	/** Shows the estimated Hardcore : OSRS rate as a bond row (it opens the bond), or hides it without a rate. */
	void showBond(MarketData.SwapRate s)
	{
		bond.removeAll();
		boolean show = s != null && s.getRate() != null && s.getRate() > 0;
		if (show)
		{
			String avg = Format.ratio(s.getRate());
			String range = avg;
			if (s.getRateLow() != null && s.getRateHigh() != null
				&& !Format.ratio(s.getRateLow()).equals(Format.ratio(s.getRateHigh())))
			{
				range = Format.ratio(s.getRateLow()) + "\u2013" + Format.ratio(s.getRateHigh());
			}
			JComponent row = tradeRow(itemManager, ItemID.OSRS_BOND, "Est. Swap Rate  1 : " + range,
				"Average 1 : " + avg, null, onOpen);
			row.setToolTipText("Based off bond prices (Hardcore : OSRS GP)");
			bond.add(row, BorderLayout.CENTER);
			bond.setMaximumSize(new Dimension(Integer.MAX_VALUE, row.getPreferredSize().height + 6));
		}
		bond.setVisible(show);
		bond.revalidate();
		bond.repaint();
	}

	JComponent getComponent()
	{
		return panel;
	}

	/** True when the "My trades" tab is selected. */
	boolean isShowingMine()
	{
		return tab == 0 && showMine;
	}

	void showMine(List<TradeEvent> trades)
	{
		setStats("Your Hardcore World trades");
		message.setVisible(false);
		showOnly(mineList);
		mineList.setItems(RowList.withOccurrenceKeys(trades, ItemSections::tradeKey));
		tick();
	}

	void showNotConnected()
	{
		tabs.setVisible(false);
		subTabs.setVisible(false);
		bond.setVisible(false);
		setStats("");
		message.setVisible(false);
		showOnly(null);
		tick();
	}

	void showTabs()
	{
		tabs.setVisible(true);
		subTabs.setVisible(tab == 0);
	}

	boolean isShowingLive()
	{
		return tab == 0 && !showMine;
	}

	boolean isShowingFlips()
	{
		return tab == 1;
	}

	boolean isShowingGaps()
	{
		return tab == 2;
	}

	void showFlips(List<MarketData.Flip> flips, long capital)
	{
		setStats(flips.size() + " flips \u00b7 " + compact(capital) + " gold \u00b7 profit over 4h");
		message.setVisible(false);
		showOnly(flipsList);
		flipsList.setItems(flips);
		tick();
	}

	void showGaps(List<MarketData.Gap> gaps)
	{
		setStats(gaps.size() + " gaps \u00b7 gp an hour for the supplier");
		message.setVisible(false);
		showOnly(gapsList);
		gapsList.setItems(gaps);
		tick();
	}

	/** A failed Flips or Gaps load: said only while nothing has loaded. */
	void showTabError(String text)
	{
		if ((tab == 1 ? flipsList : gapsList).getComponent().isVisible())
		{
			return;
		}
		setStats("");
		showMessage(text);
	}

	private void showOnly(RowList<?> list)
	{
		marketList.getComponent().setVisible(list == marketList);
		mineList.getComponent().setVisible(list == mineList);
		flipsList.getComponent().setVisible(list == flipsList);
		gapsList.getComponent().setVisible(list == gapsList);
	}

	/** Show the merged Market feed ({@link FeedMerge}): each item's latest trade ({@link MarketRows}), newest first. */
	void showMarket(MarketData.Stats s, List<MarketData.FeedEvent> events)
	{
		marketStats = s == null ? "" : "<html>" + s.getOpenBids() + " bids · " + s.getOpenAsks() + " asks open<br>"
			+ QuantityFormatter.quantityToStackSize(s.getUnits24()) + " units / " + QuantityFormatter.quantityToStackSize(s.getGp24())
			+ " gp traded in 24h</html>";
		setStats(marketStats);
		message.setVisible(false);
		showOnly(marketList);
		marketList.setItems(MarketRows.latestPerItem(events));
		hasMarketData = true;
		failed = null;
		lastUpdated = System.currentTimeMillis();
		tick();
	}

	/** A market refresh failed: replace the list only if nothing was loaded yet, otherwise just say so. */
	void showError(String text)
	{
		if (!hasMarketData)
		{
			setStats("");
			showMessage(text);
			marketList.getComponent().setVisible(false);
			mineList.getComponent().setVisible(false);
		}
		else
		{
			failed = text;
		}
		tick();
	}

	/** Forget the loaded market (connection changed); the next load starts fresh. */
	void resetMarket()
	{
		// Empty first, then reset: the first real load must not count as new rows.
		marketList.setItems(new ArrayList<>());
		marketList.reset();
		hasMarketData = false;
		marketStats = "";
		lastUpdated = 0;
		failed = null;
		if (tab == 0 && !showMine)
		{
			showLoading();
		}
	}

	/** The Market tab before its first load: no list (not "No trades yet."), just a loading line. */
	private void showLoading()
	{
		setStats("");
		showMessage("Loading…");
		marketList.getComponent().setVisible(false);
		mineList.getComponent().setVisible(false);
		tick();
	}

	/** Once a second while shown: update the "updated Xs ago" text (market tab only). */
	void tick()
	{
		String text;
		Color color = ColorScheme.LIGHT_GRAY_COLOR;
		if (tab != 0 || showMine || !hasMarketData)
		{
			text = "";
		}
		else if (failed != null)
		{
			// The reason in a few words; the full sentence is in the tooltip.
			text = failedText(failed);
			color = ColorScheme.PROGRESS_ERROR_COLOR;
		}
		else
		{
			text = "Updated " + Format.updatedAgo(lastUpdated, System.currentTimeMillis());
		}
		boolean rowShown = tab == 0 && !showMine && hasMarketData;
		if (updatedRow.isVisible() != rowShown)
		{
			updatedRow.setVisible(rowShown);
		}
		if (!text.equals(updatedLabel.getText()))
		{
			updatedLabel.setText(text);
			updatedLabel.setForeground(color);
			updatedLabel.setToolTipText(failed != null ? failed + " Showing the last data received." : null);
		}
	}

	/** The status line after a failed refresh, e.g. "Update failed: server unreachable". */
	static String failedText(String error)
	{
		return "Update failed: " + MarketClient.shortReason(error);
	}

	void stop()
	{
		marketList.stop();
		mineList.stop();
		flipsList.stop();
		gapsList.stop();
	}

	private void setStats(String text)
	{
		if (!text.equals(statsLabel.getText()))
		{
			statsLabel.setText(text);
		}
	}

	private void showMessage(String text)
	{
		if (!text.equals(message.getText()))
		{
			message.setText(text);
		}
		message.setVisible(true);
	}
}

package com.hardcoreworldtoolkit.ui;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.geom.AffineTransform;
import java.awt.geom.Arc2D;
import java.awt.geom.Area;
import java.awt.geom.Ellipse2D;
import java.awt.geom.Path2D;
import java.awt.geom.Rectangle2D;
import java.awt.geom.RoundRectangle2D;
import java.awt.image.BufferedImage;
import javax.swing.ImageIcon;
import net.runelite.client.RuneLite;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.util.ImageUtil;

/**
 * Small icons drawn in code once, so the plugin ships no image files. EDT only (the caches aren't synchronized).
 */
final class Icons
{
	private static final int CHAT_SIZE = 14;
	private static final int COG_SIZE = 14;
	private static final int COG_TEETH = 8;
	private static final int DOT_SIZE = 8;
	private static final int REFRESH_SIZE = 12;
	private static final int SKULL_SIZE = 22;

	private static ImageIcon chat;
	private static ImageIcon cog;
	private static ImageIcon dotOn;
	private static ImageIcon dotOff;
	private static ImageIcon refresh;
	private static ImageIcon skull;
	private static ImageIcon stats;
	private static ImageIcon statsNew;

	private Icons()
	{
	}

	/** RuneLite's own Discord logo, or the chat bubble if it can't be loaded. */
	static ImageIcon discord()
	{
		try
		{
			return new ImageIcon(ImageUtil.resizeImage(ImageUtil.loadImageResource(RuneLite.class, "/net/runelite/client/plugins/info/discord_icon.png"), 16, 16));
		}
		catch (RuntimeException e)
		{
			return chat();
		}
	}

	/** A speech bubble in Discord's blurple, for the Discord button. */
	static ImageIcon chat()
	{
		if (chat == null)
		{
			chat = new ImageIcon(drawChat(CHAT_SIZE, PanelComponents.DISCORD));
		}
		return chat;
	}

	/** The plugin's skull, for the header. */
	static ImageIcon skull()
	{
		if (skull == null)
		{
			skull = new ImageIcon(SkullIcon.draw(SKULL_SIZE, SkullIcon.BONE));
		}
		return skull;
	}

	/** A settings cog. */
	static ImageIcon cog()
	{
		if (cog == null)
		{
			cog = new ImageIcon(drawCog(COG_SIZE, ColorScheme.LIGHT_GRAY_COLOR));
		}
		return cog;
	}

	/** A circular arrow, for refresh buttons. */
	static ImageIcon refresh()
	{
		if (refresh == null)
		{
			refresh = new ImageIcon(drawRefresh(REFRESH_SIZE, ColorScheme.LIGHT_GRAY_COLOR));
		}
		return refresh;
	}

	/** A filled dot (connected) or a ring (not connected) for the status line. */
	static ImageIcon statusDot(boolean on)
	{
		if (on)
		{
			if (dotOn == null)
			{
				dotOn = new ImageIcon(drawDot(DOT_SIZE, PanelComponents.GOOD, true));
			}
			return dotOn;
		}
		if (dotOff == null)
		{
			dotOff = new ImageIcon(drawDot(DOT_SIZE, ColorScheme.LIGHT_GRAY_COLOR, false));
		}
		return dotOff;
	}

	static BufferedImage drawChat(int size, Color color)
	{
		BufferedImage img = new BufferedImage(size, size, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = img.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		double s = size;
		// A rounded bubble with a tail at its bottom left and three dots cut out of it.
		Area bubble = new Area(new RoundRectangle2D.Double(0, s * 0.06, s, s * 0.68, s * 0.42, s * 0.42));
		Path2D.Double tail = new Path2D.Double();
		tail.moveTo(s * 0.20, s * 0.66);
		tail.lineTo(s * 0.14, s * 0.98);
		tail.lineTo(s * 0.50, s * 0.70);
		tail.closePath();
		bubble.add(new Area(tail));
		double dot = Math.max(1.6, s * 0.15);
		for (int i = 0; i < 3; i++)
		{
			double cx = s * (0.28 + 0.22 * i);
			bubble.subtract(new Area(new Ellipse2D.Double(cx - dot / 2, s * 0.40 - dot / 2, dot, dot)));
		}
		g.setColor(color);
		g.fill(bubble);
		g.dispose();
		return img;
	}

	/** The statistics icon with a small red dot, until the button has been clicked since the last site update (STATS_NOTICE). */
	static ImageIcon statsNew()
	{
		if (statsNew == null)
		{
			BufferedImage img = drawStats(COG_SIZE, ColorScheme.LIGHT_GRAY_COLOR);
			Graphics2D g = img.createGraphics();
			g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			g.setColor(new Color(0xE0, 0x3A, 0x3A));
			g.fill(new Ellipse2D.Double(COG_SIZE - 6, 0, 6, 6));
			g.dispose();
			statsNew = new ImageIcon(img);
		}
		return statsNew;
	}

	/** Three bars of rising height, for the statistics button. */
	static ImageIcon stats()
	{
		if (stats == null)
		{
			stats = new ImageIcon(drawStats(COG_SIZE, ColorScheme.LIGHT_GRAY_COLOR));
		}
		return stats;
	}

	static BufferedImage drawStats(int size, Color color)
	{
		BufferedImage img = new BufferedImage(size, size, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = img.createGraphics();
		g.setColor(color);
		int w = Math.max(2, size / 4);
		int gap = Math.max(1, (size - 3 * w) / 2);
		for (int i = 0; i < 3; i++)
		{
			int h = size * (i + 2) / 5;
			g.fillRect(i * (w + gap), size - h, w, h);
		}
		g.dispose();
		return img;
	}

	static BufferedImage drawCog(int size, Color color)
	{
		BufferedImage img = new BufferedImage(size, size, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = img.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		double c = size / 2.0;
		double body = size * 0.34;
		double hole = size * 0.14;
		double toothW = size * 0.18;
		double toothLen = size * 0.48;
		Area cogArea = new Area(new Ellipse2D.Double(c - body, c - body, body * 2, body * 2));
		Rectangle2D tooth = new Rectangle2D.Double(c - toothW / 2, c - toothLen, toothW, toothLen);
		for (int i = 0; i < COG_TEETH; i++)
		{
			AffineTransform rot = AffineTransform.getRotateInstance(Math.PI * 2 * i / COG_TEETH, c, c);
			cogArea.add(new Area(rot.createTransformedShape(tooth)));
		}
		cogArea.subtract(new Area(new Ellipse2D.Double(c - hole, c - hole, hole * 2, hole * 2)));
		g.setColor(color);
		g.fill(cogArea);
		g.dispose();
		return img;
	}

	static BufferedImage drawRefresh(int size, Color color)
	{
		BufferedImage img = new BufferedImage(size, size, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = img.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setColor(color);
		float stroke = Math.max(1.5f, size / 7f);
		g.setStroke(new BasicStroke(stroke, BasicStroke.CAP_BUTT, BasicStroke.JOIN_MITER));
		double r = size / 2.0 - stroke;
		double c = size / 2.0;
		// Three quarters of a circle, open at the top right, with an arrowhead at the open end.
		g.draw(new Arc2D.Double(c - r, c - r, r * 2, r * 2, 70, 280, Arc2D.OPEN));
		double a = Math.toRadians(70);
		double ex = c + r * Math.cos(a), ey = c - r * Math.sin(a);
		double head = size * 0.32;
		Path2D.Double arrow = new Path2D.Double();
		arrow.moveTo(ex + head * 0.9, ey - head * 0.15);
		arrow.lineTo(ex - head * 0.25, ey - head * 0.75);
		arrow.lineTo(ex - head * 0.1, ey + head * 0.6);
		arrow.closePath();
		g.fill(arrow);
		g.dispose();
		return img;
	}

	private static BufferedImage drawDot(int size, Color color, boolean filled)
	{
		BufferedImage img = new BufferedImage(size, size, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = img.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setColor(color);
		if (filled)
		{
			g.fillOval(0, 0, size - 1, size - 1);
		}
		else
		{
			g.drawOval(1, 1, size - 3, size - 3);
		}
		g.dispose();
		return img;
	}
}

package com.hardcoreworldtoolkit.ui;

import com.hardcoreworldtoolkit.ActiveOffer;
import com.hardcoreworldtoolkit.MarketData;
import com.hardcoreworldtoolkit.TradeEvent;
import java.time.Instant;
import java.util.ArrayList;
import java.util.List;
import lombok.Value;
import net.runelite.client.util.QuantityFormatter;

/**
 * Pure helpers for the item view's sections ("Your offer", "Your trades", the stats grid).
 */
final class ItemSections
{
	private ItemSections()
	{
	}

	/**
	 * e.g. "Selling @ 1,250,000 · 40/100": the price first, then compact filled/total, so at the panel's width the
	 * amounts (also in the tooltip) are cut off rather than the price.
	 */
	static String offerText(ActiveOffer o)
	{
		return (o.isBuy() ? "Buying @ " : "Selling @ ") + Format.gp(o.getPrice()) + " · "
			+ QuantityFormatter.quantityToStackSize(o.getFilled()) + "/" + QuantityFormatter.quantityToStackSize(o.getTotalQty());
	}

	/** The right-hand column of an offer line: how much has filled, e.g. "40%". */
	static String offerRight(ActiveOffer o)
	{
		return o.getTotalQty() <= 0 ? "" : (int) (100L * o.getFilled() / o.getTotalQty()) + "%";
	}

	/** The player's open offers for {@code itemId}, in slot order. */
	static List<ActiveOffer> offersFor(List<ActiveOffer> offers, int itemId)
	{
		List<ActiveOffer> out = new ArrayList<>();
		for (ActiveOffer o : offers)
		{
			if (o.getItemId() == itemId)
			{
				out.add(o);
			}
		}
		return out;
	}

	/** The player's trades of {@code itemId}, newest first as given. */
	static List<TradeEvent> tradesFor(List<TradeEvent> trades, int itemId)
	{
		List<TradeEvent> out = new ArrayList<>();
		for (TradeEvent e : trades)
		{
			if (e.getItemId() == itemId)
			{
				out.add(e);
			}
		}
		return out;
	}

	/** Which colour a stat cell's accent gets. */
	enum Accent
	{
		BUY, SELL, NEUTRAL
	}

	/** One cell of the stats grid. */
	@Value
	static class StatCell
	{
		String label;
		String value;
		/** Small note next to the value (e.g. "5m ago"), or null. */
		String sub;
		Accent accent;
		/** Tooltip, or null. */
		String tooltip;
	}

	static final String TYPICAL_LABEL = "Typical (confirmed)";
	static final String ALCH_LABEL = "High alch";

	/**
	 * The stats grid: last bought / sold, 24h averages, best bid / ask, plus "Typical (confirmed)" (the trusted
	 * median) when the server sends one. Older servers never do, so their grid is unchanged.
	 */
	static List<StatCell> statCells(MarketData.Summary s)
	{
		return statCells(s, Instant.now().getEpochSecond());
	}

	/**
	 * {@link #statCells(MarketData.Summary)} at {@code now} (unix seconds). The typical price's note says how old its
	 * newest confirmed trade is (the median can span the last 7 days) and how many players it comes from.
	 */
	static List<StatCell> statCells(MarketData.Summary s, long now)
	{
		return statCells(s, null, now);
	}

	/** {@link #statCells(MarketData.Summary, long)} plus, last, what High Level Alchemy pays (null: not shown). */
	static List<StatCell> statCells(MarketData.Summary s, Integer highAlch, long now)
	{
		List<StatCell> cells = new ArrayList<>();
		cells.add(new StatCell("Last bought", Format.gp(s.getLastBuy()), Format.ago(s.getLastBuyTime(), now), Accent.BUY, null));
		cells.add(new StatCell("Last sold", Format.gp(s.getLastSell()), Format.ago(s.getLastSellTime(), now), Accent.SELL, null));
		cells.add(new StatCell("Avg bought 24h", Format.gp(s.getAvgBuy24()), null, Accent.BUY, null));
		cells.add(new StatCell("Avg sold 24h", Format.gp(s.getAvgSell24()), null, Accent.SELL, null));
		cells.add(new StatCell("Best bid", Format.gp(s.getBestBid()), null, Accent.BUY, null));
		cells.add(new StatCell("Best ask", Format.gp(s.getBestAsk()), null, Accent.SELL, null));
		if (s.getTrustedPrice() != null)
		{
			Integer votes = s.getTrustedVotes();
			String players = votes == null ? null : votes + (votes == 1 ? " player" : " players");
			String age = Format.ago(s.getTrustedPriceTime(), now);
			String sub = age.isEmpty() ? players : players == null ? age : age + " · " + players;
			cells.add(new StatCell(TYPICAL_LABEL, Format.gp(s.getTrustedPrice()), sub, Accent.NEUTRAL,
				"Median of confirmed trades in the last 7 days, one vote per player"
					+ (age.isEmpty() ? "" : ". Newest: " + ("now".equals(age) ? "just now" : age + " ago"))));
		}
		if (highAlch != null && highAlch > 0)
		{
			cells.add(new StatCell(ALCH_LABEL, Format.gp((long) highAlch), null, Accent.NEUTRAL,
				"What High Level Alchemy pays for one. It pays to alch when you buy for less than this minus a nature rune."));
		}
		return cells;
	}

	/** Tooltip for the 24h volume line: "X confirmed / Y unconfirmed", or null when the server didn't say. */
	static String volumeTooltip(MarketData.Summary s)
	{
		if (s.getConfVol24() == null || s.getUnconfVol24() == null)
		{
			return null;
		}
		return QuantityFormatter.formatNumber(s.getConfVol24()) + " confirmed / "
			+ QuantityFormatter.formatNumber(s.getUnconfVol24()) + " unconfirmed";
	}

	/** True only for a fill the server marked unconfirmed (never for older servers, which don't say). */
	static boolean unconfirmed(MarketData.Trade t)
	{
		return Boolean.FALSE.equals(t.getConfirmed());
	}

	/** Row identity for a trade of the player's: its event id, or its contents for old log lines without one. */
	static String tradeKey(TradeEvent e)
	{
		return e.getId() != null ? e.getId()
			: e.getKind() + "|" + e.getSide() + "|" + e.getQty() + "|" + e.getPrice() + "|" + e.getTs();
	}
}

