/**
 * Small Swing building blocks shared by the panel's views.
 * <p>
 * Rows are single-line labels (no wrapping HTML) with a fixed maximum height, so a BoxLayout column never stretches
 * them; {@link #wrapText} is only for messages.
 */
final class PanelComponents
{
	static final Color BUY = new Color(0x3987e5);
	static final Color SELL = new Color(0xd95926);
	/** Positive / connected. */
	static final Color GOOD = new Color(0x3cb371);
	/** An offer was undercut or outbid. */
	static final Color ALERT = new Color(0xe0503a);
	/** An offer hasn't filled for a long time. */
	static final Color STALE = new Color(0xd8a634);
	/** The Hardcore accent: bars and underlines. */
	static final Color HC_RED = new Color(0xc8372d);
	/** A red that reads as text on the dark panel. */
	static final Color HC_TEXT = new Color(0xf0654f);
	/** The dark red behind the header strip. */
	static final Color HC_DARK = new Color(0x2c1715);
	/** Discord's blurple, for the Discord button. */
	static final Color DISCORD = new Color(0x5865f2);
	/** The underline of the tabs that aren't selected. */
	private static final Color TAB_TRACK = new Color(0x3a3a3a);
	/** Client property of a tab button: whether it is the selected one. */
	private static final String TAB_ON = "hardcoreworldtoolkit.tabOn";
	/** Price levels shown per side of the order book. */
	private static final int BOOK_DEPTH = 8;

	private PanelComponents()
	{
	}

	static Color sideColor(String side)
	{
		return TradeEvent.SELL.equals(side) ? SELL : BUY;
	}

	/** A clickable item row: icon, name, an optional second line, and an optional time on the right. */
	static JComponent tradeRow(ItemManager itemManager, int itemId, String name, String line2, String right,
		BiConsumer<Integer, String> onOpen)
	{
		return tradeRow(itemManager, itemId, name, line2, right, false, onOpen);
	}

	/** @param rightBelow {@code right} ends the second line, so the name keeps the first */
	static JComponent tradeRow(ItemManager itemManager, int itemId, String name, String line2, String right,
		boolean rightBelow, BiConsumer<Integer, String> onOpen)
	{
		JPanel row = new JPanel(new BorderLayout(6, 0));
		row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		row.setBorder(new EmptyBorder(3, 4, 3, 6));
		JLabel icon = new JLabel();
		icon.setPreferredSize(new Dimension(32, 30));
		itemManager.getImage(itemId).addTo(icon);
		row.add(icon, BorderLayout.WEST);

		String display = name == null || name.isEmpty() ? "Item " + itemId : name;
		JPanel text = new JPanel(new GridLayout(line2 == null ? 1 : 2, 1));
		text.setOpaque(false);
		text.add(smallLabel(display, Color.WHITE));
		boolean below = rightBelow && line2 != null && right != null;
		if (below)
		{
			JPanel second = new JPanel(new BorderLayout());
			second.setOpaque(false);
			second.add(smallLabel(line2, ColorScheme.TEXT_COLOR), BorderLayout.CENTER);
			second.add(smallLabel(right, ColorScheme.PROGRESS_COMPLETE_COLOR), BorderLayout.EAST);
			text.add(second);
		}
		else if (line2 != null)
		{
			text.add(smallLabel(line2, ColorScheme.TEXT_COLOR));
		}
		row.add(text, BorderLayout.CENTER);
		if (right != null && !below)
		{
			JLabel when = mutedLabel(right);
			when.setVerticalAlignment(SwingConstants.TOP);
			row.add(when, BorderLayout.EAST);
		}
		row.setToolTipText(line2 == null ? display : display + ": " + line2);
		row.setAlignmentX(Component.LEFT_ALIGNMENT);
		// After all children are added, so the preferred height is final.
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, row.getPreferredSize().height));
		row.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		row.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				onOpen.accept(itemId, display);
			}

			@Override
			public void mouseEntered(MouseEvent e)
			{
				row.setBackground(ColorScheme.DARKER_GRAY_HOVER_COLOR);
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
			}
		});
		return row;
	}

	/**
	 * A one-line trade with a colored left edge and a time on the right. No spacing of its own: lists add it
	 * ({@link RowList}).
	 */
	static JComponent lineRow(String text, String right, Color accent)
	{
		return lineRow(text, right, accent, ColorScheme.LIGHT_GRAY_COLOR, text);
	}

	/** {@link #lineRow(String, String, Color)} with a colored right-hand text and its own tooltip. */
	static JComponent lineRow(String text, String right, Color accent, Color rightColor, String tooltip)
	{
		JPanel row = new JPanel(new BorderLayout(6, 0));
		row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		row.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createMatteBorder(0, 2, 0, 0, accent), new EmptyBorder(3, 6, 3, 6)));
		row.add(smallLabel(text, ColorScheme.TEXT_COLOR), BorderLayout.CENTER);
		row.add(smallLabel(right, rightColor), BorderLayout.EAST);
		row.setToolTipText(tooltip);
		row.setAlignmentX(Component.LEFT_ALIGNMENT);
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, 24));
		return row;
	}

	/** A small square icon-only button, e.g. refresh. */
	static JButton iconButton(Icon icon, String tooltip, int size)
	{
		JButton b = new JButton(icon);
		b.setPreferredSize(new Dimension(size, size));
		b.setMaximumSize(new Dimension(size, size));
		b.setFocusPainted(false);
		b.setToolTipText(tooltip);
		return b;
	}

	/** A compact two-line stat cell: label on top, value (and an optional note) below. */
	static JComponent stat(String label, String value, String sub, Color accent)
	{
		JPanel p = new JPanel(new GridLayout(2, 1));
		p.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		p.setBorder(BorderFactory.createCompoundBorder(BorderFactory.createMatteBorder(0, 2, 0, 0, accent), new EmptyBorder(2, 5, 2, 4)));
		p.add(mutedLabel(label));
		JPanel line = new JPanel(new BorderLayout(4, 0));
		line.setOpaque(false);
		JLabel v = new JLabel(value);
		v.setFont(FontManager.getRunescapeBoldFont());
		v.setForeground(Color.WHITE);
		line.add(v, BorderLayout.CENTER);
		if (sub != null && !sub.isEmpty())
		{
			line.add(mutedLabel(sub), BorderLayout.EAST);
		}
		p.add(line);
		return p;
	}

	/** Views live in a CardLayout that fills the panel; anchoring them at the top stops BoxLayout stretching rows. */
	static JPanel pinTop(JComponent view)
	{
		JPanel p = new JPanel(new BorderLayout());
		p.setOpaque(false);
		p.add(view, BorderLayout.NORTH);
		return p;
	}

	static JComponent bookColumn(String title, List<MarketData.Level> levels, Color accent)
	{
		JPanel col = column();
		col.add(smallLabel(title, accent));
		if (levels == null || levels.isEmpty())
		{
			col.add(mutedLabel("none"));
		}
		else
		{
			for (MarketData.Level lv : levels.subList(0, Math.min(BOOK_DEPTH, levels.size())))
			{
				JLabel l = smallLabel(QuantityFormatter.formatNumber(lv.getPrice()) + " × " + QuantityFormatter.quantityToStackSize(lv.getQty()),
					ColorScheme.TEXT_COLOR);
				l.setToolTipText(lv.getOffers() + " offer" + (lv.getOffers() == 1 ? "" : "s"));
				col.add(l);
			}
		}
		return col;
	}

	static JComponent legend()
	{
		JPanel p = new JPanel(new FlowLayout(FlowLayout.LEFT, 8, 0));
		p.setOpaque(false);
		p.add(smallLabel("■ Bought", BUY));
		p.add(smallLabel("■ Sold", SELL));
		p.add(smallLabel("bars = units traded", ColorScheme.LIGHT_GRAY_COLOR));
		p.setAlignmentX(Component.LEFT_ALIGNMENT);
		p.setMaximumSize(new Dimension(Integer.MAX_VALUE, 18));
		return p;
	}

	/** A vertical BoxLayout column, transparent and left aligned. */
	static JPanel column()
	{
		JPanel p = new JPanel();
		p.setLayout(new BoxLayout(p, BoxLayout.Y_AXIS));
		p.setOpaque(false);
		p.setAlignmentX(Component.LEFT_ALIGNMENT);
		return p;
	}

	/** A flat tab: text over an underline that {@link #styleTab} makes red on the selected one. */
	static JButton tabButton(String text)
	{
		JButton b = new JButton(text);
		b.setFocusPainted(false);
		b.setContentAreaFilled(false);
		b.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		b.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseEntered(MouseEvent e)
			{
				b.setForeground(Color.WHITE);
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				styleTab(b, Boolean.TRUE.equals(b.getClientProperty(TAB_ON)));
			}
		});
		styleTab(b, false);
		return b;
	}

	static JButton segButton(String text)
	{
		JButton b = new JButton(text);
		b.setFont(FontManager.getRunescapeSmallFont());
		b.setFocusPainted(false);
		b.setContentAreaFilled(false);
		b.setOpaque(true);
		b.setBorder(new EmptyBorder(6, 22, 6, 22));
		b.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		styleSeg(b, false);
		return b;
	}

	static void styleSeg(JButton b, boolean on)
	{
		b.setBackground(on ? ColorScheme.MEDIUM_GRAY_COLOR : ColorScheme.DARKER_GRAY_COLOR);
		b.setForeground(on ? Color.WHITE : ColorScheme.LIGHT_GRAY_COLOR);
	}

	static void styleTab(JButton b, boolean on)
	{
		b.putClientProperty(TAB_ON, on);
		b.setForeground(on ? Color.WHITE : ColorScheme.LIGHT_GRAY_COLOR);
		b.setBorder(new CompoundBorder(new MatteBorder(0, 0, 2, 0, on ? HC_RED : TAB_TRACK), new EmptyBorder(5, 4, 4, 4)));
	}

	/** The one call to action on a card, e.g. Connect. */
	static JButton primaryButton(String text)
	{
		JButton b = new JButton(text);
		b.setFont(FontManager.getRunescapeBoldFont());
		b.setBackground(HC_RED);
		b.setForeground(Color.WHITE);
		b.setFocusPainted(false);
		return b;
	}

	/** A section title with a red bar on its left. */
	static JLabel sectionLabel(String text)
	{
		JLabel l = new JLabel(text);
		l.setFont(FontManager.getRunescapeBoldFont());
		l.setForeground(Color.WHITE);
		l.setBorder(new CompoundBorder(new EmptyBorder(2, 0, 4, 0),
			new CompoundBorder(new MatteBorder(0, 3, 0, 0, HC_RED), new EmptyBorder(0, 6, 0, 0))));
		l.setAlignmentX(Component.LEFT_ALIGNMENT);
		return l;
	}

	static JLabel smallLabel(String text, Color color)
	{
		JLabel l = new JLabel(text);
		l.setFont(FontManager.getRunescapeSmallFont());
		l.setForeground(color);
		return l;
	}

	static JLabel mutedLabel(String text)
	{
		return smallLabel(text, ColorScheme.LIGHT_GRAY_COLOR);
	}

	/** Word-wrapped text, for messages only (never rows). */
	static JComponent wrapText(String text, Color color)
	{
		JTextArea t = new JTextArea(text);
		t.setLineWrap(true);
		t.setWrapStyleWord(true);
		t.setEditable(false);
		t.setFocusable(false);
		t.setOpaque(false);
		// FlatLaf gives text areas a 2,6,2,6 margin; without it wrapped text lines up with labels.
		t.setMargin(new Insets(0, 0, 0, 0));
		t.setForeground(color);
		t.setFont(FontManager.getRunescapeSmallFont());
		t.setAlignmentX(Component.LEFT_ALIGNMENT);
		return t;
	}

	/** Small clickable text with a hand cursor, e.g. the "Privacy" link. */
	static JLabel linkLabel(String text, Runnable onClick)
	{
		JLabel l = smallLabel(text, ColorScheme.LIGHT_GRAY_COLOR);
		l.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		l.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				onClick.run();
			}

			@Override
			public void mouseEntered(MouseEvent e)
			{
				l.setForeground(HC_TEXT);
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				l.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
			}
		});
		return l;
	}

	/** A one-line offer: side-colored edge, badge colored by what it says. */
	static JComponent offerRow(OfferLine line)
	{
		Color badge = line.getKind() == OfferLine.Badge.ALERT ? ALERT
			: line.getKind() == OfferLine.Badge.STALE ? STALE : ColorScheme.LIGHT_GRAY_COLOR;
		return lineRow(line.getText(), line.getBadge(), line.getOffer().isBuy() ? BUY : SELL, badge, line.getTooltip());
	}
}

package com.hardcoreworldtoolkit.ui;

import static com.hardcoreworldtoolkit.ui.PanelComponents.BUY;
import static com.hardcoreworldtoolkit.ui.PanelComponents.SELL;
import com.hardcoreworldtoolkit.MarketData;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.geom.Path2D;
import java.time.Instant;
import java.time.ZoneId;
import java.time.format.DateTimeFormatter;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Locale;
import javax.swing.JComponent;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.util.QuantityFormatter;

/**
 * Average bought/sold price over the chosen range, with a separate volume strip underneath (its own scale, not a
 * second axis on the price plot). Hover shows a crosshair and the values at the nearest bucket.
 * <p>
 * The axis always spans the whole range ending now. Everything that depends on the data or the size (scale, labels,
 * paths, bars) is computed once per change in {@link #layout}; painting only draws the cached result. EDT only.
 */
class PriceChart extends JComponent
{
	private static final Color GRID = new Color(0x3a3a3a);
	private static final Color VOLUME = new Color(0x256abf);
	private static final BasicStroke LINE = new BasicStroke(2f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND);
	private static final BasicStroke THIN = new BasicStroke(1f);
	private static final BasicStroke DASHED = new BasicStroke(1f, BasicStroke.CAP_BUTT, BasicStroke.JOIN_MITER, 1f,
		new float[]{3f, 3f}, 0f);
	private static final DateTimeFormatter TIP_TIME = DateTimeFormatter.ofPattern("EEE d MMM HH:mm", Locale.ENGLISH);
	private static final int PRICE_H = 150;
	private static final int VOL_H = 36;
	private static final int GAP = 8;
	private static final int RIGHT = 6;
	private static final int TOP = 6;
	private static final int BOTTOM = 14;
	private static final int HEIGHT = TOP + PRICE_H + GAP + VOL_H + BOTTOM;
	/** Narrower than this and the chart shows a message instead. */
	static final int MIN_WIDTH = 120;
	private static final int Y_TICKS = 4;
	private static final float DOT = 5f;

	static final String UNAVAILABLE = "Chart unavailable";
	static final String LOADING = "Loading…";
	static final String TOO_NARROW = "Too narrow";

	private final Font font = FontManager.getRunescapeSmallFont();

	// Inputs.
	private List<MarketData.Point> points = Collections.emptyList();
	private ChartRange range = ChartRange.DEFAULT;
	private long now;
	/** Message instead of data (loading, unavailable), or null when showing data. */
	private String status = LOADING;

	// Layout, recomputed when dirty or resized.
	private boolean dirty = true;
	private int layoutW = -1;
	private int layoutH = -1;
	private String message;
	private int left;
	private String[] yLabels = new String[0];
	private int[] yLabelY = new int[0];
	private final Path2D.Float buyPath = new Path2D.Float();
	private final Path2D.Float sellPath = new Path2D.Float();
	/** Lone points (no neighbour close enough to join): x, y pairs. */
	private float[] buyDots = new float[0];
	private float[] sellDots = new float[0];
	private int[] barX = new int[0];
	private int[] barH = new int[0];
	private int barW = 1;
	private String volLabel = "";
	private int[] tickX = new int[0];
	private String[] tickLabels = new String[0];
	/** Per point: x, and the y of each price (NaN when there was none). For hover. */
	private double[] xs = new double[0];
	private float[] buyY = new float[0];
	private float[] sellY = new float[0];

	// Hover.
	private int hover = -1;
	/** Where the mouse is over the chart, or -1; a relayout (refresh) re-snaps the hover to it. */
	private int mouseX = -1;
	private String tipTime = "";
	private String tipBuy = "";
	private String tipSell = "";
	private int tipW;

	PriceChart()
	{
		setPreferredSize(new Dimension(0, HEIGHT));
		setMinimumSize(new Dimension(0, HEIGHT));
		setMaximumSize(new Dimension(Integer.MAX_VALUE, HEIGHT));
		setOpaque(false);
		MouseAdapter mouse = new MouseAdapter()
		{
			@Override
			public void mouseMoved(MouseEvent e)
			{
				mouseX = e.getX();
				setHover(nearest(mouseX));
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				mouseX = -1;
				setHover(-1);
			}
		};
		addMouseListener(mouse);
		addMouseMotionListener(mouse);
	}

	/**
	 * Show {@code data} over {@code range} ending at {@code now} (unix s). Does nothing when the trimmed data, the range
	 * and the minute of {@code now} are all unchanged, so a periodic refresh with the same data doesn't repaint.
	 */
	void setData(List<MarketData.Point> data, ChartRange range, long now)
	{
		List<MarketData.Point> trimmed = range.trim(data, now);
		if (status == null && range == this.range && now / 60 == this.now / 60 && trimmed.equals(points))
		{
			return;
		}
		this.points = trimmed;
		this.range = range;
		this.now = now;
		this.status = null;
		invalidateLayout();
	}

	/** Show a loading message for {@code range} (a new item or range), dropping the old data. */
	void setLoading(ChartRange range)
	{
		setStatus(range, LOADING);
	}

	/** The series couldn't be loaded and there's nothing to show for this range. */
	void setUnavailable(ChartRange range)
	{
		setStatus(range, UNAVAILABLE);
	}

	private void setStatus(ChartRange range, String status)
	{
		if (status.equals(this.status) && range == this.range)
		{
			return;
		}
		this.range = range;
		this.status = status;
		this.points = Collections.emptyList();
		invalidateLayout();
	}

	/** True when real data (possibly empty) is shown, rather than a loading or error message. */
	boolean hasData()
	{
		return status == null;
	}

	/** The message shown instead of the chart as of the last paint, or null if it drew data. For tests. */
	String shownMessage()
	{
		return message;
	}

	/** The left gutter (y label) width as of the last layout. For tests. */
	int gutter()
	{
		return left;
	}

	/** True when the next paint recomputes the layout. For tests. */
	boolean layoutPending()
	{
		return dirty;
	}

	private void invalidateLayout()
	{
		dirty = true;
		hover = -1;
		repaint();
	}

	/** The index of the bucket nearest to {@code mx}, or -1. Binary search over the laid-out x positions. */
	private int nearest(int mx)
	{
		double[] x = xs;
		if (dirty || message != null || x.length == 0)
		{
			return -1;
		}
		return nearestIndex(x, mx);
	}

	/** Index of the value in ascending {@code xs} closest to {@code target}; -1 if empty. Pure. */
	static int nearestIndex(double[] xs, double target)
	{
		if (xs.length == 0)
		{
			return -1;
		}
		int lo = 0, hi = xs.length - 1;
		while (lo < hi)
		{
			int mid = (lo + hi) >>> 1;
			if (xs[mid] < target)
			{
				lo = mid + 1;
			}
			else
			{
				hi = mid;
			}
		}
		if (lo > 0 && Math.abs(xs[lo - 1] - target) <= Math.abs(xs[lo] - target))
		{
			return lo - 1;
		}
		return lo;
	}

	/** Change the hovered bucket; the tooltip text is built here, only when it changes, not while painting. */
	private void setHover(int idx)
	{
		if (idx == hover)
		{
			return;
		}
		buildTip(idx, getFontMetrics(font));
		repaint();
	}

	/** Set the hovered bucket and build its tooltip text (no repaint). */
	private void buildTip(int idx, FontMetrics fm)
	{
		hover = idx;
		if (idx >= 0 && idx < points.size())
		{
			MarketData.Point p = points.get(idx);
			tipTime = TIP_TIME.format(Instant.ofEpochSecond(p.getTimestamp()).atZone(ZoneId.systemDefault()));
			tipBuy = "Bought " + Format.gp(p.getAvgBuy()) + " (" + QuantityFormatter.formatNumber(p.getBuyVolume()) + ")";
			tipSell = "Sold " + Format.gp(p.getAvgSell()) + " (" + QuantityFormatter.formatNumber(p.getSellVolume()) + ")";
			tipW = Math.max(fm.stringWidth(tipTime), Math.max(fm.stringWidth(tipBuy), fm.stringWidth(tipSell)) + 12) + 12;
		}
	}

	/* ------------------------------------------------------------ layout */

	private void layout(int w, int h, FontMetrics fm)
	{
		dirty = false;
		layoutW = w;
		layoutH = h;
		message = null;
		xs = new double[0];
		if (w < MIN_WIDTH)
		{
			message = TOO_NARROW;
			return;
		}
		if (status != null)
		{
			message = status;
			return;
		}
		long lo = Long.MAX_VALUE, hi = Long.MIN_VALUE, vmax = 0;
		for (MarketData.Point p : points)
		{
			if (p.getAvgBuy() != null)
			{
				lo = Math.min(lo, p.getAvgBuy());
				hi = Math.max(hi, p.getAvgBuy());
			}
			if (p.getAvgSell() != null)
			{
				lo = Math.min(lo, p.getAvgSell());
				hi = Math.max(hi, p.getAvgSell());
			}
			vmax = Math.max(vmax, p.getBuyVolume() + p.getSellVolume());
		}
		if (lo == Long.MAX_VALUE)
		{
			message = "No trades in the last " + range.longLabel();
			return;
		}

		// Y axis: nice ticks, and a gutter as wide as the widest label.
		NiceScale scale = NiceScale.of(lo, hi, Y_TICKS);
		int n = scale.tickCount();
		yLabels = new String[n];
		yLabelY = new int[n];
		int labelW = 0;
		for (int i = 0; i < n; i++)
		{
			yLabels[i] = Format.compactGp(scale.tick(i), scale.step);
			labelW = Math.max(labelW, fm.stringWidth(yLabels[i]));
		}
		// Compact on its own ("1M", "2B"): it shares the gutter, so a big volume mustn't squeeze the plot.
		volLabel = vmax > 0 ? Format.compactAmount(vmax) : "";
		labelW = Math.max(labelW, fm.stringWidth(volLabel));
		left = labelW + 6;
		int iw = Math.max(1, w - left - RIGHT);
		for (int i = 0; i < n; i++)
		{
			yLabelY[i] = Math.round(y(scale.tick(i), scale));
		}

		// X positions: the middle of each bucket, on an axis spanning the whole range.
		long t1 = now, t0 = now - range.seconds();
		int count = points.size();
		xs = new double[count];
		buyY = new float[count];
		sellY = new float[count];
		for (int i = 0; i < count; i++)
		{
			MarketData.Point p = points.get(i);
			xs[i] = x(p.getTimestamp() + range.stepSeconds() / 2, t0, t1, iw);
			buyY[i] = p.getAvgBuy() == null ? Float.NaN : y(p.getAvgBuy(), scale);
			sellY[i] = p.getAvgSell() == null ? Float.NaN : y(p.getAvgSell(), scale);
		}
		long maxGap = range.maxGapBuckets() * range.stepSeconds();
		buyDots = buildPath(buyPath, buyY, maxGap);
		sellDots = buildPath(sellPath, sellY, maxGap);

		// Volume bars: as wide as a bucket (at most 10px), at least 1px.
		double slot = iw / (double) Math.max(1, range.seconds() / range.stepSeconds());
		barW = (int) Math.max(1, Math.min(10, slot > 4 ? slot - 1 : slot));
		barX = new int[count];
		barH = new int[count];
		for (int i = 0; i < count; i++)
		{
			MarketData.Point p = points.get(i);
			long vol = p.getBuyVolume() + p.getSellVolume();
			barX[i] = (int) Math.round(xs[i] - barW / 2.0);
			barH[i] = vol <= 0 || vmax <= 0 ? 0 : (int) Math.max(1, Math.round((double) vol / vmax * VOL_H));
		}

		// Time labels at round local times, as many as fit.
		int maxLabels = iw / (fm.stringWidth(TimeTicks.sampleLabel(range)) + 8);
		TimeTicks ticks = TimeTicks.of(t0, t1, range, ZoneId.systemDefault(), maxLabels);
		tickLabels = ticks.labels;
		tickX = new int[ticks.ts.length];
		for (int i = 0; i < tickX.length; i++)
		{
			int cx = (int) Math.round(x(ticks.ts[i], t0, t1, iw));
			int lw = fm.stringWidth(tickLabels[i]);
			tickX[i] = Math.max(0, Math.min(w - 1 - lw, cx - lw / 2));
		}

		// A refresh re-lays out under a resting mouse: keep its tooltip, snapped to the new buckets.
		if (mouseX >= 0 && count > 0)
		{
			buildTip(nearestIndex(xs, mouseX), fm);
		}
	}

	/** Fill {@code path} with one line per run of points that are close enough in time; returns the lone points. */
	private float[] buildPath(Path2D.Float path, float[] ys, long maxGap)
	{
		path.reset();
		List<Integer> idx = new ArrayList<>();
		for (int i = 0; i < ys.length; i++)
		{
			if (!Float.isNaN(ys[i]))
			{
				idx.add(i);
			}
		}
		float[] dots = new float[idx.size() * 2];
		int d = 0;
		for (int j = 0; j < idx.size(); j++)
		{
			int i = idx.get(j);
			boolean joinPrev = j > 0 && close(idx.get(j - 1), i, maxGap);
			boolean joinNext = j + 1 < idx.size() && close(i, idx.get(j + 1), maxGap);
			if (joinPrev)
			{
				path.lineTo(xs[i], ys[i]);
			}
			else
			{
				path.moveTo(xs[i], ys[i]);
			}
			if (!joinPrev && !joinNext)
			{
				dots[d++] = (float) xs[i];
				dots[d++] = ys[i];
			}
		}
		float[] out = new float[d];
		System.arraycopy(dots, 0, out, 0, d);
		return out;
	}

	private boolean close(int a, int b, long maxGap)
	{
		return points.get(b).getTimestamp() - points.get(a).getTimestamp() <= maxGap;
	}

	private double x(long ts, long t0, long t1, int iw)
	{
		double f = (double) (ts - t0) / Math.max(1, t1 - t0);
		return left + Math.max(0, Math.min(1, f)) * iw;
	}

	private static float y(long v, NiceScale s)
	{
		return (float) (TOP + PRICE_H - (double) (v - s.min) / Math.max(1, s.max - s.min) * PRICE_H);
	}

	/* ------------------------------------------------------------- paint */

	@Override
	protected void paintComponent(Graphics g0)
	{
		Graphics2D g = (Graphics2D) g0.create();
		try
		{
			g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
			g.setRenderingHint(RenderingHints.KEY_STROKE_CONTROL, RenderingHints.VALUE_STROKE_PURE);
			g.setFont(font);
			FontMetrics fm = g.getFontMetrics();
			int w = getWidth(), h = getHeight();
			if (dirty || w != layoutW || h != layoutH)
			{
				layout(w, h, fm);
			}
			if (message != null)
			{
				g.setColor(ColorScheme.LIGHT_GRAY_COLOR);
				g.drawString(message, Math.max(0, (w - fm.stringWidth(message)) / 2), TOP + PRICE_H / 2);
				return;
			}
			paintChart(g, fm, w, h);
		}
		finally
		{
			g.dispose();
		}
	}

	private void paintChart(Graphics2D g, FontMetrics fm, int w, int h)
	{
		// Price grid and labels.
		g.setStroke(THIN);
		for (int i = 0; i < yLabels.length; i++)
		{
			g.setColor(GRID);
			g.drawLine(left, yLabelY[i], w - RIGHT, yLabelY[i]);
			g.setColor(ColorScheme.LIGHT_GRAY_COLOR);
			g.drawString(yLabels[i], left - 4 - fm.stringWidth(yLabels[i]), yLabelY[i] + fm.getAscent() / 2 - 1);
		}

		// Volume strip.
		int vBase = TOP + PRICE_H + GAP + VOL_H;
		g.setColor(GRID);
		g.drawLine(left, vBase, w - RIGHT, vBase);
		g.setColor(VOLUME);
		for (int i = 0; i < barX.length; i++)
		{
			if (barH[i] > 0)
			{
				g.fillRect(barX[i], vBase - barH[i], barW, barH[i]);
			}
		}
		g.setColor(ColorScheme.LIGHT_GRAY_COLOR);
		g.drawString(volLabel, left - 4 - fm.stringWidth(volLabel), vBase - VOL_H + fm.getAscent());

		// Price lines (broken across gaps) and lone points.
		g.setStroke(LINE);
		g.setColor(BUY);
		g.draw(buyPath);
		drawDots(g, buyDots);
		g.setColor(SELL);
		g.draw(sellPath);
		drawDots(g, sellDots);

		// Time labels.
		g.setColor(ColorScheme.LIGHT_GRAY_COLOR);
		for (int i = 0; i < tickX.length; i++)
		{
			g.drawString(tickLabels[i], tickX[i], h - 3);
		}

		if (hover >= 0 && hover < xs.length)
		{
			paintHover(g, fm, w, h);
		}
	}

	private static void drawDots(Graphics2D g, float[] dots)
	{
		for (int i = 0; i + 1 < dots.length; i += 2)
		{
			g.fillOval(Math.round(dots[i] - DOT / 2), Math.round(dots[i + 1] - DOT / 2), (int) DOT, (int) DOT);
		}
	}

	private void paintHover(Graphics2D g, FontMetrics fm, int w, int h)
	{
		int px = (int) Math.round(xs[hover]);
		g.setColor(ColorScheme.LIGHT_GRAY_COLOR);
		g.setStroke(DASHED);
		g.drawLine(px, TOP, px, TOP + PRICE_H + GAP + VOL_H);
		marker(g, px, buyY[hover], BUY);
		marker(g, px, sellY[hover], SELL);

		// Tooltip box, beside the crosshair and always inside the component.
		int th = fm.getHeight() * 3 + 8;
		int tw = Math.min(tipW, w - 1);
		int tx = px + 10;
		if (tx + tw > w - 1)
		{
			tx = px - 10 - tw;
		}
		tx = Math.max(0, Math.min(w - 1 - tw, tx));
		int ty = Math.max(0, Math.min(h - 1 - th, TOP + 2));
		g.setColor(ColorScheme.DARKER_GRAY_COLOR);
		g.fillRoundRect(tx, ty, tw, th, 6, 6);
		g.setColor(ColorScheme.MEDIUM_GRAY_COLOR);
		g.setStroke(THIN);
		g.drawRoundRect(tx, ty, tw, th, 6, 6);
		int line = ty + 4 + fm.getAscent();
		g.setColor(ColorScheme.LIGHT_GRAY_COLOR);
		g.drawString(tipTime, tx + 6, line);
		line += fm.getHeight();
		g.setColor(BUY);
		g.fillOval(tx + 6, line - fm.getAscent() / 2 - 3, 6, 6);
		g.setColor(ColorScheme.TEXT_COLOR);
		g.drawString(tipBuy, tx + 18, line);
		line += fm.getHeight();
		g.setColor(SELL);
		g.fillOval(tx + 6, line - fm.getAscent() / 2 - 3, 6, 6);
		g.setColor(ColorScheme.TEXT_COLOR);
		g.drawString(tipSell, tx + 18, line);
	}

	private static void marker(Graphics2D g, int px, float py, Color c)
	{
		if (Float.isNaN(py))
		{
			return;
		}
		int y = Math.round(py);
		g.setColor(ColorScheme.DARKER_GRAY_COLOR);
		g.fillOval(px - 5, y - 5, 10, 10);
		g.setColor(c);
		g.fillOval(px - 4, y - 4, 8, 8);
	}
}

package com.hardcoreworldtoolkit.ui;

import static com.hardcoreworldtoolkit.ui.PanelComponents.column;
import static com.hardcoreworldtoolkit.ui.PanelComponents.lineRow;
import static com.hardcoreworldtoolkit.ui.PanelComponents.sectionLabel;
import static com.hardcoreworldtoolkit.ui.PanelComponents.stat;
import static com.hardcoreworldtoolkit.ui.PanelComponents.wrapText;
import com.hardcoreworldtoolkit.ProfitSnapshot;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.GridLayout;
import java.awt.Insets;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.function.BiConsumer;
import javax.swing.Box;
import javax.swing.JButton;
import javax.swing.JComponent;
import javax.swing.JPanel;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

/**
 * "Profit" on the home card: realized profit today, over 7 days and all time, the best items, and footnotes for GE
 * History rows and sells with no known cost, plus a Rebuild button that recounts from the local trade log. Hidden
 * until an account's numbers arrive and there is something to show (or a log to rebuild from). EDT only.
 */
class ProfitSection
{
	/** Item rows shown under the totals. */
	static final int ROWS = 3;

	private final JPanel panel = column();
	private final JButton rebuild = new JButton("Rebuild");
	private final JPanel body = column();
	private final BiConsumer<Integer, String> onOpen;

	/** The account's numbers; null until an account has loaded. */
	private ProfitSnapshot snapshot;
	private boolean logEnabled = true;
	/** The "Show profit" setting; the panel sets it right after building this. */
	private boolean profitOn;
	/** Rebuild was clicked and no snapshot has arrived since. */
	private boolean requested;
	/** What the body shows now, to skip identical re-renders. */
	private List<Object> shown;

	/**
	 * @param onRebuild recount from the trade log (submits the work; must not block)
	 * @param onOpen    opens an item from a row
	 */
	ProfitSection(Runnable onRebuild, BiConsumer<Integer, String> onOpen)
	{
		this.onOpen = onOpen;
		JPanel header = new JPanel(new BorderLayout(4, 0));
		header.setOpaque(false);
		header.add(sectionLabel("Profit"), BorderLayout.WEST);
		rebuild.setFont(FontManager.getRunescapeSmallFont());
		rebuild.setMargin(new Insets(0, 4, 0, 4));
		rebuild.setFocusPainted(false);
		rebuild.addActionListener(e ->
		{
			requested = true;
			styleButton();
			onRebuild.run();
		});
		JPanel east = new JPanel(new BorderLayout());
		east.setOpaque(false);
		east.add(rebuild, BorderLayout.NORTH);
		header.add(east, BorderLayout.EAST);
		header.setAlignmentX(Component.LEFT_ALIGNMENT);
		header.setMaximumSize(new Dimension(Integer.MAX_VALUE, 24));

		panel.add(header);
		panel.add(body);
		panel.add(Box.createVerticalStrut(8));
		panel.setVisible(false);
		styleButton();
	}

	JComponent getComponent()
	{
		return panel;
	}

	/** New numbers from the plugin (after a trade, an account switch or a rebuild). */
	void setSnapshot(ProfitSnapshot s)
	{
		snapshot = s;
		requested = false;
		render();
	}

	/** The "Show profit" setting: off keeps the whole section hidden. */
	void setShown(boolean on)
	{
		if (on != profitOn)
		{
			profitOn = on;
			render();
		}
	}

	/** Whether the local trade log is on; Rebuild needs it. */
	void setLogEnabled(boolean enabled)
	{
		if (enabled != logEnabled)
		{
			logEnabled = enabled;
			render();
		}
	}

	/** Once a second while shown: "Today" moves on at midnight. */
	void tick()
	{
		if (snapshot != null && panel.isVisible())
		{
			render();
		}
	}

	/** Shown once there are numbers, or a log a rebuild could count. */
	static boolean visible(ProfitSnapshot s)
	{
		return s != null && (s.hasData() || s.isLogAvailable());
	}

	private void render()
	{
		styleButton();
		boolean show = profitOn && visible(snapshot);
		if (show != panel.isVisible())
		{
			panel.setVisible(show);
		}
		if (!show)
		{
			return;
		}
		ProfitSnapshot s = snapshot;
		LocalDate today = LocalDate.now();
		List<ProfitSnapshot.ItemProfit> top = s.getTop().subList(0, Math.min(ROWS, s.getTop().size()));
		List<Object> key = Arrays.asList(s.hasData(), s.today(today), s.last7(today), s.getAllTime(),
			s.getHistoryAllTime(), s.getUnknownProceeds(), new ArrayList<>(top));
		if (key.equals(shown))
		{
			return;
		}
		shown = key;
		body.removeAll();
		if (!s.hasData())
		{
			body.add(wrapText(ProfitText.EMPTY, ColorScheme.LIGHT_GRAY_COLOR));
		}
		else
		{
			JPanel cells = new JPanel(new GridLayout(1, 3, 4, 0));
			cells.setOpaque(false);
			cells.add(cell("Today", s.today(today)));
			cells.add(cell("7 days", s.last7(today)));
			cells.add(cell("All time", s.getAllTime()));
			cells.setAlignmentX(Component.LEFT_ALIGNMENT);
			cells.setMaximumSize(new Dimension(Integer.MAX_VALUE, cells.getPreferredSize().height));
			body.add(cells);
			for (ProfitSnapshot.ItemProfit p : top)
			{
				body.add(Box.createVerticalStrut(2));
				body.add(itemRow(p));
			}
			addNote(ProfitText.historyNote(s));
			addNote(ProfitText.unknownNote(s));
		}
		panel.revalidate();
		panel.repaint();
	}

	private static JComponent cell(String label, long v)
	{
		return stat(label, Format.signedGp(v), null, ProfitText.color(v));
	}

	private JComponent itemRow(ProfitSnapshot.ItemProfit p)
	{
		Color c = ProfitText.color(p.getRealized());
		JComponent row = lineRow(ProfitText.name(p), Format.signedGp(p.getRealized()), c, c, ProfitText.itemTooltip(p));
		row.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		row.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				onOpen.accept(p.getItemId(), ProfitText.name(p));
			}
		});
		return row;
	}

	private void addNote(String text)
	{
		if (text != null)
		{
			body.add(Box.createVerticalStrut(4));
			body.add(wrapText(text, ColorScheme.LIGHT_GRAY_COLOR));
		}
	}

	private void styleButton()
	{
		boolean running = requested || (snapshot != null && snapshot.isRebuilding());
		String text = running ? "Rebuilding…" : "Rebuild";
		boolean enabled = logEnabled && !running && snapshot != null;
		String tip = !logEnabled ? ProfitText.REBUILD_NEEDS_LOG : running ? "Recounting from your local trade log" : ProfitText.REBUILD_TIP;
		if (!text.equals(rebuild.getText()))
		{
			rebuild.setText(text);
		}
		if (enabled != rebuild.isEnabled())
		{
			rebuild.setEnabled(enabled);
		}
		if (!tip.equals(rebuild.getToolTipText()))
		{
			rebuild.setToolTipText(tip);
		}
	}
}

package com.hardcoreworldtoolkit.ui;

import com.hardcoreworldtoolkit.ProfitSnapshot;
import java.awt.Color;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.util.QuantityFormatter;

/**
 * Text for the profit numbers on the home card and in the item view. Pure.
 */
final class ProfitText
{
	static final String REBUILD_TIP = "<html>Recount your profit from the local trade log.<br>"
		+ "Lines written before the account was known have no account id,<br>so they count for the account you're logged in with.</html>";
	static final String REBUILD_NEEDS_LOG = "Needs Save local trade log (Configuration > Hardcore World Tool Kit > Local)";
	static final String EMPTY = "No profit counted yet. Rebuild to count the trades already in your local trade log.";

	private ProfitText()
	{
	}

	/** Green for a gain, red for a loss, muted for nothing. */
	static Color color(long v)
	{
		return v > 0 ? PanelComponents.GOOD : v < 0 ? PanelComponents.ALERT : ColorScheme.LIGHT_GRAY_COLOR;
	}

	/** Footnote for profit from GE History rows, or null when there is none. */
	static String historyNote(ProfitSnapshot s)
	{
		return s.getHistoryAllTime() == 0 ? null
			: "Incl. " + Format.signedGp(s.getHistoryAllTime()) + " from GE History (counted at import)";
	}

	/** Footnote for sells with no known cost, or null when there are none. */
	static String unknownNote(ProfitSnapshot s)
	{
		return s.getUnknownProceeds() == 0 ? null
			: "Sold without known cost: " + Format.shortGp(s.getUnknownProceeds()) + " (not counted)";
	}

	/** The name shown for an item. */
	static String name(ProfitSnapshot.ItemProfit p)
	{
		return p.getName() == null || p.getName().isEmpty() ? "Item " + p.getItemId() : p.getName();
	}

	/** True when the item view has anything to say about this item. */
	static boolean hasPosition(ProfitSnapshot.ItemProfit p)
	{
		return p != null && (p.getHeld() > 0 || p.getRealized() != 0 || p.getUnknownProceeds() != 0);
	}

	/** e.g. "Held 1,200 · avg 1.21M · realized +3.4M", or "Realized +3.4M" when none are held. */
	static String itemLine(ProfitSnapshot.ItemProfit p)
	{
		String realized = Format.signedGp(p.getRealized());
		if (p.getHeld() <= 0)
		{
			return "Realized " + realized;
		}
		return "Held " + QuantityFormatter.formatNumber(p.getHeld()) + " · avg " + Format.shortGp(p.getAvgCost())
			+ " · realized " + realized;
	}

	/** e.g. "3 sold for 3.2M with no known cost (not counted)", or null when there were none. */
	static String itemUnknownLine(ProfitSnapshot.ItemProfit p)
	{
		if (p.getUnknownProceeds() == 0)
		{
			return null;
		}
		return QuantityFormatter.formatNumber(p.getUnknownQty()) + " sold for " + Format.shortGp(p.getUnknownProceeds())
			+ " with no known cost (not counted)";
	}

	/** Tooltip for an item row on the home card. */
	static String itemTooltip(ProfitSnapshot.ItemProfit p)
	{
		String tip = name(p) + ": " + itemLine(p);
		if (p.getHistoryRealized() != 0)
		{
			tip += " (" + Format.signedGp(p.getHistoryRealized()) + " from GE History)";
		}
		String unknown = itemUnknownLine(p);
		return unknown == null ? tip : tip + "; " + unknown;
	}
}

package com.hardcoreworldtoolkit.ui;

import static com.hardcoreworldtoolkit.ui.PanelComponents.column;
import static com.hardcoreworldtoolkit.ui.PanelComponents.wrapText;
import java.awt.Color;
import java.awt.Component;
import java.awt.Dimension;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Set;
import java.util.function.Function;
import javax.swing.Box;
import javax.swing.JButton;
import javax.swing.JComponent;
import javax.swing.JPanel;
import javax.swing.Timer;
import javax.swing.text.JTextComponent;
import net.runelite.client.ui.ColorScheme;

/**
 * A column of rows that renders a page at a time ({@link #PAGE} rows, then "Show more") and only builds rows it
 * hasn't built before: rows are cached by key and reused, and when the visible rows are unchanged nothing is touched.
 * Rows that appear after the first render are briefly highlighted. EDT only.
 *
 * @param <T> the row data
 */
class RowList<T>
{
	static final int PAGE = 50;
	static final Color HIGHLIGHT = new Color(0x2f4a2f);
	private static final int HIGHLIGHT_MS = 2_500;
	private static final int GAP = 2;

	/** A cached row: the component the factory built, the wrapper holding it and the spacing, and its content key. */
	private static final class Row
	{
		final JComponent row;
		final JComponent wrapper;
		final Object version;

		Row(JComponent row, JComponent wrapper, Object version)
		{
			this.row = row;
			this.wrapper = wrapper;
			this.version = version;
		}
	}

	private final JPanel panel = column();
	private final Function<T, Object> key;
	private final Function<T, Object> version;
	private final Function<T, JComponent> factory;
	private final JButton more = new JButton();
	private final JComponent empty = wrapText("", ColorScheme.LIGHT_GRAY_COLOR);
	private final Timer unhighlight;
	private final List<JComponent> highlighted = new ArrayList<>();

	private Map<Object, Row> cache = new HashMap<>();
	/** Keys of the rows on screen, in order; null before the first render (and after {@link #reset}). */
	private List<Object> shownKeys;
	private boolean shownEmpty;
	private boolean shownMore;
	private List<T> items = Collections.emptyList();
	private int limit = PAGE;

	/**
	 * @param key     identifies a row; a row whose key was already shown is reused, a new key is highlighted
	 * @param version the row's content; when it changes for a known key the row is rebuilt (not highlighted), e.g. a
	 *                time label that went from "5m" to "6m"
	 * @param factory builds a row
	 */
	RowList(Function<T, Object> key, Function<T, Object> version, Function<T, JComponent> factory)
	{
		this.key = key;
		this.version = version;
		this.factory = factory;
		more.setFocusPainted(false);
		more.setAlignmentX(Component.LEFT_ALIGNMENT);
		more.setMaximumSize(new Dimension(Integer.MAX_VALUE, 24));
		more.addActionListener(e -> showMore());
		unhighlight = new Timer(HIGHLIGHT_MS, e -> clearHighlight());
		unhighlight.setRepeats(false);
	}

	RowList(Function<T, Object> key, Function<T, JComponent> factory)
	{
		this(key, t -> null, factory);
	}

	JComponent getComponent()
	{
		return panel;
	}

	/** Text shown when there are no rows. */
	void setEmptyText(String text)
	{
		((JTextComponent) empty).setText(text);
	}

	/** Back to the first page, and the next render counts as a first render (no highlight). Tab or item changes. */
	void reset()
	{
		limit = PAGE;
		shownKeys = null;
	}

	int limit()
	{
		return limit;
	}

	/** Show {@code items} (first {@link #limit} of them). Does nothing if the visible rows are unchanged. */
	void setItems(List<T> items)
	{
		this.items = new ArrayList<>(items);
		render(true);
	}

	void showMore()
	{
		limit += PAGE;
		render(false);
	}

	/** Stop the highlight timer; for the panel's shutdown. */
	void stop()
	{
		unhighlight.stop();
	}

	private void render(boolean highlightNew)
	{
		int n = Math.min(limit, items.size());
		List<Object> keys = new ArrayList<>(n);
		List<Object> versions = new ArrayList<>(n);
		for (int i = 0; i < n; i++)
		{
			keys.add(key.apply(items.get(i)));
			versions.add(version.apply(items.get(i)));
		}
		boolean isEmpty = items.isEmpty();
		boolean hasMore = items.size() > n;
		boolean sameVersions = shownKeys != null && keys.equals(shownKeys);
		for (int i = 0; sameVersions && i < n; i++)
		{
			Row r = cache.get(keys.get(i));
			sameVersions = r != null && Objects.equals(r.version, versions.get(i));
		}
		if (sameVersions && isEmpty == shownEmpty && hasMore == shownMore)
		{
			if (hasMore)
			{
				more.setText(moreText(items.size() - n));
			}
			return;
		}

		// An empty render (reset, logged out, before the first load) is no baseline: the first rows aren't "new".
		Set<Object> fresh = highlightNew && shownKeys != null && !shownKeys.isEmpty()
			? newKeys(shownKeys, keys) : Collections.emptySet();
		Map<Object, Row> next = new LinkedHashMap<>();
		panel.removeAll();
		for (int i = 0; i < n; i++)
		{
			Object k = keys.get(i);
			Row r = cache.get(k);
			if (r == null || !Objects.equals(r.version, versions.get(i)))
			{
				JComponent row = factory.apply(items.get(i));
				JPanel wrapper = column();
				wrapper.add(row);
				wrapper.add(Box.createVerticalStrut(GAP));
				r = new Row(row, wrapper, versions.get(i));
			}
			if (fresh.contains(k))
			{
				r.row.setBackground(HIGHLIGHT);
				highlighted.add(r.row);
			}
			// A key can only appear once on screen; a duplicate keeps its first row.
			if (next.putIfAbsent(k, r) == null)
			{
				panel.add(r.wrapper);
			}
		}
		if (isEmpty)
		{
			panel.add(empty);
		}
		if (hasMore)
		{
			more.setText(moreText(items.size() - n));
			panel.add(more);
		}
		cache = next;
		shownKeys = keys;
		shownEmpty = isEmpty;
		shownMore = hasMore;
		if (!highlighted.isEmpty())
		{
			unhighlight.restart();
		}
		panel.revalidate();
		panel.repaint();
	}

	private void clearHighlight()
	{
		for (JComponent row : highlighted)
		{
			if (HIGHLIGHT.equals(row.getBackground()))
			{
				row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
			}
		}
		highlighted.clear();
	}

	private static String moreText(int remaining)
	{
		return "Show more (" + remaining + " more)";
	}

	/** Keys in {@code now} that weren't in {@code before}: rows added since the last render. */
	static Set<Object> newKeys(List<?> before, List<?> now)
	{
		Set<Object> old = new HashSet<>(before);
		Set<Object> out = new HashSet<>();
		for (Object k : now)
		{
			if (!old.contains(k))
			{
				out.add(k);
			}
		}
		return out;
	}

	/** Items paired with keys that stay unique when items repeat: {@code base + "|" + occurrence}. Pure. */
	static <T> List<Keyed<T>> withOccurrenceKeys(List<T> items, Function<T, String> base)
	{
		Map<String, Integer> seen = new HashMap<>();
		List<Keyed<T>> out = new ArrayList<>(items.size());
		for (T t : items)
		{
			String b = base.apply(t);
			int n = seen.merge(b, 1, Integer::sum);
			out.add(new Keyed<>(b + "|" + n, t));
		}
		return out;
	}

	/** A row's data with its key. */
	static final class Keyed<T>
	{
		final String key;
		final T value;

		Keyed(String key, T value)
		{
			this.key = key;
			this.value = value;
		}
	}
}

package com.hardcoreworldtoolkit.ui;

import java.util.function.Consumer;

/** What the panel's Privacy menu can do with the data this computer shared. Called on the EDT; must not block. */
public interface SharedDataActions
{
	/** Whether this computer may have shared anything: it has an install token, or it is connected. */
	boolean mayHaveShared();

	/** Whether a deletion is running now. */
	boolean isDeleting();

	/**
	 * Delete everything this computer shared, then disconnect. Returns false when a deletion is already running.
	 *
	 * @param onDone gets the message to show the player, on the EDT
	 */
	boolean delete(Consumer<String> onDone);
}

package com.hardcoreworldtoolkit.ui;

import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.geom.Area;
import java.awt.geom.Ellipse2D;
import java.awt.geom.Path2D;
import java.awt.geom.Rectangle2D;
import java.awt.geom.RoundRectangle2D;
import java.awt.image.BufferedImage;

/**
 * The plugin's skull, drawn in code so it scales to any size and the plugin ships no image for it. The eye sockets, the
 * nose and the gaps between the teeth are see-through, so it works on any background.
 */
public final class SkullIcon
{
	/** Bone white. */
	public static final Color BONE = new Color(0xe9e2d0);

	private SkullIcon()
	{
	}

	/**
	 * @param size  width and height in px
	 * @param bone  the skull's colour
	 */
	public static BufferedImage draw(int size, Color bone)
	{
		BufferedImage img = new BufferedImage(size, size, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = img.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setRenderingHint(RenderingHints.KEY_STROKE_CONTROL, RenderingHints.VALUE_STROKE_PURE);
		double s = size;
		// Cranium and jaw.
		Area skull = new Area(new Ellipse2D.Double(0.09 * s, 0.03 * s, 0.82 * s, 0.72 * s));
		skull.add(new Area(new RoundRectangle2D.Double(0.27 * s, 0.50 * s, 0.46 * s, 0.46 * s, 0.14 * s, 0.14 * s)));
		// Eye sockets.
		skull.subtract(new Area(new Ellipse2D.Double(0.20 * s, 0.30 * s, 0.24 * s, 0.26 * s)));
		skull.subtract(new Area(new Ellipse2D.Double(0.56 * s, 0.30 * s, 0.24 * s, 0.26 * s)));
		// Nose.
		Path2D nose = new Path2D.Double();
		nose.moveTo(0.50 * s, 0.57 * s);
		nose.lineTo(0.44 * s, 0.70 * s);
		nose.lineTo(0.56 * s, 0.70 * s);
		nose.closePath();
		skull.subtract(new Area(nose));
		// Teeth: gaps cut up from the bottom of the jaw.
		double gap = Math.max(1.0, 0.05 * s);
		for (double x : new double[] {0.395, 0.5, 0.605})
		{
			skull.subtract(new Area(new Rectangle2D.Double(x * s - gap / 2, 0.80 * s, gap, 0.20 * s)));
		}
		g.setColor(bone);
		g.fill(skull);
		g.dispose();
		return img;
	}
}

package com.hardcoreworldtoolkit.ui;

import java.time.DayOfWeek;
import java.time.Instant;
import java.time.LocalDate;
import java.time.YearMonth;
import java.time.ZoneId;
import java.time.ZonedDateTime;
import java.time.format.DateTimeFormatter;
import java.time.temporal.ChronoUnit;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;

/**
 * Time axis labels for the price chart, at round local times that suit the range: every few hours for 24h, days for
 * 7d, weeks for 30d and 90d, months for 1y. Pure.
 */
final class TimeTicks
{
	private static final DateTimeFormatter HOUR = DateTimeFormatter.ofPattern("HH:mm", Locale.ENGLISH);
	private static final DateTimeFormatter WEEKDAY = DateTimeFormatter.ofPattern("EEE", Locale.ENGLISH);
	private static final DateTimeFormatter DAY_MONTH = DateTimeFormatter.ofPattern("d MMM", Locale.ENGLISH);
	private static final DateTimeFormatter MONTH = DateTimeFormatter.ofPattern("MMM", Locale.ENGLISH);

	/** Tick times (unix s), ascending. */
	final long[] ts;
	final String[] labels;

	private TimeTicks(List<Long> ts, List<String> labels)
	{
		this.ts = new long[ts.size()];
		for (int i = 0; i < this.ts.length; i++)
		{
			this.ts[i] = ts.get(i);
		}
		this.labels = labels.toArray(new String[0]);
	}

	/** A label as wide as the widest this range uses, to work out how many fit. */
	static String sampleLabel(ChartRange range)
	{
		switch (range)
		{
			case H24:
				return "00:00";
			case D7:
				return "Wed";
			case Y1:
				return "May";
			default:
				return "30 May";
		}
	}

	/**
	 * @param t0        start of the axis (unix s)
	 * @param t1        end of the axis (unix s)
	 * @param zone      the player's time zone
	 * @param maxLabels most labels that fit; the finest spacing that fits is used, thinned out if none does
	 */
	static TimeTicks of(long t0, long t1, ChartRange range, ZoneId zone, int maxLabels)
	{
		List<Long> ts = new ArrayList<>();
		List<String> labels = new ArrayList<>();
		if (maxLabels <= 0 || t1 <= t0)
		{
			return new TimeTicks(ts, labels);
		}
		int[] steps;
		switch (range)
		{
			case H24:
				steps = new int[]{3, 6, 12};
				break;
			case D7:
				steps = new int[]{1, 2};
				break;
			case D30:
				steps = new int[]{1, 2};
				break;
			case D90:
				steps = new int[]{2, 3, 4, 8};
				break;
			default:
				steps = new int[]{1, 2, 3, 6};
				break;
		}
		for (int i = 0; i < steps.length; i++)
		{
			ts.clear();
			labels.clear();
			generate(t0, t1, range, steps[i], zone, ts, labels);
			if (ts.size() <= maxLabels)
			{
				return new TimeTicks(ts, labels);
			}
		}
		// Even the coarsest spacing has too many: keep every k-th.
		int k = (ts.size() + maxLabels - 1) / maxLabels;
		List<Long> thinTs = new ArrayList<>();
		List<String> thinLabels = new ArrayList<>();
		for (int i = 0; i < ts.size(); i += k)
		{
			thinTs.add(ts.get(i));
			thinLabels.add(labels.get(i));
		}
		return new TimeTicks(thinTs, thinLabels);
	}

	private static void generate(long t0, long t1, ChartRange range, int n, ZoneId zone, List<Long> ts, List<String> labels)
	{
		ZonedDateTime start = Instant.ofEpochSecond(t0).atZone(zone);
		switch (range)
		{
			case H24:
			{
				// Every n hours on the local clock (00:00, 06:00, ...).
				ZonedDateTime z = start.truncatedTo(ChronoUnit.HOURS);
				for (; z.toEpochSecond() <= t1; z = z.plusHours(1))
				{
					if (z.toEpochSecond() >= t0 && z.getHour() % n == 0)
					{
						add(ts, labels, z, HOUR);
					}
				}
				break;
			}
			case D7:
			{
				// Local midnights, every n days.
				for (LocalDate d = start.toLocalDate(); ; d = d.plusDays(1))
				{
					ZonedDateTime z = d.atStartOfDay(zone);
					if (z.toEpochSecond() > t1)
					{
						break;
					}
					if (z.toEpochSecond() >= t0 && Math.floorMod(d.toEpochDay(), n) == 0)
					{
						add(ts, labels, z, WEEKDAY);
					}
				}
				break;
			}
			case D30:
			case D90:
			{
				// Monday midnights, every n weeks.
				for (LocalDate d = start.toLocalDate(); ; d = d.plusDays(1))
				{
					ZonedDateTime z = d.atStartOfDay(zone);
					if (z.toEpochSecond() > t1)
					{
						break;
					}
					// 1970-01-05 was the first Monday after the epoch.
					long week = Math.floorDiv(d.toEpochDay() - 4, 7);
					if (z.toEpochSecond() >= t0 && d.getDayOfWeek() == DayOfWeek.MONDAY && Math.floorMod(week, n) == 0)
					{
						add(ts, labels, z, DAY_MONTH);
					}
				}
				break;
			}
			default:
			{
				// The 1st of every n-th month.
				for (YearMonth m = YearMonth.from(start); ; m = m.plusMonths(1))
				{
					ZonedDateTime z = m.atDay(1).atStartOfDay(zone);
					if (z.toEpochSecond() > t1)
					{
						break;
					}
					if (z.toEpochSecond() >= t0 && Math.floorMod(m.getYear() * 12L + m.getMonthValue() - 1, n) == 0)
					{
						add(ts, labels, z, MONTH);
					}
				}
				break;
			}
		}
	}

	private static void add(List<Long> ts, List<String> labels, ZonedDateTime z, DateTimeFormatter f)
	{
		ts.add(z.toEpochSecond());
		labels.add(f.format(z));
	}
}

package com.hardcoreworldtoolkit.ui;

import static com.hardcoreworldtoolkit.ui.PanelComponents.column;
import static com.hardcoreworldtoolkit.ui.PanelComponents.linkLabel;
import static com.hardcoreworldtoolkit.ui.PanelComponents.primaryButton;
import static com.hardcoreworldtoolkit.ui.PanelComponents.smallLabel;
import static com.hardcoreworldtoolkit.ui.PanelComponents.wrapText;
import com.hardcoreworldtoolkit.HardcoreWorldToolKitConfig;
import com.hardcoreworldtoolkit.Onboarding;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.Insets;
import java.util.Objects;
import javax.swing.Box;
