import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JOptionPane;
import javax.swing.JPanel;
import javax.swing.border.CompoundBorder;
import javax.swing.border.EmptyBorder;
import javax.swing.border.MatteBorder;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

/**
 * "Get started" card at the top of the home view: connect (what's shared; RuneLite's third-party warning is shown as a
 * confirmation when Connect is clicked) and the GE History import steps, then a one-time "Imported N trades" line.
 * EDT only.
 */
class WelcomeCard
{
	static final String[] BENEFITS = {
		"Live prices and charts",
		"Today's bond swap rate",
		"Best bid and ask for every item",
	};
	static final String SHARED_TEXT = "Shared: your trades and a hashed ID. Never your name. IP addresses are never stored.";
	private static final Color FINE_PRINT = new Color(0x8a8a8a);

	/** Asks before connecting; returns true to go ahead. Tests replace the dialog. */
	interface ConnectConfirm
	{
		boolean confirm(Component parent);
	}

	/**
	 * RuneLite's required third-party warning, shown when Connect is clicked. The settings page shows the same text
	 * through the config item's warning; the card's Connect button doesn't go through that dialog, so it asks here.
	 */
	static final ConnectConfirm WARNING_DIALOG = parent -> JOptionPane.showConfirmDialog(parent,
		HardcoreWorldToolKitConfig.THIRD_PARTY_WARNING + ".\n\nThe Hardcore World Tool Kit server never stores your IP address."
			+ "\n\nConnect now?",
		"Hardcore World Tool Kit", JOptionPane.YES_NO_OPTION, JOptionPane.WARNING_MESSAGE) == JOptionPane.YES_OPTION;

	private final Runnable onConnect;
	private final ConnectConfirm confirmConnect;
	private final Runnable onPrivacy;
	private final Runnable onDismissNotice;
	/** Outer wrapper: the card plus the gap below it, so a hidden card leaves no gap. */
	private final JPanel wrapper = column();
	private final JPanel card = column();

	private Onboarding.Step shownStep;
	private boolean shownNeedsLogin;
	private Integer shownNotice;

	/**
	 * @param onConnect       sets the connected setting
	 * @param onPrivacy       opens the privacy notice
	 * @param onDismissNotice forgets the import notice (the "x" button)
	 */
	WelcomeCard(Runnable onConnect, Runnable onPrivacy, Runnable onDismissNotice)
	{
		this(onConnect, onPrivacy, onDismissNotice, WARNING_DIALOG);
	}

	/** @param confirmConnect asks before connecting (RuneLite's third-party warning) */
	WelcomeCard(Runnable onConnect, Runnable onPrivacy, Runnable onDismissNotice, ConnectConfirm confirmConnect)
	{
		this.onConnect = onConnect;
		this.confirmConnect = confirmConnect;
		this.onPrivacy = onPrivacy;
		this.onDismissNotice = onDismissNotice;
		card.setOpaque(true);
		card.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		card.setBorder(new CompoundBorder(new MatteBorder(0, 3, 0, 0, PanelComponents.HC_RED), new EmptyBorder(8, 8, 8, 8)));
		wrapper.add(card);
		wrapper.add(Box.createVerticalStrut(8));
		wrapper.setVisible(false);
	}

	JComponent getComponent()
	{
		return wrapper;
	}

	/** Show the given state. Rebuilds only when something changed. */
	void update(Onboarding.Step step, boolean needsLogin, Integer notice)
	{
		if (step == shownStep && needsLogin == shownNeedsLogin && Objects.equals(notice, shownNotice))
		{
			return;
		}
		shownStep = step;
		shownNeedsLogin = needsLogin;
		shownNotice = notice;

		card.removeAll();
		boolean connect = step == Onboarding.Step.CONNECT || step == Onboarding.Step.CONNECT_AND_IMPORT;
		boolean showNotice = notice != null && step != Onboarding.Step.HIDDEN;
		if (connect)
		{
			JLabel title = new JLabel("See live Hardcore GE prices");
			title.setFont(FontManager.getRunescapeBoldFont());
			title.setForeground(Color.WHITE);
			title.setAlignmentX(Component.LEFT_ALIGNMENT);
			card.add(title);
			card.add(Box.createVerticalStrut(4));
		}
		if (showNotice)
		{
			card.add(noticeRow(notice));
			if (connect)
			{
				card.add(Box.createVerticalStrut(6));
			}
		}
		if (connect)
		{
			addConnectBlock();
		}
		wrapper.setVisible(connect || showNotice);
		wrapper.revalidate();
		wrapper.repaint();
	}

	private void addConnectBlock()
	{
		card.add(wrapText("Join 5,000+ players already using it.", ColorScheme.LIGHT_GRAY_COLOR));
		card.add(Box.createVerticalStrut(4));
		for (String b : BENEFITS)
		{
			card.add(wrapText("• " + b, ColorScheme.LIGHT_GRAY_COLOR));
		}
		card.add(Box.createVerticalStrut(10));
		JButton connect = primaryButton("Connect");
		connect.setPreferredSize(new Dimension(0, 34));
		connect.setMaximumSize(new Dimension(Integer.MAX_VALUE, 34));
		connect.setAlignmentX(Component.LEFT_ALIGNMENT);
		connect.addActionListener(e ->
		{
			if (confirmConnect.confirm(card))
			{
				onConnect.run();
			}
		});
		card.add(connect);
		card.add(Box.createVerticalStrut(8));
		card.add(wrapText(SHARED_TEXT, FINE_PRINT));
		card.add(linkLabel("Privacy", onPrivacy));
	}

	private JComponent noticeRow(int count)
	{
		JPanel row = new JPanel(new BorderLayout(4, 0));
		row.setOpaque(false);
		row.add(smallLabel(noticeText(count), PanelComponents.GOOD), BorderLayout.CENTER);
		JButton close = new JButton("x");
		close.setFont(FontManager.getRunescapeSmallFont());
		close.setMargin(new Insets(0, 4, 0, 4));
		close.setFocusPainted(false);
		close.setToolTipText("Dismiss");
		close.addActionListener(e -> onDismissNotice.run());
		row.add(close, BorderLayout.EAST);
		row.setAlignmentX(Component.LEFT_ALIGNMENT);
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, 20));
		return row;
	}

	/** The one-time line after the first GE History import; an empty history still counts as imported. */
	static String noticeText(int count)
	{
		return count == 0 ? "GE History read: no trades to import"
			: "Imported " + count + " trade" + (count == 1 ? "" : "s") + " from GE History";
	}
}

package com.hardcoreworldtoolkit;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class AccountIdTest
{
	@Test
	public void knownVectors()
	{
		// sha256("hardcore-world-tool-kit:123456789")
		assertEquals("7b1a2f8f6f61ed6066424c5038c1ef0aee11a83c2fe561fd8ff8a0abac8fe11a", AccountId.of(123456789L));
		// sha256("hardcore-world-tool-kit:-42")
		assertEquals("0aa4d618b4866a23a3e47e433dae25225d4aba2a2def1dab0c5a6119b6ff5cdf", AccountId.of(-42L));
	}

	@Test
	public void saltedLowercaseHex()
	{
		String id = AccountId.of(Long.MAX_VALUE);
		assertEquals(64, id.length());
		assertTrue(id.matches("[0-9a-f]{64}"));
		// Not the plain hash of the account hash: the prefix is included.
		assertNotEquals("15e2b0d3c33891ebb0f1ef609ec419420c20e320ce94c65fbc8c3312448eb225", AccountId.of(123456789L));
		assertNotEquals(AccountId.of(1L), AccountId.of(2L));
		assertEquals(AccountId.of(7L), AccountId.of(7L));
	}
}

package com.hardcoreworldtoolkit;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import java.util.List;
import org.junit.Test;

public class ActiveOfferTest
{
	@Test
	public void onlyOpenOffersInSlotOrder()
	{
		OfferTracker t = new OfferTracker(() -> "key");
		t.setSlot(2, new OfferTracker.SlotState("k2", 536, false, 1_250_000, 100, 40, 50_000_000, OfferTracker.Status.ACTIVE, 10, 20));
		t.setSlot(0, new OfferTracker.SlotState("k0", 4151, true, 5, 10, 0, 0, OfferTracker.Status.ACTIVE, 11, 21));
		// Done or fully filled: not open.
		t.setSlot(1, new OfferTracker.SlotState("k1", 4151, true, 5, 10, 10, 50, OfferTracker.Status.ACTIVE, 1, 2));
		t.setSlot(3, new OfferTracker.SlotState("k3", 4151, true, 5, 10, 3, 15, OfferTracker.Status.CANCELLED, 1, 2));
		t.setSlot(4, new OfferTracker.SlotState("k4", 4151, true, 5, 10, 10, 50, OfferTracker.Status.COMPLETE, 1, 2));

		List<ActiveOffer> offers = ActiveOffer.fromTracker(t, id -> id == 536 ? "Dragon bones" : "Abyssal whip");
		assertEquals(2, offers.size());
		assertEquals(new ActiveOffer(0, "k0", 4151, "Abyssal whip", true, 5, 10, 0, 11), offers.get(0));
		assertEquals(new ActiveOffer(2, "k2", 536, "Dragon bones", false, 1_250_000, 100, 40, 10), offers.get(1));
		assertTrue(ActiveOffer.fromTracker(new OfferTracker(() -> "x"), id -> "").isEmpty());
	}
}

package com.hardcoreworldtoolkit;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import com.hardcoreworldtoolkit.OfferWatch.Flag;
import java.util.Collections;
import org.junit.Test;

public class AlertGateTest
{
	private static final long MIN = 60_000;
	private final AlertGate gate = new AlertGate();

	@Test
	public void onlyTransitionsIntoUndercutOrOutbid()
	{
		assertFalse(gate.shouldNotify("a", Flag.OK, 0));
		assertFalse(gate.shouldNotify("a", Flag.STALE, MIN));
		assertTrue(gate.shouldNotify("a", Flag.UNDERCUT, 2 * MIN));
		// Still undercut: no repeat.
		assertFalse(gate.shouldNotify("a", Flag.UNDERCUT, 3 * MIN));
		assertFalse(gate.shouldNotify("a", Flag.UNDERCUT, 60 * MIN));
	}

	@Test
	public void cooldownPerOfferAndFlag()
	{
		assertTrue(gate.shouldNotify("a", Flag.UNDERCUT, 0));
		assertFalse(gate.shouldNotify("a", Flag.OK, 2 * MIN));
		// Undercut again within 30 minutes: quiet, and that change is used up.
		assertFalse(gate.shouldNotify("a", Flag.UNDERCUT, 10 * MIN));
		assertFalse(gate.shouldNotify("a", Flag.UNDERCUT, 40 * MIN));
		// Cleared and undercut again after the cooldown: notifies.
		assertFalse(gate.shouldNotify("a", Flag.OK, 41 * MIN));
		assertTrue(gate.shouldNotify("a", Flag.UNDERCUT, 42 * MIN));
	}

	@Test
	public void globalGapRetriesLater()
	{
		assertTrue(gate.shouldNotify("a", Flag.UNDERCUT, 0));
		// Another offer within a minute: held back, but not forgotten.
		assertFalse(gate.shouldNotify("b", Flag.OUTBID, 30_000));
		assertTrue(gate.shouldNotify("b", Flag.OUTBID, MIN + 1));
	}

	@Test
	public void resetWhenOfferGoes()
	{
		assertTrue(gate.shouldNotify("a", Flag.UNDERCUT, 0));
		gate.retain(Collections.singletonList("b"));
		// "a" was forgotten, so the cooldown no longer applies to it.
		assertTrue(gate.shouldNotify("a", Flag.UNDERCUT, 2 * MIN));
	}
}

