			+ "\"trades\":[{\"kind\":\"fill\",\"side\":\"buy\",\"qty\":1,\"price\":10,\"ts\":30}],"
			+ "\"book\":{\"bids\":[{\"price\":9,\"offers\":2,\"qty\":100}]}}";
