		assertTrue(MyTrades.isShown(ev("a", TradeEvent.HISTORY, 1, true)));
	}

	@Test
	public void addNewestPutsLatestFirstAndCaps()
	{
		MyTrades trades = new MyTrades();
		trades.addNewest(Arrays.asList(ev("a", TradeEvent.FILL, 1, false), ev("b", TradeEvent.PLACED, 2, false),
			ev("c", TradeEvent.CANCELLED, 3, false)));
		assertEquals(Arrays.asList("c", "a"), ids(trades.snapshot()));

		List<TradeEvent> many = new ArrayList<>();
		for (int i = 0; i < MyTrades.MAX + 5; i++)
		{
			many.add(ev("n" + i, TradeEvent.FILL, 10 + i, false));
		}
		trades.addNewest(many);
		List<TradeEvent> snap = trades.snapshot();
		assertEquals(MyTrades.MAX, snap.size());
		assertEquals("n" + (MyTrades.MAX + 4), snap.get(0).getId());
		assertEquals("n5", snap.get(MyTrades.MAX - 1).getId());

		trades.clear();
		assertTrue(trades.snapshot().isEmpty());
	}

	@Test
	public void mergeLoadedFillsNamesAndSortsNewestFirst()
	{
		MyTrades trades = new MyTrades();
		trades.addNewest(Arrays.asList(ev("live5", TradeEvent.FILL, 5, false), ev("live7", TradeEvent.FILL, 7, false)));
		trades.mergeLoaded(trades.session(), Arrays.asList(ev("log3", TradeEvent.FILL, 3, false), ev("log5", TradeEvent.FILL, 5, false),
			ev("log9", TradeEvent.FILL, 9, false)), e -> e.toBuilder().name("named " + e.getId()).build());

		List<TradeEvent> snap = trades.snapshot();
		// Equal times keep live trades ahead of loaded ones.
		assertEquals(Arrays.asList("log9", "live7", "live5", "log5", "log3"), ids(snap));
		assertEquals("named log9", snap.get(0).getName());
		assertNull(snap.get(1).getName());
	}

	@Test
	public void mergeLoadedCapsTotal()
	{
		MyTrades trades = new MyTrades();
		trades.addNewest(Collections.singletonList(ev("live", TradeEvent.FILL, 0, false)));
		List<TradeEvent> loaded = new ArrayList<>();
		for (int i = 0; i < MyTrades.MAX; i++)
		{
			loaded.add(ev("f" + i, TradeEvent.FILL, 100 + i, false));
		}
		trades.mergeLoaded(trades.session(), loaded, UnaryOperator.identity());
		List<TradeEvent> snap = trades.snapshot();
		assertEquals(MyTrades.MAX, snap.size());
		assertEquals("f0", snap.get(MyTrades.MAX - 1).getId());
	}

	@Test
	public void loadFromAnEarlierSessionIsDropped()
	{
		MyTrades trades = new MyTrades();
		int oldSession = trades.session();
		// Plugin stopped and started again while the first log read was still running.
		trades.clear();
		int newSession = trades.session();
		List<TradeEvent> log = Collections.singletonList(ev("logged", TradeEvent.FILL, 1, false));

		assertFalse(trades.mergeLoaded(oldSession, log, UnaryOperator.identity()));
		assertTrue(trades.snapshot().isEmpty());

		assertTrue(trades.mergeLoaded(newSession, log, UnaryOperator.identity()));
		assertEquals(Collections.singletonList("logged"), ids(trades.snapshot()));
	}

}

package com.hardcoreworldtoolkit;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.net.InetAddress;
import java.net.NetworkInterface;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Enumeration;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.TreeSet;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.LinkedBlockingQueue;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.regex.Pattern;
import org.junit.Test;

/**
 * The plugin never sends an IP address: no request (register, submit, delete, market reads) carries an IP-like field,
 * header or query parameter, and no request contains an address of this machine or any IPv4 literal. The user-facing
 * texts no longer list "your IP address" among what is shared, while RuneLite's mandatory warning stays verbatim
 * (the welcome card's line is checked in WelcomeCardTest).
 */
public class NoIpSentTest
{
	private static final Pattern IP_NAME = Pattern.compile("(?i)(^|[-_])ip($|[-_])|ipaddr|ip_?hash|^ip[A-Z]|"
		+ "address|forwarded|real-?ip|client-?ip|remote|^via$|^host$");
	private static final Pattern IPV4 = Pattern.compile("(?<![\\d.])(\\d{1,3}\\.){3}\\d{1,3}(?![\\d.])");

	private final Gson gson = new Gson();
	private final FakeServer server = new FakeServer();
	private final Map<String, String> config = new ConcurrentHashMap<>();
	private final InstallIdentity identity = FakeServer.identity(config);
	private final AtomicBoolean connected = new AtomicBoolean(true);

	private static TradeEvent fill(String id)
	{
		return TradeEvent.builder().id(id).kind(TradeEvent.FILL).side(TradeEvent.BUY).itemId(4151).qty(3)
			.price(290_000).total(870_000L).slot(2).offerKey("k1").ts(1000).late(false).filled(3).since(900L)
			.world(9000).name("Abyssal whip").build();
	}

	/** Every address of this machine's network interfaces, as text (e.g. "192.168.1.5", "fe80:0:0:0:..."). */
	private static List<String> localAddresses() throws Exception
	{
		List<String> out = new ArrayList<>();
		Enumeration<NetworkInterface> nis = NetworkInterface.getNetworkInterfaces();
		for (NetworkInterface ni : nis == null ? Collections.<NetworkInterface>emptyList() : Collections.list(nis))
		{
			for (InetAddress a : Collections.list(ni.getInetAddresses()))
			{
				String s = a.getHostAddress();
				int pct = s.indexOf('%');
				out.add(pct >= 0 ? s.substring(0, pct) : s);
			}
		}
		out.add(InetAddress.getLocalHost().getHostAddress());
		return out;
	}

	private static void collectKeys(JsonElement e, Set<String> keys)
	{
		if (e == null || e.isJsonNull() || e.isJsonPrimitive())
		{
			return;
		}
		if (e.isJsonArray())
		{
			e.getAsJsonArray().forEach(c -> collectKeys(c, keys));
			return;
		}
		for (Map.Entry<String, JsonElement> en : e.getAsJsonObject().entrySet())
		{
			keys.add(en.getKey());
			collectKeys(en.getValue(), keys);
		}
	}

	private static void assertNoIp(okhttp3.Request req, String body, List<String> local)
	{
		String where = req.method() + " " + req.url().encodedPath();
		for (String h : req.headers().names())
		{
			assertFalse(where + " header " + h, IP_NAME.matcher(h).find());
		}
		for (String q : req.url().queryParameterNames())
		{
			assertFalse(where + " query " + q, IP_NAME.matcher(q).find());
		}
		Set<String> keys = new TreeSet<>();
		if (body != null && !body.isEmpty())
		{
			collectKeys(new Gson().fromJson(body, JsonElement.class), keys);
		}
		for (String k : keys)
		{
			assertFalse(where + " field " + k, IP_NAME.matcher(k).find());
		}
		String all = req.url() + "\n" + req.headers() + "\n" + (body == null ? "" : body);
		assertFalse(where + " has an IPv4 literal: " + all, IPV4.matcher(all).find());
		String lower = all.toLowerCase(Locale.ROOT);
		for (String a : local)
		{
			assertFalse(where + " contains local address " + a, lower.contains(a.toLowerCase(Locale.ROOT)));
		}
	}

	@Test
	public void registerSubmitAndDeleteCarryNoIp() throws Exception
	{
		List<String> local = localAddresses();
		TradeUploader up = new TradeUploader(server.api(gson, connected::get), gson, ids ->
		{
		}, identity, connected::get);
		up.add(fill("k1:fill:3"), "acct-hash");
		up.addItem(4151, "Abyssal whip", null, 70);
		JsonObject offer = TradeUploader.offerJson(2, new OfferTracker.SlotState("k1", 4151, true, 290_000, 10, 3,
			870_000, OfferTracker.Status.ACTIVE, 900, 1000));
		up.setOpenOffers(9000, "acct-hash", Collections.singletonList(offer));
		up.flush();

		FakeServer.Seen reg = server.next();
		assertEquals(FakeServer.REGISTER, reg.path());
		// Registration sends the install id and nothing else.
		assertEquals(Collections.singleton("installId"), reg.json().keySet());
		assertNoIp(reg.request, reg.body, local);

		FakeServer.Seen sub = server.next();
		assertEquals(FakeServer.SUBMIT, sub.path());
		assertTrue(sub.json().has("offers"));
		assertNoIp(sub.request, sub.body, local);
		FakeServer.awaitIdle(up);

		DataDeletion deletion = new DataDeletion(server.api(gson, connected::get), gson, identity, up,
			() -> connected.set(false));
		LinkedBlockingQueue<DataDeletion.Result> results = new LinkedBlockingQueue<>();
		assertTrue(deletion.start(results::add));
		FakeServer.Seen del = server.next();
		assertEquals(FakeServer.ME, del.path());
		assertNoIp(del.request, del.body, local);
		assertNull(server.poll(100));
	}

	@Test
	public void marketReadsCarryNoIp() throws Exception
	{
		List<String> local = localAddresses();
		MarketClient market = new MarketClient(server.api(gson, connected::get), gson, FakeServer.BASE, 9000);
		market.recent(5, r ->
		{
		}, err ->
		{
		});
		market.item(4151, true, r ->
		{
		}, err ->
		{
		});
		market.items(java.util.Arrays.asList(4151, 385), true, r ->
		{
		}, err ->
		{
		});
		for (int i = 0; i < 3; i++)
		{
			FakeServer.Seen s = server.next();
			assertNoIp(s.request, s.body, local);
		}
	}

	@Test
	public void ownTextsSayIpsAreNeverStoredButTheRuneLiteWarningIsVerbatim() throws Exception
	{
		String warning = "This feature submits your IP address to a 3rd-party server not controlled or verified by"
			+ " RuneLite developers";
		assertEquals(warning, HardcoreWorldToolKitConfig.THIRD_PARTY_WARNING);
		net.runelite.client.config.ConfigItem item = HardcoreWorldToolKitConfig.class.getMethod("connected")
			.getAnnotation(net.runelite.client.config.ConfigItem.class);
		assertEquals(warning, item.warning());

		// The Connect setting says what is shared and that IPs are never stored.
		assertFalse(item.description().contains("your IP address"));
		assertTrue(item.description(), item.description().contains("never stored")
			|| item.description().contains("never stores IP addresses"));

		// The one-line plugin descriptions (Plugin Hub list and tooltip) stay short, but say sharing is opt-in.
		List<String> ours = new ArrayList<>();
		ours.add(HardcoreWorldToolKitPlugin.class.getAnnotation(net.runelite.client.plugins.PluginDescriptor.class)
			.description());
		java.util.Properties props = new java.util.Properties();
		try (java.io.InputStream in = new java.io.FileInputStream("runelite-plugin.properties"))
		{
			props.load(in);
		}
		ours.add(props.getProperty("description"));
		for (String s : ours)
		{
			assertFalse(s, s.contains("your IP address"));
			assertTrue(s, s.contains("opt-in"));
			assertTrue(s, s.length() <= 120);
		}
		// The short README (the Plugin Hub page) and the full write-up in docs/TECHNICAL.md.
		String readme = new String(java.nio.file.Files.readAllBytes(java.nio.file.Paths.get("README.md")),
			java.nio.charset.StandardCharsets.UTF_8);
		String technical = new String(java.nio.file.Files.readAllBytes(java.nio.file.Paths.get("docs", "TECHNICAL.md")),
			java.nio.charset.StandardCharsets.UTF_8);
		assertTrue(readme.contains("never stores IP addresses"));
		assertTrue(technical.contains("> " + warning + "."));
		assertTrue(technical.contains("never stores, hashes or logs it"));
		for (String doc : new String[]{readme, technical})
		{
			assertFalse(doc.contains("reveal your IP address"));
			assertFalse(doc.contains("expose your IP address"));
		}
	}
}

package com.hardcoreworldtoolkit;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import com.google.gson.Gson;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collection;
import java.util.Collections;
import java.util.List;
import java.util.function.Consumer;
import org.junit.Before;
import org.junit.Test;

public class OfferMarketWatchTest
{
	private static final long T0 = 1_700_000_000_000L;

	/** A request the fake fetcher received, answered by the test. */
	private static final class Call
	{
		final List<Integer> ids;
		final Consumer<MarketData.ItemsResponse> ok;
		final Consumer<String> err;

		Call(Collection<Integer> ids, Consumer<MarketData.ItemsResponse> ok, Consumer<String> err)
		{
			this.ids = new ArrayList<>(ids);
			this.ok = ok;
			this.err = err;
		}
	}

	private final List<Call> calls = new ArrayList<>();
	private final List<OfferReport> reports = new ArrayList<>();
	private final List<String> alerts = new ArrayList<>();
	private long now = T0;
	private boolean connected = true;
	private boolean notify = true;
	private boolean panelShown;
	private OfferMarketWatch watch;

	@Before
	public void setUp()
	{
		watch = new OfferMarketWatch((ids, fresh, ok, err) -> calls.add(new Call(ids, ok, err)), () -> now, () -> connected,
			() -> notify, () -> panelShown, () -> 6 * 3600L, Collections::emptyList, new OfferMarketWatch.Listener()
		{
			@Override
			public void onReport(OfferReport report)
			{
				reports.add(report);
			}

			@Override
			public void onAlert(String message)
			{
				alerts.add(message);
			}
		});
	}

	private static ActiveOffer sell(int slot, int itemId, long price)
	{
		return new ActiveOffer(slot, "k" + slot, itemId, "Item " + itemId, false, price, 10, 0, T0 / 1000);
	}

	private static MarketData.ItemsResponse items(String json)
	{
		return new Gson().fromJson(json, MarketData.ItemsResponse.class);
	}

	@Test
	public void newItemAsksRightAwayThenAutoWaitsAMinute()
	{
		watch.setOffers(Collections.singletonList(sell(0, 536, 1000)));
		assertEquals(1, calls.size());
		assertEquals(Collections.singletonList(536), calls.get(0).ids);
		calls.get(0).ok.accept(items("{\"items\":[]}"));

		now += 59_000;
		assertFalse(watch.refresh(false));
		now += 1_000;
		assertTrue(watch.refresh(false));
		assertEquals(2, calls.size());
	}

	@Test
	public void onDemandEveryTenSeconds()
	{
		watch.setOffers(Collections.singletonList(sell(0, 536, 1000)));
		calls.get(0).ok.accept(items("{}"));
		now += 5_000;
		assertFalse(watch.refresh(true));
		// The rate-limited request is remembered and made by the next periodic call once allowed.
		now += 5_000;
		assertTrue(watch.refresh(false));
		assertEquals(2, calls.size());
	}

	@Test
	public void noRequestWhileOneIsRunning()
	{
		watch.setOffers(Collections.singletonList(sell(0, 536, 1000)));
		now += 120_000;
		assertFalse(watch.refresh(true));
		assertEquals(1, calls.size());
	}

	@Test
	public void nothingWhenDisconnectedOrNoOffers()
	{
		assertFalse(watch.refresh(true));
		connected = false;
		watch.setOffers(Collections.singletonList(sell(0, 536, 1000)));
		assertFalse(watch.refresh(true));
		assertTrue(calls.isEmpty());
		// Reports carry no market statuses while disconnected.
		assertTrue(reports.get(reports.size() - 1).getStatuses().isEmpty());
	}

	@Test
	public void sameItemsReuseQuotesWithoutFetching()
	{
		watch.setOffers(Collections.singletonList(sell(0, 536, 1000)));
		calls.get(0).ok.accept(items("{\"items\":[{\"id\":536,\"bestAsk\":900}]}"));
		assertEquals(OfferWatch.Flag.UNDERCUT, reports.get(reports.size() - 1).getStatuses().get(0).getFlag());

		// The offer filled a bit: same item, so it is re-evaluated with the quotes held.
		now += 1_000;
		watch.setOffers(Collections.singletonList(new ActiveOffer(0, "k0", 536, "Item 536", false, 1000, 10, 3, T0 / 1000)));
		assertEquals(1, calls.size());
		assertEquals(OfferWatch.Flag.UNDERCUT, reports.get(reports.size() - 1).getStatuses().get(0).getFlag());
	}

	@Test
	public void responseFiltersAndAlertsOnce()
	{
		watch.setOffers(Arrays.asList(sell(0, 536, 1000), sell(1, 4151, 2_000_000)));
		assertEquals(Arrays.asList(536, 4151), calls.get(0).ids);
		// A server that ignores ids sends everything.
		calls.get(0).ok.accept(items("{\"items\":[{\"id\":536,\"bestAsk\":900},{\"id\":4151},{\"id\":11832,\"bestAsk\":1}]}"));
		OfferReport r = reports.get(reports.size() - 1);
		assertEquals(OfferWatch.Flag.UNDERCUT, r.getStatuses().get(0).getFlag());
		assertEquals(OfferWatch.Flag.OK, r.getStatuses().get(1).getFlag());
		assertEquals(T0, r.getCheckedAt());
		assertNull(r.getError());
		assertEquals(Collections.singletonList("Hardcore World Tool Kit: your Item 536 sell offer (1,000) was undercut at 900."), alerts);

		now += 60_000;
		assertTrue(watch.refresh(false));
		calls.get(1).ok.accept(items("{\"items\":[{\"id\":536,\"bestAsk\":900}]}"));
		assertEquals(1, alerts.size());
	}

	@Test
	public void errorIsReportedAndOldResponsesDroppedAfterReset()
	{
		watch.setOffers(Collections.singletonList(sell(0, 536, 1000)));
		calls.get(0).err.accept("Can't reach the server.");
		assertEquals("Can't reach the server.", reports.get(reports.size() - 1).getError());

		now += 10_000;
		assertTrue(watch.refresh(true));
		watch.reset();
		calls.get(1).ok.accept(items("{\"items\":[{\"id\":536,\"bestAsk\":900}]}"));
		// Dropped: the report after reset has no quote for the item.
		assertEquals(OfferWatch.Flag.OK, reports.get(reports.size() - 1).getStatuses().get(0).getFlag());
		assertTrue(alerts.isEmpty());
		// Reset allows a new request at once.
		assertTrue(watch.refresh(false));
	}

	@Test
	public void automaticChecksOnlyWhenSomethingUsesThem()
	{
		notify = false;
		panelShown = false;
		watch.setOffers(Collections.singletonList(sell(0, 536, 1000)));
		assertEquals("a new item doesn't fetch for a hidden panel", 0, calls.size());
		now += OfferMarketWatch.AUTO_MS;
		assertFalse(watch.refresh(false));
		assertEquals(0, calls.size());

		panelShown = true;
		assertTrue(watch.refresh(false));
		assertEquals(1, calls.size());
		calls.get(0).ok.accept(items("{\"items\":[]}"));

		panelShown = false;
		now += OfferMarketWatch.AUTO_MS;
		assertFalse(watch.refresh(false));
		notify = true;
		assertTrue("notifications use automatic checks", watch.refresh(false));
		assertEquals(2, calls.size());
	}
}

package com.hardcoreworldtoolkit;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import com.google.gson.Gson;
import java.util.Arrays;
import java.util.Map;
import org.junit.Test;

public class OfferQuotesTest
{
	private static MarketData.ItemsResponse parse(String json)
	{
		return new Gson().fromJson(json, MarketData.ItemsResponse.class);
	}

	@Test
	public void serverIgnoringIdsExtraItemsDropped()
	{
		MarketData.ItemsResponse r = parse("{\"time\":5,\"items\":["
			+ "{\"id\":536,\"bestAsk\":1200,\"bestBid\":1100,\"lastSell\":1190,\"lastSellTime\":4,\"vol24\":10},"
			+ "{\"id\":4151,\"bestAsk\":2000000},"
			+ "{\"id\":11832,\"lastBuy\":30000000,\"lastBuyTime\":3}]}");
		Map<Integer, OfferWatch.Quote> q = OfferQuotes.filter(r, Arrays.asList(536, 11832));
		assertEquals(2, q.size());
		// Book only: the batch's last trades may be GE History rows timestamped at import.
		assertEquals(new OfferWatch.Quote(1100L, 1200L, null, null, null, null), q.get(536));
		assertTrue(q.containsKey(11832));
		assertNull(q.get(11832).getLastBuy());
	}

	@Test
	public void missingIdsAreAbsent()
	{
		Map<Integer, OfferWatch.Quote> q = OfferQuotes.filter(parse("{\"items\":[{\"id\":536}]}"), Arrays.asList(536, 4151));
		assertEquals(1, q.size());
		assertTrue(q.containsKey(536));
	}

	@Test
	public void emptyOrNullResponse()
	{
		assertTrue(OfferQuotes.filter(parse("{}"), Arrays.asList(1)).isEmpty());
		assertTrue(OfferQuotes.filter(null, Arrays.asList(1)).isEmpty());
	}
}

package com.hardcoreworldtoolkit;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import com.hardcoreworldtoolkit.OfferTracker.Snapshot;
import com.hardcoreworldtoolkit.OfferTracker.Status;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.concurrent.atomic.AtomicInteger;
import net.runelite.api.GrandExchangeOffer;
import net.runelite.api.GrandExchangeOfferState;
import org.junit.Before;
import org.junit.Test;

public class OfferTrackerTest
{
	private static final int WHIP = 4151;
	private static final int WORLD = 9000;

	private OfferTracker tracker;

	@Before
	public void setUp()
	{
		AtomicInteger n = new AtomicInteger();
		tracker = new OfferTracker(() -> "offer" + n.incrementAndGet());
	}

	private static Snapshot buy(int total, int sold, long spent, Status status)
	{
		return new Snapshot(WHIP, true, 300_000, total, sold, spent, status);
	}

	@Test
	public void newOfferEmitsPlaced()
	{
		List<TradeEvent> ev = tracker.update(0, buy(10, 0, 0, Status.ACTIVE), false, 100, WORLD);
		assertEquals(1, ev.size());
		TradeEvent e = ev.get(0);
		assertEquals(TradeEvent.PLACED, e.getKind());
		assertEquals("buy", e.getSide());
		assertEquals(10, e.getQty());
		assertEquals(300_000, e.getPrice());
		assertEquals("offer1:placed", e.getId());
		assertFalse(e.isLate());
	}

	@Test
	public void partialFillsReportDeltasAtActualPrice()
	{
		tracker.update(0, buy(10, 0, 0, Status.ACTIVE), false, 100, WORLD);
		List<TradeEvent> ev = tracker.update(0, buy(10, 3, 870_000, Status.ACTIVE), false, 110, WORLD);
		assertEquals(1, ev.size());
		assertEquals(TradeEvent.FILL, ev.get(0).getKind());
		assertEquals(3, ev.get(0).getQty());
		assertEquals(290_000, ev.get(0).getPrice());
		assertEquals(Long.valueOf(870_000), ev.get(0).getTotal());
		assertEquals(Integer.valueOf(3), ev.get(0).getFilled());

		ev = tracker.update(0, buy(10, 10, 2_970_000, Status.COMPLETE), false, 120, WORLD);
		assertEquals(1, ev.size());
		assertEquals(7, ev.get(0).getQty());
		assertEquals(300_000, ev.get(0).getPrice());
		assertEquals("offer1:fill:10", ev.get(0).getId());
	}

	@Test
	public void loginReplayOfUnchangedOfferEmitsNothing()
	{
		tracker.update(0, buy(10, 3, 870_000, Status.ACTIVE), false, 100, WORLD);
		List<TradeEvent> ev = tracker.update(0, buy(10, 3, 870_000, Status.ACTIVE), true, 200, WORLD);
		assertTrue(ev.isEmpty());
	}

	@Test
	public void fillsWhileLoggedOutAreMarkedLate()
	{
		tracker.update(0, buy(10, 0, 0, Status.ACTIVE), false, 100, WORLD);
		List<TradeEvent> ev = tracker.update(0, buy(10, 10, 3_000_000, Status.COMPLETE), true, 5000, WORLD);
		assertEquals(1, ev.size());
		assertTrue(ev.get(0).isLate());
		assertEquals(10, ev.get(0).getQty());
		assertEquals(Long.valueOf(100), ev.get(0).getSince());
	}

	@Test
	public void liveFillsHaveNoSince()
	{
		tracker.update(0, buy(10, 0, 0, Status.ACTIVE), false, 100, WORLD);
		List<TradeEvent> ev = tracker.update(0, buy(10, 2, 600_000, Status.ACTIVE), false, 150, WORLD);
		assertNull(ev.get(0).getSince());
		// The next late fill is bounded by the last time we saw the offer (150), not when it was placed.
		ev = tracker.update(0, buy(10, 5, 1_500_000, Status.ACTIVE), true, 9000, WORLD);
		assertEquals(Long.valueOf(150), ev.get(0).getSince());
	}

	@Test
	public void cancelReportsUnfilledRemainder()
	{
		tracker.update(0, buy(10, 0, 0, Status.ACTIVE), false, 100, WORLD);
		tracker.update(0, buy(10, 4, 1_200_000, Status.ACTIVE), false, 110, WORLD);
		List<TradeEvent> ev = tracker.update(0, buy(10, 4, 1_200_000, Status.CANCELLED), false, 120, WORLD);
		assertEquals(1, ev.size());
		assertEquals(TradeEvent.CANCELLED, ev.get(0).getKind());
		assertEquals(6, ev.get(0).getQty());
		// A repeat of the cancelled state (e.g. on relog) doesn't re-report it.
		assertTrue(tracker.update(0, buy(10, 4, 1_200_000, Status.CANCELLED), true, 130, WORLD).isEmpty());
	}

	@Test
	public void collectingClearsSlotAndNextOfferIsNew()
	{
		tracker.update(0, buy(10, 10, 3_000_000, Status.COMPLETE), false, 100, WORLD);
		tracker.update(0, new Snapshot(0, false, 0, 0, 0, 0, Status.EMPTY), false, 110, WORLD);
		assertNull(tracker.getSlot(0));
		List<TradeEvent> ev = tracker.update(0, buy(10, 0, 0, Status.ACTIVE), false, 120, WORLD);
		assertEquals(TradeEvent.PLACED, ev.get(0).getKind());
		assertEquals("offer2:placed", ev.get(0).getId());
	}

	@Test
	public void identicalOfferPlacedAfterAMissedCollectionIsNew()
	{
		// Cancelled with nothing filled, collected while we weren't watching, then the same offer placed again.
		tracker.update(0, buy(10, 0, 0, Status.ACTIVE), false, 100, WORLD);
		tracker.update(0, buy(10, 0, 0, Status.CANCELLED), false, 110, WORLD);
		List<TradeEvent> ev = tracker.update(0, buy(10, 0, 0, Status.ACTIVE), true, 200, WORLD);
		assertEquals(1, ev.size());
		assertEquals(TradeEvent.PLACED, ev.get(0).getKind());
		assertEquals("offer2:placed", ev.get(0).getId());
		// Its fills belong to the new offer.
		ev = tracker.update(0, buy(10, 10, 3_000_000, Status.COMPLETE), false, 210, WORLD);
		assertEquals("offer2:fill:10", ev.get(0).getId());
	}

	@Test
	public void sameItemDifferentPriceIsANewOffer()
	{
		tracker.update(0, buy(10, 0, 0, Status.ACTIVE), false, 100, WORLD);
		List<TradeEvent> ev = tracker.update(0, new Snapshot(WHIP, true, 310_000, 10, 0, 0, Status.ACTIVE), false, 110, WORLD);
		assertEquals(TradeEvent.PLACED, ev.get(0).getKind());
		assertEquals(310_000, ev.get(0).getPrice());
	}

	@Test
	public void completedOffersAreMatchedAgainstHistoryOnce()
	{
		tracker.update(0, buy(10, 0, 0, Status.ACTIVE), false, 100, WORLD);
		tracker.update(0, buy(10, 10, 2_950_000, Status.COMPLETE), false, 110, WORLD);
		String sig = OfferTracker.signature(true, WHIP, 10, 2_950_000);
		assertTrue(tracker.consumeCompleted(sig));
		assertFalse(tracker.consumeCompleted(sig));
	}

	@Test
	public void sellSide()
	{
		tracker.update(3, new Snapshot(WHIP, false, 280_000, 2, 0, 0, Status.ACTIVE), false, 100, WORLD);
		List<TradeEvent> ev = tracker.update(3, new Snapshot(WHIP, false, 280_000, 2, 2, 600_000, Status.COMPLETE), false, 110, WORLD);
		assertEquals("sell", ev.get(0).getSide());
		assertEquals(300_000, ev.get(0).getPrice());
		assertEquals(Integer.valueOf(3), ev.get(0).getSlot());
	}

	private static GrandExchangeOffer offer(GrandExchangeOfferState state)
	{
		return new GrandExchangeOffer()
		{
			@Override
			public int getQuantitySold()
			{
				return 4;
			}

			@Override
			public int getItemId()
			{
				return WHIP;
			}

			@Override
			public int getTotalQuantity()
			{
				return 10;
			}

			@Override
			public long getPrice()
			{
				return 300_000;
			}

			@Override
			public long getSpent()
			{
				return 1_150_000;
			}

			@Override
			public GrandExchangeOfferState getState()
			{
				return state;
			}
		};
	}

	@Test
	public void snapshotOfMapsEveryState()
	{
		assertEquals(new Snapshot(WHIP, true, 300_000, 10, 4, 1_150_000, Status.ACTIVE), Snapshot.of(offer(GrandExchangeOfferState.BUYING)));
		assertEquals(new Snapshot(WHIP, true, 300_000, 10, 4, 1_150_000, Status.COMPLETE), Snapshot.of(offer(GrandExchangeOfferState.BOUGHT)));
		assertEquals(new Snapshot(WHIP, true, 300_000, 10, 4, 1_150_000, Status.CANCELLED), Snapshot.of(offer(GrandExchangeOfferState.CANCELLED_BUY)));
		assertEquals(new Snapshot(WHIP, false, 300_000, 10, 4, 1_150_000, Status.ACTIVE), Snapshot.of(offer(GrandExchangeOfferState.SELLING)));
		assertEquals(new Snapshot(WHIP, false, 300_000, 10, 4, 1_150_000, Status.COMPLETE), Snapshot.of(offer(GrandExchangeOfferState.SOLD)));
		assertEquals(new Snapshot(WHIP, false, 300_000, 10, 4, 1_150_000, Status.CANCELLED), Snapshot.of(offer(GrandExchangeOfferState.CANCELLED_SELL)));
