	@Test
	public void dailyBucketsUseTheZoneAndSevenDayWindow()
	{
		ZoneId ny = ZoneId.of("America/New_York");
		ProfitBook b = new ProfitBook();
		b.apply(fill(TradeEvent.BUY, 100, 100, T0), ny);
		// 2026-03-17T03:00Z is still the 16th in New York.
		long lateEvening = Instant.parse("2026-03-17T03:00:00Z").getEpochSecond();
		b.apply(fill(TradeEvent.SELL, 1, 110, lateEvening), ny);
		long sixDaysBefore = Instant.parse("2026-03-10T16:00:00Z").getEpochSecond();
		b.apply(fill(TradeEvent.SELL, 1, 120, sixDaysBefore), ny);
		long sevenDaysBefore = Instant.parse("2026-03-09T16:00:00Z").getEpochSecond();
		b.apply(fill(TradeEvent.SELL, 1, 140, sevenDaysBefore), ny);

		assertEquals(Long.valueOf(10), b.daily().get("2026-03-16"));
		LocalDate today = LocalDate.of(2026, 3, 16);
		ProfitSnapshot s = b.snapshot(today, false, false);
		assertEquals(10, s.today(today));
		assertEquals(30, s.last7(today));
		assertEquals(70, s.getAllTime());
		// The snapshot only keeps what the 7-day window can still need.
		assertFalse(s.getRecentDaily().containsKey("2026-03-09"));
		// A later day: nothing today, the 7-day window has moved on.
		assertEquals(0, s.today(today.plusDays(1)));
		assertEquals(10, s.last7(today.plusDays(1)));
	}

	@Test
	public void dailyIsPruned()
	{
		ProfitBook b = new ProfitBook();
		b.apply(fill(TradeEvent.BUY, 1_000, 1, T0), UTC);
		for (int d = 0; d < ProfitBook.DAILY_DAYS + 50; d++)
		{
			b.apply(fill(TradeEvent.SELL, 1, 2, T0 + d * 86_400L), UTC);
		}
		assertTrue(b.daily().size() <= ProfitBook.DAILY_DAYS + 1);
		assertEquals(LocalDate.of(2026, 3, 10).plusDays(ProfitBook.DAILY_DAYS + 49).toString(),
			b.daily().keySet().stream().reduce((x, y) -> y).get());
		// All time still counts every day.
		assertEquals(ProfitBook.DAILY_DAYS + 50, b.getAllTime());
	}

	@Test
	public void billionsDontOverflow()
	{
		ProfitBook b = new ProfitBook();
		long price = 2_000_000_000L;
		b.apply(fill(TradeEvent.BUY, 1_000, price, T0), UTC);
		b.apply(fill(TradeEvent.BUY, 1_000, price, T0), UTC);
		b.apply(fill(TradeEvent.SELL, 999, price + 1, T0), UTC);
		ProfitBook.Position p = b.position(ITEM);
		assertEquals(999, p.realized);
		assertEquals(1_001, p.held);
		assertEquals(1_001 * price, p.basis);
		assertEquals(price, b.snapshot(LocalDate.of(2026, 3, 10), false, false).item(ITEM).getAvgCost());
	}

	@Test
	public void mulDivRoundsAndSurvivesOverflow()
	{
		assertEquals(3, ProfitBook.mulDiv(10, 1, 3));
		assertEquals(7, ProfitBook.mulDiv(20, 1, 3));
		assertEquals(Long.MAX_VALUE / 2, ProfitBook.mulDiv(Long.MAX_VALUE / 2, 1_000_000, 1_000_000));
		assertEquals(4_611_686_018_427_387_904L, ProfitBook.mulDiv(Long.MAX_VALUE, 3, 6));
	}

	@Test
	public void topItemsBestFirst()
	{
		ProfitBook b = new ProfitBook();
		for (int item = 1; item <= 7; item++)
		{
			b.apply(trade(TradeEvent.FILL, item, TradeEvent.BUY, 1, 100, T0), UTC);
			b.apply(trade(TradeEvent.FILL, item, TradeEvent.SELL, 1, 100 + item * 10, T0), UTC);
		}
		ProfitSnapshot s = b.snapshot(LocalDate.of(2026, 3, 10), false, false);
		assertEquals(ProfitBook.TOP, s.getTop().size());
		assertEquals(7, s.getTop().get(0).getItemId());
		assertEquals(70, s.getTop().get(0).getRealized());
		assertEquals(3, s.getTop().get(4).getItemId());
	}

	@Test
	public void jsonRoundTrip()
	{
		Gson gson = new Gson();
		ProfitBook b = new ProfitBook();
		b.apply(fill(TradeEvent.BUY, 10, 100, T0), UTC);
		b.apply(fill(TradeEvent.SELL, 4, 150, T0), UTC);
		b.apply(trade(TradeEvent.HISTORY, 4151, TradeEvent.SELL, 1, 2_000_000, T0), UTC);
		ProfitBook back = gson.fromJson(gson.toJson(b), ProfitBook.class).sanitized();
		assertTrue(back.sameAs(b));
		assertEquals("Dragon bones", back.position(ITEM).name);

		// A damaged or older file without some fields still loads.
		ProfitBook partial = gson.fromJson("{\"allTime\":5}", ProfitBook.class).sanitized();
		assertEquals(5, partial.getAllTime());
		assertTrue(partial.isEmpty());
		assertTrue(partial.apply(fill(TradeEvent.BUY, 1, 1, T0), UTC));
		ProfitBook nulls = gson.fromJson("{\"items\":null,\"daily\":null}", ProfitBook.class).sanitized();
		assertTrue(nulls.apply(fill(TradeEvent.SELL, 1, 1, T0), UTC));
	}
}

package com.hardcoreworldtoolkit;

import static com.hardcoreworldtoolkit.ProfitBookTest.trade;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import com.google.gson.Gson;
import com.google.gson.JsonObject;
import java.nio.charset.StandardCharsets;
import java.time.Clock;
import java.time.Instant;
import java.time.ZoneOffset;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.concurrent.CopyOnWriteArrayList;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import net.runelite.client.util.Filepath;
import org.junit.After;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

public class ProfitStoreTest
{
	private static final String A = AccountId.of(1L);
	private static final String B = AccountId.of(2L);
	private static final Clock CLOCK = Clock.fixed(Instant.parse("2026-03-20T12:00:00Z"), ZoneOffset.UTC);
	private static final long JAN = Instant.parse("2026-01-15T12:00:00Z").getEpochSecond();
	private static final long FEB = Instant.parse("2026-02-15T12:00:00Z").getEpochSecond();
	private static final long APR = Instant.parse("2026-04-01T00:00:01Z").getEpochSecond();

	@Rule
	public TemporaryFolder tmp = new TemporaryFolder();

	private final Gson gson = new Gson();
	private final List<ProfitSnapshot> published = new CopyOnWriteArrayList<>();
	private ScheduledExecutorService executor;

	@Before
	public void setUp()
	{
		executor = Executors.newSingleThreadScheduledExecutor();
	}

	@After
	public void tearDown()
	{
		executor.shutdownNow();
	}

	private Filepath dir()
	{
		return Filepath.Unchecked.getRooted(tmp.getRoot().toPath()).joinSegment("hardcore-world-tool-kit");
	}

	private ProfitStore store()
	{
		return new ProfitStore(this::dir, gson, executor, CLOCK, published::add);
	}

	/** Run {@code r} on the executor and wait for it (and everything queued before it). */
	private void on(Runnable r) throws Exception
	{
		executor.submit(r).get(10, TimeUnit.SECONDS);
	}

	private void awaitRebuild(ProfitStore s) throws Exception
	{
		for (int i = 0; i < 1_000; i++)
		{
			if (!executor.submit(s::isRebuilding).get(10, TimeUnit.SECONDS))
			{
				return;
			}
		}
		throw new AssertionError("rebuild never finished");
	}

	private static TradeEvent buy(int qty, long price, long ts)
	{
		return trade(TradeEvent.FILL, 536, TradeEvent.BUY, qty, price, ts);
	}

	private static TradeEvent sell(int qty, long price, long ts)
	{
		return trade(TradeEvent.FILL, 536, TradeEvent.SELL, qty, price, ts);
	}

	private void log(String acct, TradeEvent... events) throws Exception
	{
		List<String> lines = new ArrayList<>();
		for (TradeEvent e : events)
		{
			lines.add(gson.toJson(HardcoreWorldToolKitPlugin.logLine(gson, e, acct)));
		}
		LocalTradeLog.append(dir(), LocalTradeLog.monthOf(events[0].getTs()), lines);
	}

	private static ProfitBook live(TradeEvent... events)
	{
		ProfitBook b = new ProfitBook();
		for (TradeEvent e : events)
		{
			b.apply(e, ZoneOffset.UTC);
		}
		return b;
	}

	@Test
	public void fileNameIsFromTheHashOnly()
	{
		assertEquals("profit-" + A.substring(0, 16) + ".json", ProfitStore.fileName(A));
		assertNull(ProfitStore.fileName("Zezima"));
		assertNull(ProfitStore.fileName("../../x"));
		assertNull(ProfitStore.fileName(null));
		assertNull(ProfitStore.fileName("abc"));
	}

	@Test
	public void savesAndLoadsPerAccount() throws Exception
	{
		ProfitStore s = store();
		on(() -> s.load(A));
		on(() -> s.apply(A, Arrays.asList(buy(10, 100, JAN), sell(4, 150, JAN)), false));
		assertEquals(200, published.get(published.size() - 1).getAllTime());
		// Switching account saves the old one first.
		on(() -> s.load(B));
		assertTrue(dir().joinSegment(ProfitStore.fileName(A)).isFile());
		assertEquals(0, published.get(published.size() - 1).getAllTime());
		on(() -> s.apply(B, Collections.singletonList(sell(1, 5, JAN)), false));
		on(s::close);
		assertTrue(dir().joinSegment(ProfitStore.fileName(B)).isFile());
		// A closed store ignores late events.
		int count = published.size();
		on(() -> s.apply(B, Collections.singletonList(sell(1, 5, JAN)), false));
		assertEquals(count, published.size());

		ProfitStore again = store();
		on(() -> again.load(A));
		assertTrue(again.book().sameAs(live(buy(10, 100, JAN), sell(4, 150, JAN))));
		on(() -> again.load(B));
		assertEquals(5, again.book().getUnknownProceeds());
	}

	@Test
	public void applyToAnotherAccountSwitchesFirst() throws Exception
	{
		ProfitStore s = store();
		on(() -> s.load(A));
		on(() -> s.apply(B, Collections.singletonList(buy(1, 1, JAN)), false));
		on(() -> s.apply(null, Collections.singletonList(sell(1, 3, JAN)), false));
		on(() -> s.load(A));
		assertTrue(s.book().isEmpty());
		on(() -> s.load(B));
		assertEquals(2, s.book().getAllTime());
	}

	@Test
	public void debouncedSaveWritesTheFile() throws Exception
	{
		ProfitStore s = store();
		on(() -> s.load(A));
		on(() -> s.apply(A, Collections.singletonList(buy(1, 1, JAN)), false));
		assertFalse(dir().joinSegment(ProfitStore.fileName(A)).exists());
		on(s::saveNow);
		assertTrue(dir().joinSegment(ProfitStore.fileName(A)).isFile());
	}

	@Test
	public void damagedFileStartsFromZero() throws Exception
	{
		Filepath d = dir();
		d.createDirectories();
		d.joinSegment(ProfitStore.fileName(A)).write("{not json".getBytes(StandardCharsets.UTF_8));
		ProfitStore s = store();
		on(() -> s.load(A));
		assertTrue(s.book().isEmpty());
		assertFalse(published.isEmpty());
	}

	@Test
	public void rebuildFiltersOtherAccountsAndCountsLinesWithoutAnAccount() throws Exception
	{
		TradeEvent l1 = buy(10, 100, JAN - 86_400 * 60);
		log(null, l1);
		TradeEvent a1 = sell(4, 150, JAN), a2 = buy(6, 200, FEB), a3 = sell(12, 160, FEB);
		TradeEvent b1 = sell(100, 1_000, JAN);
		log(A, a1);
		log(B, b1);
		log(A, a2, a3);

		ProfitStore s = store();
		on(() -> s.load(A));
		on(s::rebuild);
		awaitRebuild(s);
		assertTrue(s.book().sameAs(live(l1, a1, a2, a3)));
		assertTrue(dir().joinSegment(ProfitStore.fileName(A)).isFile());
		ProfitSnapshot last = published.get(published.size() - 1);
		assertFalse(last.isRebuilding());
		assertTrue(last.isLogAvailable());
		assertTrue(published.stream().anyMatch(ProfitSnapshot::isRebuilding));
	}

	@Test
	public void rebuildCountsEventsRecordedWhileItRunsOnce() throws Exception
	{
		TradeEvent l1 = buy(10, 100, JAN - 86_400 * 60);
		log(A, l1);
		TradeEvent a1 = sell(2, 150, JAN), a2 = buy(4, 120, FEB);
		log(A, a1);
		log(A, a2);
		ProfitStore s = store();
		on(() -> s.load(A));
		// Count what's already logged live too, so the store starts with the same numbers.
		on(() -> s.apply(A, Arrays.asList(l1, a1, a2), false));

		// Queue the rebuild and, behind it, events recorded meanwhile, the way the plugin does: append, then apply.
		TradeEvent feb2 = sell(3, 200, FEB + 60), apr = sell(1, 300, APR);
		executor.execute(s::rebuild);
		for (TradeEvent e : Arrays.asList(feb2, apr))
		{
			executor.execute(() ->
			{
				try
				{
					log(A, e);
				}
				catch (Exception ex)
				{
					throw new IllegalStateException(ex);
				}
				s.apply(A, Collections.singletonList(e), true);
			});
		}
		awaitRebuild(s);
		// The April file didn't exist when the rebuild listed the log; it is still read, and nothing counts twice.
		assertTrue(s.book().sameAs(live(l1, a1, a2, feb2, apr)));
	}

	@Test
	public void rebuildWithoutAccountOrLogStillPublishes() throws Exception
	{
		ProfitStore s = store();
		on(s::rebuild);
		assertEquals(1, published.size());
		assertFalse(published.get(0).isLogAvailable());
		on(() -> s.load(A));
		on(s::rebuild);
		awaitRebuild(s);
		assertTrue(s.book().isEmpty());
		assertFalse(published.get(published.size() - 1).isRebuilding());
	}

	@Test
	public void belongsTo()
	{
		JsonObject noAccount = new JsonObject();
		assertTrue(ProfitStore.belongsTo(noAccount, A));
		JsonObject mine = new JsonObject();
		mine.addProperty("acct", A);
		assertTrue(ProfitStore.belongsTo(mine, A));
		assertFalse(ProfitStore.belongsTo(mine, B));
		JsonObject odd = new JsonObject();
		odd.add("acct", new JsonObject());
		assertFalse(ProfitStore.belongsTo(odd, A));
	}

	@Test
	public void rebuildCountsInTimeOrder() throws Exception
	{
		// A sell, then (appended later, into the same month) the buy from before it.
		TradeEvent sold = sell(10, 150, FEB + 600);
		TradeEvent bought = trade(TradeEvent.FILL, 536, TradeEvent.BUY, 10, 100, FEB);
		log(A, sold);
		log(A, bought);
		ProfitStore s = store();
		on(() -> s.load(A));
		on(s::rebuild);
		awaitRebuild(s);
		// Counted where it happened: the buy is the sell's cost basis.
		assertTrue(s.book().sameAs(live(bought, sold)));
		assertEquals(500, s.book().getAllTime());
		assertEquals(0, s.book().getUnknownProceeds());
	}

}

package com.hardcoreworldtoolkit;

import static org.junit.Assert.assertEquals;
import java.io.IOException;
import java.nio.ByteBuffer;
import java.nio.channels.SeekableByteChannel;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import org.junit.Test;

public class ReverseLineReaderTest
{
	private static final int[] CHUNKS = {1, 2, 3, 5, 64 * 1024};

	/** An in-memory channel, so no files are needed. */
	private static final class BytesChannel implements SeekableByteChannel
	{
		private final byte[] bytes;
		private long position;
		private boolean open = true;

		BytesChannel(byte[] bytes)
		{
			this.bytes = bytes;
		}

		@Override
		public int read(ByteBuffer dst)
		{
			if (position >= bytes.length)
			{
				return -1;
			}
			int n = (int) Math.min(dst.remaining(), bytes.length - position);
			dst.put(bytes, (int) position, n);
			position += n;
			return n;
		}

		@Override
		public int write(ByteBuffer src)
		{
			throw new UnsupportedOperationException();
		}

		@Override
		public long position()
		{
			return position;
		}

		@Override
		public SeekableByteChannel position(long p)
		{
			position = p;
			return this;
		}

		@Override
		public long size()
		{
			return bytes.length;
		}

		@Override
		public SeekableByteChannel truncate(long size)
		{
			throw new UnsupportedOperationException();
		}

		@Override
		public boolean isOpen()
		{
			return open;
		}

		@Override
		public void close()
		{
			open = false;
		}
	}

	private static List<String> readAll(String text, int chunk) throws IOException
	{
		List<String> lines = new ArrayList<>();
		try (ReverseLineReader r = new ReverseLineReader(new BytesChannel(text.getBytes(StandardCharsets.UTF_8)), chunk))
		{
			String line;
			while ((line = r.readLine()) != null)
			{
				lines.add(line);
			}
			// Stays at the start.
			assertEquals(null, r.readLine());
		}
		return lines;
	}

	private static void check(String text, String... newestFirst) throws IOException
	{
		for (int chunk : CHUNKS)
		{
			assertEquals("chunk " + chunk, Arrays.asList(newestFirst), readAll(text, chunk));
		}
	}

	@Test
	public void linesComeBackNewestFirst() throws IOException
	{
		check("one\ntwo\nthree\n", "three", "two", "one");
	}

	@Test
	public void noTrailingNewline() throws IOException
	{
		check("one\ntwo", "two", "one");
	}

	@Test
	public void emptyFile() throws IOException
	{
		check("");
		check("\n\n\r\n");
	}

	@Test
	public void blankLinesAreSkipped() throws IOException
	{
		check("\none\n\n\ntwo\n\n", "two", "one");
	}

	@Test
	public void crlfIsStripped() throws IOException
	{
		check("one\r\ntwo\r\n", "two", "one");
	}

	@Test
	public void multiByteCharactersSplitAcrossChunks() throws IOException
	{
		// "×" and "é" are two bytes each; small chunk sizes split them.
		check("{\"n\":\"3 × café\"}\n{\"n\":\"é×é\"}\n", "{\"n\":\"é×é\"}", "{\"n\":\"3 × café\"}");
		check("×\né", "é", "×");
	}

	@Test
	public void longLinesSpanManyChunks() throws IOException
	{
		String a = String.join("", Collections.nCopies(500, "a")), b = String.join("", Collections.nCopies(300, "bé"));
		check(a + "\n" + b + "\n", b, a);
	}
}

