/** Install tokens on upload: register first, Authorization on every submit, one re-register on 401, never logged. */
public class TradeUploaderAuthTest
{
	private final Gson gson = new Gson();
	private final FakeServer server = new FakeServer();
	private final Map<String, String> config = new ConcurrentHashMap<>();
	private final InstallIdentity identity = FakeServer.identity(config);
	private final AtomicBoolean allowed = new AtomicBoolean(true);

	private TradeUploader uploader()
	{
		return new TradeUploader(server.api(gson, allowed::get), gson, ids ->
		{
		}, identity, allowed::get);
	}

	private static TradeEvent fill(String id)
	{
		return TradeEvent.builder().id(id).kind(TradeEvent.FILL).side(TradeEvent.BUY).itemId(4151).qty(1)
			.price(1).total(1L).ts(1).world(9000).build();
	}

	@Test
	public void firstFlushRegistersThenSubmitsWithTheToken() throws InterruptedException
	{
		TradeUploader up = uploader();
		up.add(fill("e1"), "acct");
		up.flush();

		FakeServer.Seen reg = server.next();
		assertEquals(REGISTER, reg.path());
		assertNull(reg.auth());
		String id = identity.installId();
		assertEquals(id, reg.json().get("installId").getAsString());
		assertTrue(reg.request.body().contentType().toString().startsWith("application/json"));

		FakeServer.Seen sub = server.next();
		assertEquals(SUBMIT, sub.path());
		String token = identity.token();
		assertEquals("Bearer " + token, sub.auth());
		assertEquals(id, sub.json().get("installId").getAsString());
		awaitIdle(up);
		assertFalse(up.hasPending());

		// The token is kept: the next upload doesn't register again.
		up.add(fill("e2"), "acct");
		up.flush();
		FakeServer.Seen again = server.next();
		assertEquals(SUBMIT, again.path());
		assertEquals("Bearer " + token, again.auth());
		awaitIdle(up);
	}

	@Test
	public void nothingIsSentWhileNotConnectedOrSharing() throws InterruptedException
	{
		TradeUploader up = uploader();
		allowed.set(false);
		up.add(fill("e1"), "acct");
		up.flush();
		assertNull("nothing, not even a registration, before Connect", server.poll(200));
		assertFalse(up.isInFlight());
		assertNull(identity.token());

		// Allowed, but nothing queued: no registration either.
		allowed.set(true);
		TradeUploader empty = uploader();
		empty.flush();
		assertNull(server.poll(200));
		assertFalse(empty.isInFlight());

		up.flush();
		assertEquals(REGISTER, server.next().path());
		assertEquals(SUBMIT, server.next().path());
		awaitIdle(up);
	}

	@Test
	public void disconnectingDuringRegistrationStopsTheChain() throws InterruptedException
	{
		TradeUploader up = uploader();
		up.add(fill("e1"), "acct");
		server.beforeReply = () -> allowed.set(false);
		up.flush();
		assertEquals(REGISTER, server.next().path());
		awaitIdle(up);
		assertNull("no upload after the player disconnected", server.poll(200));
		assertTrue(up.hasPending());
	}

	@Test
	public void unauthorizedRegistersOnceAndResends() throws InterruptedException
	{
		String old = tok('o');
		String fresh = tok('n');
		String id = identity.installId();
		identity.setToken(id, old);
		server.on(SUBMIT, status(401), status(200)).on(REGISTER, token(fresh));
		TradeUploader up = uploader();
		up.add(fill("e1"), "acct");
		up.flush();

		FakeServer.Seen first = server.next();
		assertEquals(SUBMIT, first.path());
		assertEquals("Bearer " + old, first.auth());
		FakeServer.Seen reg = server.next();
		assertEquals(REGISTER, reg.path());
		assertEquals(id, reg.json().get("installId").getAsString());
		FakeServer.Seen retry = server.next();
		assertEquals(SUBMIT, retry.path());
		assertEquals("Bearer " + fresh, retry.auth());
		assertEquals("the same batch", first.json().get("events"), retry.json().get("events"));
		awaitIdle(up);
		assertEquals(fresh, identity.token());
		assertFalse(up.hasPending());
	}

	@Test
	public void secondUnauthorizedDoesNotLoopAndKeepsTheQueue() throws InterruptedException
	{
		identity.setToken(identity.installId(), tok('o'));
		server.on(SUBMIT, status(401), status(401));
		TradeUploader up = uploader();
		up.add(fill("e1"), "acct");
		up.flush();
		assertEquals(SUBMIT, server.next().path());
		assertEquals(REGISTER, server.next().path());
		assertEquals(SUBMIT, server.next().path());
		awaitIdle(up);
		assertNull("no loop", server.poll(300));
		assertTrue("queue kept", up.hasPending());

		// The next flush sends it again.
		up.flush();
		FakeServer.Seen s = server.next();
		assertEquals(SUBMIT, s.path());
		assertEquals("e1", s.json().getAsJsonArray("events").get(0).getAsJsonObject().get("id").getAsString());
		awaitIdle(up);
		assertFalse(up.hasPending());
	}

	@Test
	public void conflictOnRegisterRotatesTheInstallId() throws InterruptedException
	{
		String first = identity.installId();
		server.on(REGISTER, status(409));
		TradeUploader up = uploader();
		up.add(fill("e1"), "acct");
		up.flush();

		assertEquals(first, server.next().json().get("installId").getAsString());
		FakeServer.Seen second = server.next();
		assertEquals(REGISTER, second.path());
		String rotated = second.json().get("installId").getAsString();
		assertNotEquals(first, rotated);
		FakeServer.Seen sub = server.next();
		assertEquals(SUBMIT, sub.path());
		assertEquals("uploads use the id the token was issued for", rotated, sub.json().get("installId").getAsString());
		awaitIdle(up);
		assertEquals(rotated, identity.installId());
		assertEquals("another key holds the old id: it is remembered for an erasure request",
			Collections.singletonList(first), identity.lostInstallIds());
	}

	@Test
	public void aDeletedIdIsRotatedWithoutBeingRemembered() throws InterruptedException
	{
		String first = identity.installId();
		server.on(REGISTER, json(409, "{\"error\":\"installId deleted\"}"));
		TradeUploader up = uploader();
		up.add(fill("e1"), "acct");
		up.flush();
		assertEquals(first, server.next().json().get("installId").getAsString());
		assertEquals(REGISTER, server.next().path());
		assertEquals(SUBMIT, server.next().path());
		awaitIdle(up);
		assertNotEquals(first, identity.installId());
		assertTrue("its data is gone already", identity.lostInstallIds().isEmpty());
	}

	@Test
	public void twoConflictsGiveUpUntilTheNextFlush() throws InterruptedException
	{
		server.on(REGISTER, status(409), status(409));
		TradeUploader up = uploader();
		up.add(fill("e1"), "acct");
		up.flush();
		assertEquals(REGISTER, server.next().path());
		assertEquals(REGISTER, server.next().path());
		awaitIdle(up);
		assertNull(server.poll(200));
		assertTrue(up.hasPending());
	}

	@Test
	public void inFlightIsNeverStuck() throws InterruptedException
	{
		FakeServer.Reply[] registerFailures = {status(429), status(500), ioFailure(), json(200, "not json"),
			json(200, "{\"token\":\"too-short\"}"), json(200, "{}")};
		for (FakeServer.Reply r : registerFailures)
		{
			server.on(REGISTER, r);
			TradeUploader up = uploader();
			up.add(fill("e1"), "acct");
			up.flush();
			assertEquals(REGISTER, server.next().path());
			awaitIdle(up);
			assertNull(server.poll(100));
			assertTrue(up.hasPending());
			assertNull(identity.token());
		}

		// Submit failures with a token.
		identity.setToken(identity.installId(), tok('t'));
		for (FakeServer.Reply r : new FakeServer.Reply[]{ioFailure(), status(500), status(429)})
		{
			server.on(SUBMIT, r);
			TradeUploader up = uploader();
			up.add(fill("e1"), "acct");
			up.flush();
			assertEquals(SUBMIT, server.next().path());
			awaitIdle(up);
			assertTrue(up.hasPending());
		}

		// 401, then the re-registration fails.
		server.on(SUBMIT, status(401)).on(REGISTER, ioFailure());
		TradeUploader up = uploader();
		up.add(fill("e1"), "acct");
		up.flush();
		assertEquals(SUBMIT, server.next().path());
		assertEquals(REGISTER, server.next().path());
		awaitIdle(up);
		assertTrue(up.hasPending());
	}

	@Test
	public void pausedUploaderSendsNothingAndWhenIdleWaitsForTheChain() throws InterruptedException
	{
		java.util.concurrent.CountDownLatch hold = new java.util.concurrent.CountDownLatch(1);
		identity.setToken(identity.installId(), tok('t'));
		server.on(SUBMIT, FakeServer.heldUntil(hold));
		TradeUploader up = uploader();
		up.add(fill("e1"), "acct");
		up.flush();
		assertEquals(SUBMIT, server.next().path());
		assertTrue(up.isInFlight());

		up.pause();
		AtomicBoolean ran = new AtomicBoolean();
		up.whenIdle(() -> ran.set(true));
		assertFalse("still in flight", ran.get());
		hold.countDown();
		assertTrue(FakeServer.await(ran::get));

		up.add(fill("e2"), "acct");
		up.flush();
		assertNull("paused", server.poll(200));
		up.resume();
		up.flush();
		assertEquals(SUBMIT, server.next().path());
		awaitIdle(up);

		// Idle: runs right away.
		AtomicBoolean now = new AtomicBoolean();
		up.whenIdle(() -> now.set(true));
		assertTrue(now.get());
		assertFalse(up.isInFlight());
	}

	@Test
	public void everyUploadCarriesTheToken() throws InterruptedException
	{
		String id = identity.installId();
		identity.setToken(id, tok('u'));
		TradeUploader up = uploader();
		up.add(fill("e1"), null);
		up.flush();
		FakeServer.Seen s = server.next();
		assertEquals(SUBMIT, s.path());
		assertEquals("Bearer " + tok('u'), s.auth());
		awaitIdle(up);
	}

	@Test
	public void theTokenIsNeverLogged() throws InterruptedException
	{
		Logger pluginLogger = (Logger) LoggerFactory.getLogger("com.hardcoreworldtoolkit");
		Level oldLevel = pluginLogger.getLevel();
		ListAppender<ILoggingEvent> appender = new ListAppender<>();
		appender.start();
		pluginLogger.addAppender(appender);
		pluginLogger.setLevel(Level.ALL);
		try
		{
			String old = tok('q');
			String a = tok('r');
			String b = tok('s');
			identity.setToken(identity.installId(), old);
			// 401 -> re-register -> 401 again; then a 409 rotation and a malformed register body.
			server.on(SUBMIT, status(401), status(401), status(500))
				.on(REGISTER, token(a), status(409), token(b));
			TradeUploader up = new TradeUploader(server.api(gson, allowed::get), gson, ids ->
			{
				throw new IllegalStateException("listener boom");
			}, identity, allowed::get);
			up.add(fill("e1"), "acct");
			up.flush();
			for (int i = 0; i < 3; i++)
			{
				server.next();
			}
			awaitIdle(up);
			identity.clearToken(identity.installId());
			up.flush();
			for (int i = 0; i < 3; i++)
			{
				server.next();
			}
			awaitIdle(up);
			server.on(REGISTER, json(200, "{\"token\":\"" + old + "\" broken"));
			identity.clearToken(identity.installId());
			up.flush();
			server.next();
			awaitIdle(up);

			assertFalse("the test should exercise some logging", appender.list.isEmpty());
			for (ILoggingEvent e : appender.list)
			{
				String text = e.getFormattedMessage() + throwableText(e.getThrowableProxy());
				for (String t : new String[]{old, a, b})
				{
					assertFalse("token in log: " + text, text.contains(t));
				}
			}
		}
		finally
		{
			pluginLogger.detachAppender(appender);
			pluginLogger.setLevel(oldLevel);
		}
	}

	private static String throwableText(IThrowableProxy t)
	{
		StringBuilder sb = new StringBuilder();
		for (IThrowableProxy p = t; p != null; p = p.getCause())
		{
			sb.append(' ').append(p.getClassName()).append(": ").append(p.getMessage());
		}
		return sb.toString();
	}
}

package com.hardcoreworldtoolkit;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import com.google.gson.Gson;
import com.google.gson.JsonObject;
import java.awt.image.BufferedImage;
import java.io.IOException;
import java.util.function.Consumer;
import java.util.HashMap;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.BlockingQueue;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.LinkedBlockingQueue;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicInteger;
import okhttp3.Call;
import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;
import okhttp3.Protocol;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;
import okio.Buffer;
import org.junit.Test;

/**
 * Flush must never throw or leave the in-flight flag stuck, whatever state the queues are in. No network: requests
 * are answered by an interceptor.
 */
public class TradeUploaderFlushTest
{
	private static final HttpUrl BASE = HttpUrl.get("http://localhost:1");
	private static final String PNG_BASE64_PREFIX = "iVBORw0KGgo";

	private final Gson gson = new Gson();
	/** Requests seen by the fake server, in order. */
	private final BlockingQueue<Request> requests = new LinkedBlockingQueue<>();

	/** The plugin's uploader, with a token already issued (as after registering): uploads go straight out. */
	private TradeUploader uploader(OkHttpClient http, Consumer<Set<Integer>> onSent)
	{
		InstallIdentity id = FakeServer.identity(new HashMap<>());
		id.setToken(id.installId(), FakeServer.tok('f'));
		return new TradeUploader(new ServerApi(http, gson, BASE, FakeServer.config(() -> true)), gson, onSent, id,
			() -> true);
	}

	private OkHttpClient fakeServer()
	{
		return new OkHttpClient.Builder()
			.addInterceptor(chain ->
			{
				requests.add(chain.request());
				return new Response.Builder()
					.request(chain.request())
					.protocol(Protocol.HTTP_1_1)
					.code(200)
					.message("fake")
					.body(ResponseBody.create(null, ""))
					.build();
			})
			.build();
	}

	private static TradeEvent fill(int world)
	{
		return TradeEvent.builder().id("k:fill:1").kind(TradeEvent.FILL).side(TradeEvent.BUY).itemId(4151).qty(1)
			.price(1).total(1L).ts(1).world(world).build();
	}

	private static BufferedImage visibleImage()
	{
		BufferedImage img = new BufferedImage(4, 4, BufferedImage.TYPE_INT_ARGB);
		img.setRGB(1, 1, 0xff00ff00);
		return img;
	}

	/** An image that counts pixel reads, so a test can tell when the PNG encoding (which scans pixels) ran. */
	private static final class CountingImage extends BufferedImage
	{
		final AtomicInteger reads = new AtomicInteger();

		CountingImage()
		{
			super(4, 4, BufferedImage.TYPE_INT_ARGB);
			super.setRGB(1, 1, 0xff00ff00);
		}

		@Override
		public int getRGB(int x, int y)
		{
			reads.incrementAndGet();
			return super.getRGB(x, y);
		}
	}

	/** Waits for the response callback to clear the in-flight flag. */
	private static void awaitIdle(TradeUploader up) throws InterruptedException
	{
		for (int i = 0; i < 500 && up.isInFlight(); i++)
		{
			TimeUnit.MILLISECONDS.sleep(10);
		}
		assertFalse("in-flight flag stuck", up.isInFlight());
	}

	@Test
	public void nextKeyHandlesEmptySnapshot()
	{
		Map<TradeUploader.BatchKey, List<JsonObject>> offers = new ConcurrentHashMap<>();
		// The old flush assumed the offers map was still non-empty here and threw NoSuchElementException.
		assertNull(TradeUploader.nextKey(null, offers));
		offers.put(new TradeUploader.BatchKey(9000, "a"), Collections.emptyList());
		assertEquals(new TradeUploader.BatchKey(9000, "a"), TradeUploader.nextKey(null, offers));
		assertEquals(new TradeUploader.BatchKey(318, "b"),
			TradeUploader.nextKey(new TradeUploader.Queued(fill(318), "b"), offers));
	}

	private JsonObject nextBody() throws InterruptedException, IOException
	{
		Request req = requests.poll(5, TimeUnit.SECONDS);
		assertNotNull("expected a request", req);
		Buffer buf = new Buffer();
		req.body().writeTo(buf);
		return gson.fromJson(buf.readUtf8(), JsonObject.class);
	}

	@Test
	public void batchesNeverMixAccounts() throws InterruptedException, IOException
	{
		TradeUploader up = uploader(fakeServer(), ids ->
		{
		});
		TradeEvent a1 = fill(9000).toBuilder().id("a1").build();
		TradeEvent b1 = fill(9000).toBuilder().id("b1").build();
		TradeEvent a2 = fill(9000).toBuilder().id("a2").build();
		TradeEvent n1 = fill(9000).toBuilder().id("n1").build();
		up.add(a1, "acct-a");
		up.add(b1, "acct-b");
		up.add(a2, "acct-a");
		up.add(n1, null);

		up.flush();
		JsonObject first = nextBody();
		awaitIdle(up);
		assertEquals("acct-a", first.get("accountId").getAsString());
		assertEquals(2, first.getAsJsonArray("events").size());
		assertEquals("a1", first.getAsJsonArray("events").get(0).getAsJsonObject().get("id").getAsString());
		assertEquals("a2", first.getAsJsonArray("events").get(1).getAsJsonObject().get("id").getAsString());

		up.flush();
		JsonObject second = nextBody();
		awaitIdle(up);
		assertEquals("acct-b", second.get("accountId").getAsString());
		assertEquals(1, second.getAsJsonArray("events").size());
		assertEquals("b1", second.getAsJsonArray("events").get(0).getAsJsonObject().get("id").getAsString());

		// Unknown account: its own batch, and no accountId field at all.
		up.flush();
		JsonObject third = nextBody();
		awaitIdle(up);
		assertFalse(third.has("accountId"));
		assertEquals("n1", third.getAsJsonArray("events").get(0).getAsJsonObject().get("id").getAsString());

		up.flush();
		assertNull(requests.poll(200, TimeUnit.MILLISECONDS));
	}

	@Test
	public void openOffersGoWithTheirAccount() throws InterruptedException, IOException
	{
		TradeUploader up = uploader(fakeServer(), ids ->
		{
		});
		JsonObject offer = new JsonObject();
		offer.addProperty("slot", 1);
		up.setOpenOffers(9000, "acct-b", Collections.singletonList(offer));
		up.add(fill(9000), "acct-a");

		up.flush();
		JsonObject first = nextBody();
		awaitIdle(up);
		assertEquals("acct-a", first.get("accountId").getAsString());
		assertFalse(first.has("offers"));

		up.flush();
		JsonObject second = nextBody();
		awaitIdle(up);
		assertEquals("acct-b", second.get("accountId").getAsString());
		assertEquals(0, second.getAsJsonArray("events").size());
		assertEquals(1, second.getAsJsonArray("offers").size());
	}

	@Test
	public void flushOnEmptyAfterClearDoesNotWedge() throws InterruptedException
	{
		TradeUploader up = uploader(fakeServer(), ids ->
		{
		});
		// Open offers queued, then dropped (sharing switched off) right before the flush ran.
		up.setOpenOffers(9000, null, Collections.emptyList());
		up.clear();
		up.flush();
		assertFalse(up.isInFlight());
		assertNull(requests.poll());

		// The uploader still works afterwards.
		up.add(fill(9000), null);
		up.flush();
		assertNotNull(requests.poll(5, TimeUnit.SECONDS));
		awaitIdle(up);
	}

	@Test
	public void flushThatThrowsResetsInFlight() throws InterruptedException
	{
		AtomicInteger calls = new AtomicInteger();
		OkHttpClient real = fakeServer();
		OkHttpClient failingOnce = new OkHttpClient()
		{
			@Override
			public Call newCall(Request request)
			{
				if (calls.getAndIncrement() == 0)
				{
					throw new IllegalStateException("boom");
				}
				return real.newCall(request);
			}
		};
		TradeUploader up = uploader(failingOnce, ids ->
		{
		});
		up.add(fill(9000), null);

		up.flush(); // must not throw
		assertFalse(up.isInFlight());

		up.flush();
		assertNotNull(requests.poll(5, TimeUnit.SECONDS));
		awaitIdle(up);
	}

	@Test
	public void iconIsEncodedOnlyOnceRendered()
	{
		TradeUploader.ItemInfo info = new TradeUploader.ItemInfo(4151, "Abyssal whip");
		info.image = visibleImage();

		// Added but not rendered yet: nothing to encode.
		TradeUploader.encodeIcon(info);
		assertNull(info.icon);

		info.imageReady = true;
		TradeUploader.encodeIcon(info);
		assertNotNull(info.icon);
		assertTrue(info.icon.startsWith(PNG_BASE64_PREFIX));
	}

	@Test
	public void addItemDoesNotEncodeButFlushSendsTheIcon() throws InterruptedException, IOException
	{
		TradeUploader up = uploader(fakeServer(), ids ->
		{
		});
		CountingImage img = new CountingImage();
		up.addItem(4151, "Abyssal whip", img);
		up.setIcon(4151, img);
		assertFalse(up.needsItem(4151));
		// addItem/setIcon run on the client thread: they must not scan or encode the image.
		assertEquals(0, img.reads.get());

		// Items ride along with a batch of events.
		up.add(fill(9000), null);
		up.flush();
		Request req = requests.poll(5, TimeUnit.SECONDS);
		assertNotNull(req);
		// The encoding happened in flush.
		assertTrue(img.reads.get() > 0);
		Buffer buf = new Buffer();
		req.body().writeTo(buf);
		JsonObject body = gson.fromJson(buf.readUtf8(), JsonObject.class);
		JsonObject item = body.getAsJsonArray("items").get(0).getAsJsonObject();
		assertEquals("Abyssal whip", item.get("name").getAsString());
		assertTrue(item.get("icon").getAsString().startsWith(PNG_BASE64_PREFIX));
		awaitIdle(up);
	}

	private OkHttpClient serverAnswering(int code)
	{
		return new OkHttpClient.Builder()
			.addInterceptor(chain ->
			{
				requests.add(chain.request());
				return new Response.Builder().request(chain.request()).protocol(Protocol.HTTP_1_1).code(code)
					.message("fake").body(ResponseBody.create(null, "")).build();
			})
			.build();
	}

	@Test
	public void onSentGetsTheBatchItemIdsOnlyOnSuccess() throws InterruptedException
	{
		BlockingQueue<Set<Integer>> sent = new LinkedBlockingQueue<>();
		TradeUploader up = uploader(fakeServer(), sent::add);
		up.add(fill(9000), "a");
		up.add(fill(9000).toBuilder().id("x").itemId(536).build(), "a");
		up.flush();
		assertNotNull(requests.poll(5, TimeUnit.SECONDS));
		assertEquals(new HashSet<>(Arrays.asList(4151, 536)), sent.poll(5, TimeUnit.SECONDS));
		awaitIdle(up);

		// Offers only: nothing traded, nothing to report.
		up.setOpenOffers(9000, "a", Collections.emptyList());
		up.flush();
		assertNotNull(requests.poll(5, TimeUnit.SECONDS));
		awaitIdle(up);
		assertNull(sent.poll(200, TimeUnit.MILLISECONDS));

		// Server errors: not sent, not reported.
		for (int code : new int[]{500, 400})
		{
			TradeUploader failing = uploader(serverAnswering(code), sent::add);
			failing.add(fill(9000), "a");
			failing.flush();
			assertNotNull(requests.poll(5, TimeUnit.SECONDS));
			awaitIdle(failing);
			assertNull(sent.poll(200, TimeUnit.MILLISECONDS));
		}
	}

	@Test
	public void throwingOnSentDoesNotWedgeTheUploader() throws InterruptedException
	{
		TradeUploader up = uploader(fakeServer(), ids ->
		{
			throw new IllegalStateException("boom");
		});
		up.add(fill(9000), null);
		up.flush();
		assertNotNull(requests.poll(5, TimeUnit.SECONDS));
		awaitIdle(up);
		up.add(fill(9000).toBuilder().id("2").build(), null);
		up.flush();
		assertNotNull(requests.poll(5, TimeUnit.SECONDS));
		awaitIdle(up);
	}
}

package com.hardcoreworldtoolkit;

import static org.junit.Assert.assertEquals;
import com.hardcoreworldtoolkit.OfferTracker.SlotState;
import com.hardcoreworldtoolkit.OfferTracker.Status;
import com.google.gson.Gson;
import com.google.gson.JsonObject;
import java.util.Arrays;
import java.util.Collections;
import org.junit.Test;

/**
 * Pins the submit request body, which is the server's contract.
 */
public class TradeUploaderTest
{
	private final Gson gson = new Gson();

	private static final String OFFER_JSON = "{\"slot\":2,\"offerKey\":\"k1\",\"side\":\"sell\",\"itemId\":4151,\"price\":300000,"
		+ "\"totalQty\":10,\"filledQty\":3,\"placedAt\":100}";

	private static SlotState slot()
	{
		return new SlotState("k1", 4151, false, 300_000, 10, 3, 900_000, Status.ACTIVE, 100, 150);
	}

	@Test
	public void offerJson()
	{
		assertEquals(OFFER_JSON, gson.toJson(TradeUploader.offerJson(2, slot())));
	}

	@Test
	public void submitBody()
	{
		TradeEvent ev = TradeEvent.builder()
			.id("k1:placed")
			.kind(TradeEvent.PLACED)
			.side(TradeEvent.SELL)
			.itemId(4151)
			.qty(10)
			.price(300_000)
			.slot(2)
			.offerKey("k1")
			.ts(100)
			.late(false)
			.world(9000)
			.name("Abyssal whip")
			.build();
		TradeUploader.ItemInfo whip = new TradeUploader.ItemInfo(4151, "Abyssal whip");
		whip.icon = "AAAA";
		TradeUploader.ItemInfo shark = new TradeUploader.ItemInfo(385, "Shark");

		JsonObject body = TradeUploader.buildBody(gson, "install-1", new TradeUploader.BatchKey(9000, null), 1234, Collections.singletonList(ev),
			Collections.singletonList(TradeUploader.offerJson(2, slot())), Arrays.asList(whip, shark));

		assertEquals("{\"installId\":\"install-1\",\"world\":9000,\"sentAt\":1234,\"events\":[{\"id\":\"k1:placed\","
			+ "\"kind\":\"placed\",\"side\":\"sell\",\"itemId\":4151,\"qty\":10,\"price\":300000,\"slot\":2,\"offerKey\":\"k1\","
			+ "\"ts\":100,\"late\":false,\"world\":9000,\"name\":\"Abyssal whip\"}],\"offers\":[" + OFFER_JSON + "],"
			+ "\"items\":[{\"id\":4151,\"name\":\"Abyssal whip\",\"icon\":\"AAAA\"},{\"id\":385,\"name\":\"Shark\"}]}",
			gson.toJson(body));
	}

	@Test
	public void submitBodyWithoutOpenOffers()
	{
		JsonObject body = TradeUploader.buildBody(gson, "install-1", new TradeUploader.BatchKey(9000, null), 1234, Collections.emptyList(), null,
			Collections.emptyList());
		assertEquals("{\"installId\":\"install-1\",\"world\":9000,\"sentAt\":1234,\"events\":[],\"items\":[]}", gson.toJson(body));
	}

	@Test
	public void submitBodyAppendsAccountIdLast()
	{
		JsonObject body = TradeUploader.buildBody(gson, "install-1", new TradeUploader.BatchKey(9000, "abc123"), 1234,
			Collections.emptyList(), null, Collections.emptyList());
		assertEquals("{\"installId\":\"install-1\",\"world\":9000,\"sentAt\":1234,\"events\":[],\"items\":[],"
			+ "\"accountId\":\"abc123\"}", gson.toJson(body));
	}

	@Test
	public void itemLimitOnlyWhenKnownAndLast()
	{
		TradeUploader.ItemInfo whip = new TradeUploader.ItemInfo(4151, "Abyssal whip", 70);
		whip.icon = "AAAA";
		TradeUploader.ItemInfo shark = new TradeUploader.ItemInfo(385, "Shark", 0);
		TradeUploader.ItemInfo bones = new TradeUploader.ItemInfo(536, "Dragon bones", 7500);
		JsonObject body = TradeUploader.buildBody(gson, "install-1", new TradeUploader.BatchKey(9000, null), 1234,
			Collections.emptyList(), null, Arrays.asList(whip, shark, bones));
		assertEquals("{\"installId\":\"install-1\",\"world\":9000,\"sentAt\":1234,\"events\":[],\"items\":["
			+ "{\"id\":4151,\"name\":\"Abyssal whip\",\"icon\":\"AAAA\",\"limit\":70},"
			+ "{\"id\":385,\"name\":\"Shark\"},"
			+ "{\"id\":536,\"name\":\"Dragon bones\",\"limit\":7500}]}", gson.toJson(body));
	}
}

package com.hardcoreworldtoolkit;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import com.hardcoreworldtoolkit.OfferTracker.SlotState;
import com.hardcoreworldtoolkit.OfferTracker.Status;
import com.google.gson.Gson;
import java.util.Arrays;
import org.junit.Test;

/**
 * Pins the JSON written to trades.jsonl, uploaded to the server and saved in the RuneLite profile, so a refactor
 * can't silently rename or reorder anything.
 */
public class WireFormatTest
{
	private final Gson gson = new Gson();

	private static TradeEvent fullEvent()
	{
		return TradeEvent.builder()
			.id("k1:fill:3")
			.kind(TradeEvent.FILL)
			.side("buy")
			.itemId(4151)
			.qty(3)
			.price(290_000)
			.total(870_000L)
			.slot(2)
			.offerKey("k1")
			.ts(1000)
			.late(true)
			.filled(3)
			.since(900L)
			.world(9000)
			.name("Abyssal whip")
			.build();
	}

	@Test
	public void tradeEventJson()
	{
		assertEquals("{\"id\":\"k1:fill:3\",\"kind\":\"fill\",\"side\":\"buy\",\"itemId\":4151,\"qty\":3,\"price\":290000,"
			+ "\"total\":870000,\"slot\":2,\"offerKey\":\"k1\",\"ts\":1000,\"late\":true,\"filled\":3,\"since\":900,"
			+ "\"world\":9000,\"name\":\"Abyssal whip\"}", gson.toJson(fullEvent()));
	}

	@Test
	public void tradeEventOmitsNulls()
	{
		TradeEvent ev = TradeEvent.builder()
			.id("hist:x")
			.kind(TradeEvent.HISTORY)
			.side("sell")
			.itemId(385)
			.qty(500)
			.price(900)
			.ts(2000)
			.late(false)
			.world(9000)
			.build();
		assertEquals("{\"id\":\"hist:x\",\"kind\":\"history\",\"side\":\"sell\",\"itemId\":385,\"qty\":500,\"price\":900,"
			+ "\"ts\":2000,\"late\":false,\"world\":9000}", gson.toJson(ev));
	}

	@Test
	public void kindValues()
	{
		assertEquals("placed", TradeEvent.PLACED);
		assertEquals("fill", TradeEvent.FILL);
		assertEquals("cancelled", TradeEvent.CANCELLED);
		assertEquals("history", TradeEvent.HISTORY);
	}

	@Test
	public void tradeLogLineRoundTrip()
	{
		String line = "{\"id\":\"k1:fill:3\",\"kind\":\"fill\",\"side\":\"buy\",\"itemId\":4151,\"qty\":3,\"price\":290000,"
			+ "\"total\":870000,\"slot\":2,\"offerKey\":\"k1\",\"ts\":1000,\"late\":true,\"filled\":3,\"since\":900,"
			+ "\"world\":9000,\"name\":\"Abyssal whip\"}";
		assertEquals(fullEvent(), gson.fromJson(line, TradeEvent.class));
	}

	@Test
	public void localLogLineAddsAcctLast()
	{
		String line = gson.toJson(HardcoreWorldToolKitPlugin.logLine(gson, fullEvent(), "abc"));
		assertEquals("{\"id\":\"k1:fill:3\",\"kind\":\"fill\",\"side\":\"buy\",\"itemId\":4151,\"qty\":3,\"price\":290000,"
			+ "\"total\":870000,\"slot\":2,\"offerKey\":\"k1\",\"ts\":1000,\"late\":true,\"filled\":3,\"since\":900,"
			+ "\"world\":9000,\"name\":\"Abyssal whip\",\"acct\":\"abc\"}", line);
		// Reading it back ignores acct.
		assertEquals(fullEvent(), gson.fromJson(line, TradeEvent.class));
		// Unknown account: just the event.
		assertEquals(gson.toJson(fullEvent()), gson.toJson(HardcoreWorldToolKitPlugin.logLine(gson, fullEvent(), null)));
	}

	@Test
	public void slotStateJson()
	{
		SlotState s = new SlotState("k1", 4151, true, 300_000, 10, 3, 870_000, Status.ACTIVE, 100, 150);
		String json = gson.toJson(s);
		assertEquals("{\"offerKey\":\"k1\",\"itemId\":4151,\"buy\":true,\"price\":300000,\"totalQty\":10,\"sold\":3,"
			+ "\"spent\":870000,\"status\":\"ACTIVE\",\"placedAt\":100,\"seenAt\":150}", json);
		assertEquals(s, gson.fromJson(json, SlotState.class));
	}

	@Test
	public void persistedSignatures()
	{
		assertEquals("buy|4151|10|2950000", OfferTracker.signature(true, 4151, 10, 2_950_000));
		assertEquals("sell|385|500|450000", OfferTracker.signature(false, 385, 500, 450_000));
	}

	@Test
	public void statusNames()
	{
		assertArrayEquals(new String[]{"EMPTY", "ACTIVE", "COMPLETE", "CANCELLED"},
			Arrays.stream(Status.values()).map(Enum::name).toArray(String[]::new));
	}
}

