import com.hardcoreworldtoolkit.MarketData;
import com.google.gson.Gson;
import java.util.Arrays;
import java.util.List;
import org.junit.Test;

public class MarketRowsTest
{
	private static final Gson GSON = new Gson();

	private static MarketData.FeedEvent fill(long id, int item, String side, int qty, long price, long receivedAt)
	{
		return GSON.fromJson("{\"id\":" + id + ",\"kind\":\"fill\",\"side\":\"" + side + "\",\"itemId\":" + item
			+ ",\"qty\":" + qty + ",\"price\":" + price + ",\"receivedAt\":" + receivedAt + "}", MarketData.FeedEvent.class);
	}

	@Test
	public void oneRowPerItemWithItsLatestTrade()
	{
		List<MarketRows.Row> rows = MarketRows.latestPerItem(Arrays.asList(
			fill(5, 6685, "sell", 3, 5800, 1000),
			fill(4, 561, "buy", 1000, 195, 900),
			fill(3, 6685, "buy", 10, 5600, 800),
			fill(2, 561, "sell", 50, 190, 700)));
		assertEquals(2, rows.size());
		assertEquals(5L, rows.get(0).getEvent().getId());
		assertEquals(4L, rows.get(1).getEvent().getId());
		assertFalse(rows.get(0).isBothSides());
	}

	@Test
	public void bothSidesOfOneTradeAreOneTradedRow()
	{
		// Seen live: two plugin users on either side of one GE trade, reported a second apart.
		List<MarketRows.Row> rows = MarketRows.latestPerItem(Arrays.asList(
			fill(9, 6685, "sell", 10, 5697, 1001),
			fill(8, 6685, "buy", 10, 5697, 1000)));
		assertEquals(1, rows.size());
		assertEquals(9L, rows.get(0).getEvent().getId());
		assertTrue(rows.get(0).isBothSides());
	}

	@Test
	public void differentQuantityPriceOrTimeIsNotTheSameTrade()
	{
		assertFalse(MarketRows.latestPerItem(Arrays.asList(fill(2, 1, "sell", 10, 100, 1000), fill(1, 1, "buy", 9, 100, 1000)))
			.get(0).isBothSides());
		assertFalse(MarketRows.latestPerItem(Arrays.asList(fill(2, 1, "sell", 10, 100, 1000), fill(1, 1, "buy", 10, 101, 1000)))
			.get(0).isBothSides());
		assertFalse(MarketRows.latestPerItem(Arrays.asList(fill(2, 1, "sell", 10, 100, 1000),
			fill(1, 1, "buy", 10, 100, 1000 - MarketRows.SAME_TRADE - 1))).get(0).isBothSides());
		assertFalse(MarketRows.latestPerItem(Arrays.asList(fill(2, 1, "sell", 10, 100, 1000), fill(1, 1, "sell", 10, 100, 1000)))
			.get(0).isBothSides());
	}
}

package com.hardcoreworldtoolkit.ui;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import java.util.HashSet;
import java.util.Set;
import org.junit.Test;

public class NiceScaleTest
{
	/** Ticks ascend, cover [lo, hi], never go below 0, and their labels are all different. */
	private static NiceScale check(long lo, long hi)
	{
		NiceScale s = NiceScale.of(lo, hi, 4);
		assertTrue("min " + s.min, s.min >= 0);
		assertTrue(s.min <= Math.min(lo, hi));
		assertTrue(s.max >= Math.max(lo, hi));
		assertTrue(s.max > s.min);
		assertTrue("tick count " + s.tickCount(), s.tickCount() >= 2 && s.tickCount() <= 7);
		Set<String> labels = new HashSet<>();
		for (int i = 0; i < s.tickCount(); i++)
		{
			if (i > 0)
			{
				assertTrue(s.tick(i) > s.tick(i - 1));
			}
			assertTrue("duplicate label " + Format.compactGp(s.tick(i), s.step),
				labels.add(Format.compactGp(s.tick(i), s.step)));
		}
		assertEquals(s.max, s.tick(s.tickCount() - 1));
		return s;
	}

	@Test
	public void smallRanges()
	{
		check(0, 1);
		check(998, 1003);
		check(1, 2);
		check(5, 5);
	}

	@Test
	public void flatValueGetsRoomAndDistinctLabels()
	{
		NiceScale s = check(1_250_000, 1_250_000);
		assertTrue(s.min < 1_250_000 && s.max > 1_250_000);
	}

	@Test
	public void singleSmallPoint()
	{
		NiceScale s = check(1, 1);
		assertEquals(0, s.min);
		assertTrue(s.max >= 2);
	}

	@Test
	public void nearZeroNeverNegative()
	{
		assertEquals(0, check(3, 1_000).min);
		assertEquals(0, check(0, 0).min);
	}

	@Test
	public void niceSteps()
	{
		NiceScale s = check(1_210_000, 1_340_000);
		assertEquals(50_000, s.step);
		assertEquals(1_200_000, s.min);
		assertEquals(1_350_000, s.max);
	}

	@Test
	public void billions()
	{
		NiceScale s = check(1_200_000_000L, 3_400_000_000L);
		assertTrue(Format.compactGp(s.tick(1), s.step).endsWith("B"));
		check(2_147_000_000L, 2_147_000_001L);
		check(Long.MAX_VALUE / 4, Long.MAX_VALUE / 4 + 1_000);
	}

	@Test
	public void reversedInput()
	{
		NiceScale a = NiceScale.of(10, 500, 4), b = NiceScale.of(500, 10, 4);
		assertEquals(a.min, b.min);
		assertEquals(a.max, b.max);
	}
}

package com.hardcoreworldtoolkit.ui;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import com.hardcoreworldtoolkit.ActiveOffer;
import com.hardcoreworldtoolkit.OfferReport;
import com.hardcoreworldtoolkit.OfferWatch;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.junit.Test;

public class OfferLineTest
{
	private static final long PLACED = 1_000_000;
	private static final long NOW = PLACED + 3 * 3600;

	private static final ActiveOffer SELL = new ActiveOffer(2, "k2", 536, "Dragon bones", false, 1_250_000, 100, 40, PLACED);
	private static final ActiveOffer BUY = new ActiveOffer(5, "k5", 4151, "Abyssal whip", true, 2_000_000, 1, 0, PLACED);

	private static OfferWatch.OfferStatus status(String key, OfferWatch.Flag flag, Long competing, String detail, long idle)
	{
		return new OfferWatch.OfferStatus(key, flag, competing, detail, idle);
	}

	@Test
	public void homeTextAndPlainBadge()
	{
		OfferLine l = OfferLine.home(SELL, null, NOW);
		assertEquals("Sell @ 1.25M Dragon bones", l.getText());
		assertEquals("40%", l.getBadge());
		assertEquals(OfferLine.Badge.PLAIN, l.getKind());
		assertEquals("Sell @ 1.25M Dragon bones · 40/100 filled · placed 3h ago", l.getTooltip());
		assertEquals("2|k2", l.key());
	}

	@Test
	public void flags()
	{
		OfferLine under = OfferLine.home(SELL, status("k2", OfferWatch.Flag.UNDERCUT, 1_240_000L, "Lowest ask 1,240,000", 60), NOW);
		assertEquals("undercut", under.getBadge());
		assertEquals(OfferLine.Badge.ALERT, under.getKind());
		assertTrue(under.getTooltip().contains("Lowest ask 1,240,000"));

		OfferLine out = OfferLine.home(BUY, status("k5", OfferWatch.Flag.OUTBID, 2_100_000L, "Highest bid 2,100,000", 60), NOW);
		assertEquals("outbid", out.getBadge());
		assertEquals("Buy @ 2M Abyssal whip", out.getText());

		OfferLine stale = OfferLine.home(BUY, status("k5", OfferWatch.Flag.STALE, null, "No fill for 7h", 7 * 3600 + 59), NOW);
		assertEquals("stale 7h", stale.getBadge());
		assertEquals(OfferLine.Badge.STALE, stale.getKind());
	}

	@Test
	public void itemViewTextIsTheOfferLine()
	{
		OfferLine l = OfferLine.item(SELL, null, NOW);
		assertEquals("Selling @ 1,250,000 · 40/100", l.getText());
	}

	@Test
	public void justPlaced()
	{
		ActiveOffer o = new ActiveOffer(0, "k", 1, "Item", true, 5, 1, 0, NOW);
		assertTrue(OfferLine.home(o, null, NOW).getTooltip().endsWith("placed just now"));
	}

	@Test
	public void sectionLinesMatchStatusesByOfferAndHideThemWhenDisconnected()
	{
		Map<Integer, OfferWatch.OfferStatus> st = new HashMap<>();
		st.put(2, status("k2", OfferWatch.Flag.UNDERCUT, 1L, "x", 0));
		// A status for an older offer that used to be in slot 5 doesn't apply to the new one.
		st.put(5, status("old", OfferWatch.Flag.OUTBID, 1L, "y", 0));
		OfferReport report = new OfferReport(st, 1, null);
		List<OfferLine> lines = OffersSection.lines(Arrays.asList(SELL, BUY), report, true, NOW);
		assertEquals("undercut", lines.get(0).getBadge());
		assertEquals("0%", lines.get(1).getBadge());

		List<OfferLine> off = OffersSection.lines(Arrays.asList(SELL, BUY), report, false, NOW);
		assertEquals("40%", off.get(0).getBadge());
		assertTrue(OffersSection.lines(Collections.emptyList(), report, true, NOW).isEmpty());
	}
}

package com.hardcoreworldtoolkit.ui;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import com.hardcoreworldtoolkit.MarketData;
import com.google.gson.Gson;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import org.junit.Test;

public class PriceChartTest
{
	private static final Gson GSON = new Gson();
	private static final long NOW = 1_800_000_000L;

	private static MarketData.Point point(long ts, Long buy, Long sell, long vol)
	{
		return GSON.fromJson("{\"timestamp\":" + ts + (buy == null ? "" : ",\"avgBuy\":" + buy)
			+ (sell == null ? "" : ",\"avgSell\":" + sell) + ",\"buyVolume\":" + vol + ",\"sellVolume\":0}", MarketData.Point.class);
	}

	private static void paint(PriceChart c, int w)
	{
		c.setSize(w, c.getPreferredSize().height);
		BufferedImage img = new BufferedImage(w, c.getPreferredSize().height, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = img.createGraphics();
		c.paint(g);
		g.dispose();
	}

	@Test
	public void nearestIndex()
	{
		double[] xs = {10, 20, 40};
		assertEquals(-1, PriceChart.nearestIndex(new double[0], 5));
		assertEquals(0, PriceChart.nearestIndex(xs, -100));
		assertEquals(0, PriceChart.nearestIndex(xs, 14));
		assertEquals(1, PriceChart.nearestIndex(xs, 16));
		assertEquals(1, PriceChart.nearestIndex(xs, 29));
		assertEquals(2, PriceChart.nearestIndex(xs, 31));
		assertEquals(2, PriceChart.nearestIndex(xs, 1000));
	}

	@Test
	public void states()
	{
		PriceChart c = new PriceChart();
		paint(c, 205);
		assertEquals(PriceChart.LOADING, c.shownMessage());

		c.setData(Collections.emptyList(), ChartRange.D7, NOW);
		paint(c, 205);
		assertEquals("No trades in the last 7 days", c.shownMessage());

		// Only data older than the range: also empty.
		c.setData(Collections.singletonList(point(NOW - 8 * 86_400, 5L, null, 1)), ChartRange.D7, NOW);
		paint(c, 205);
		assertEquals("No trades in the last 7 days", c.shownMessage());

		c.setUnavailable(ChartRange.D7);
		paint(c, 205);
		assertEquals(PriceChart.UNAVAILABLE, c.shownMessage());
		assertFalse(c.hasData());

		c.setData(Collections.singletonList(point(NOW - 3600, 1_250_000L, null, 3)), ChartRange.D7, NOW);
		paint(c, 100);
		assertEquals(PriceChart.TOO_NARROW, c.shownMessage());
		paint(c, 205);
		assertNull(c.shownMessage());
		assertTrue(c.hasData());
	}

	@Test
	public void sameDataDoesNotRelayout()
	{
		PriceChart c = new PriceChart();
		List<MarketData.Point> pts = Arrays.asList(point(NOW - 7200, 100L, 110L, 2), point(NOW - 3600, 101L, null, 1));
		c.setData(pts, ChartRange.H24, NOW);
		paint(c, 205);
		assertFalse(c.layoutPending());
		// A refresh 20 s later with equal (separately parsed) data.
		c.setData(new ArrayList<>(Arrays.asList(point(NOW - 7200, 100L, 110L, 2), point(NOW - 3600, 101L, null, 1))),
			ChartRange.H24, NOW + 20 - NOW % 60);
		assertFalse(c.layoutPending());
		c.setData(pts, ChartRange.D7, NOW);
		assertTrue(c.layoutPending());
	}

	@Test
	public void paintsAllShapesOfData()
	{
		for (ChartRange r : ChartRange.values())
		{
			PriceChart c = new PriceChart();
			List<MarketData.Point> pts = new ArrayList<>();
			// Runs, gaps, lone points, nulls, flat values, billions.
			long step = r.stepSeconds();
			pts.add(point(NOW - r.seconds() + step, 2_100_000_000L, 2_150_000_000L, 1));
			pts.add(point(NOW - r.seconds() + 2 * step, 2_100_000_000L, null, 1_000_000));
			pts.add(point(NOW - r.seconds() / 2, null, 2_000_000_000L, 5));
			pts.add(point(NOW - step, 2_100_000_000L, 2_100_000_000L, 0));
			c.setData(pts, r, NOW);
			for (int w : new int[]{120, 205, 400, 1000})
			{
				paint(c, w);
				assertNull(c.shownMessage());
			}
		}
	}

	@Test
	public void singlePointAndFlatData()
	{
		PriceChart c = new PriceChart();
		c.setData(Collections.singletonList(point(NOW - 60, 7L, 7L, 1)), ChartRange.H24, NOW);
		paint(c, 205);
		assertNull(c.shownMessage());
	}

	@Test
	public void gutterDoesNotDependOnVolume()
	{
		int[] widths = new int[3];
		long[] vols = {3, 1_000_000, 2_000_000_000L};
		for (int i = 0; i < vols.length; i++)
		{
			PriceChart c = new PriceChart();
			c.setData(Arrays.asList(point(NOW - 7200, 1_240_000L, 1_300_000L, vols[i]), point(NOW - 3600, 1_260_000L, null, 1)),
				ChartRange.H24, NOW);
			paint(c, 205);
			widths[i] = c.gutter();
		}
		assertEquals(widths[0], widths[1]);
		assertEquals(widths[0], widths[2]);
	}
}

package com.hardcoreworldtoolkit.ui;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import com.hardcoreworldtoolkit.ProfitSnapshot;
import java.awt.Component;
import java.awt.Container;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import java.util.concurrent.atomic.AtomicInteger;
import javax.swing.JButton;
import org.junit.Test;

public class ProfitTextTest
{
	private static ProfitSnapshot.ItemProfit item(int id, long held, long avg, long realized, long unknown, long unknownQty,
		long history)
	{
		return new ProfitSnapshot.ItemProfit(id, "Dragon bones", held, avg, realized, unknown, unknownQty, history);
	}

	private static ProfitSnapshot snapshot(long allTime, long history, long unknown, boolean rebuilding, boolean log,
		ProfitSnapshot.ItemProfit... items)
	{
		Map<Integer, ProfitSnapshot.ItemProfit> byId = new HashMap<>();
		List<ProfitSnapshot.ItemProfit> top = new ArrayList<>();
		for (ProfitSnapshot.ItemProfit p : items)
		{
			byId.put(p.getItemId(), p);
			top.add(p);
		}
		TreeMap<String, Long> daily = new TreeMap<>();
		daily.put(LocalDate.now().toString(), allTime);
		return new ProfitSnapshot(allTime, history, unknown, daily, top, byId, rebuilding, log);
	}

	@Test
	public void signedGp()
	{
		assertEquals("0", Format.signedGp(0));
		assertEquals("+950", Format.signedGp(950));
		assertEquals("-350K", Format.signedGp(-350_000));
		assertEquals("+1.25M", Format.signedGp(1_250_000));
		assertEquals("+2.14B", Format.signedGp(2_147_000_000L));
		assertTrue(Format.signedGp(Long.MIN_VALUE).startsWith("-"));
		assertEquals("1.21M", Format.shortGp(1_210_000));
	}

	@Test
	public void itemLines()
	{
		ProfitSnapshot.ItemProfit p = item(536, 1_200, 1_210_000, 3_400_000, 0, 0, 0);
		assertEquals("Held 1,200 · avg 1.21M · realized +3.4M", ProfitText.itemLine(p));
		assertNull(ProfitText.itemUnknownLine(p));
		assertTrue(ProfitText.hasPosition(p));

		ProfitSnapshot.ItemProfit sold = item(536, 0, 0, -50_000, 3_200_000, 3, 0);
		assertEquals("Realized -50K", ProfitText.itemLine(sold));
		assertEquals("3 sold for 3.2M with no known cost (not counted)", ProfitText.itemUnknownLine(sold));
		assertTrue(ProfitText.itemTooltip(sold).contains("no known cost"));

		assertFalse(ProfitText.hasPosition(null));
		assertFalse(ProfitText.hasPosition(item(536, 0, 0, 0, 0, 0, 0)));
		assertTrue(ProfitText.itemTooltip(item(536, 0, 0, 10, 0, 0, 10)).contains("from GE History"));
		assertEquals("Item 7", ProfitText.name(new ProfitSnapshot.ItemProfit(7, null, 0, 0, 0, 0, 0, 0)));
	}

	@Test
	public void footnotesOnlyWhenNonZero()
	{
		assertNull(ProfitText.historyNote(snapshot(5, 0, 0, false, true)));
		assertNull(ProfitText.unknownNote(snapshot(5, 0, 0, false, true)));
		assertEquals("Incl. +4.1M from GE History (counted at import)",
			ProfitText.historyNote(snapshot(5, 4_100_000, 0, false, true)));
		assertEquals("Sold without known cost: 3.2M (not counted)",
			ProfitText.unknownNote(snapshot(5, 0, 3_200_000, false, true)));
		assertEquals(PanelComponents.GOOD, ProfitText.color(1));
		assertEquals(PanelComponents.ALERT, ProfitText.color(-1));
	}

	@Test
	public void sectionVisibility()
	{
		assertFalse(ProfitSection.visible(null));
		assertFalse(ProfitSection.visible(ProfitSnapshot.EMPTY));
		// No numbers yet, but a log a rebuild could count.
		assertTrue(ProfitSection.visible(snapshot(0, 0, 0, false, true)));
		assertTrue(ProfitSection.visible(snapshot(0, 0, 0, false, false, item(1, 1, 1, 0, 0, 0, 0))));
	}

	private static List<Component> all(Container c)
	{
		List<Component> out = new ArrayList<>();
		for (Component ch : c.getComponents())
		{
			out.add(ch);
			if (ch instanceof Container)
			{
				out.addAll(all((Container) ch));
			}
		}
		return out;
	}

	private static JButton button(ProfitSection s)
	{
		for (Component c : all((Container) s.getComponent()))
		{
			if (c instanceof JButton)
			{
				return (JButton) c;
			}
		}
		throw new AssertionError("no button");
	}

	@Test
	public void sectionRendersOnlyOnChangeAndRebuildButtonStates()
	{
		AtomicInteger rebuilds = new AtomicInteger();
		ProfitSection s = new ProfitSection(rebuilds::incrementAndGet, (id, name) ->
		{
		});
		assertFalse(s.getComponent().isVisible());
		ProfitSnapshot snap = snapshot(1_000, 0, 0, false, true, item(1, 0, 0, 1_000, 0, 0, 0));
		// Off until the "Show profit" setting is on, even with numbers.
		s.setSnapshot(snap);
		assertFalse(s.getComponent().isVisible());
		s.setShown(true);
		assertTrue(s.getComponent().isVisible());
		s.setShown(false);
		assertFalse(s.getComponent().isVisible());
		s.setShown(true);
		List<Component> before = all((Container) s.getComponent());
		s.setSnapshot(snapshot(1_000, 0, 0, false, true, item(1, 0, 0, 1_000, 0, 0, 0)));
		s.tick();
		List<Component> after = all((Container) s.getComponent());
		assertEquals(before.size(), after.size());
		for (int i = 0; i < before.size(); i++)
		{
			assertSame(before.get(i), after.get(i));
		}

		JButton b = button(s);
		assertTrue(b.isEnabled());
		b.doClick();
		assertEquals(1, rebuilds.get());
		assertFalse(b.isEnabled());
		assertEquals("Rebuilding…", b.getText());
		s.setSnapshot(snapshot(1_000, 0, 0, true, true, item(1, 0, 0, 1_000, 0, 0, 0)));
		assertFalse(b.isEnabled());
		s.setSnapshot(snap);
		assertTrue(b.isEnabled());
		assertEquals("Rebuild", b.getText());

		s.setLogEnabled(false);
		assertFalse(b.isEnabled());
		assertEquals(ProfitText.REBUILD_NEEDS_LOG, b.getToolTipText());
	}
}

package com.hardcoreworldtoolkit.ui;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotSame;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import java.awt.Component;
import java.awt.Container;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;
import javax.swing.JButton;
import javax.swing.JComponent;
import javax.swing.JLabel;
import org.junit.Test;

public class RowListTest
{
	/** How many times the factory built each item. */
	private final Map<String, Integer> built = new HashMap<>();
	private final Map<String, String> versions = new HashMap<>();

	private RowList<String> list()
	{
		return new RowList<>(s -> s, s -> versions.getOrDefault(s, ""), s ->
		{
			built.merge(s, 1, Integer::sum);
			return new JLabel(s);
		});
	}

	private static List<String> items(int n)
	{
		List<String> out = new ArrayList<>();
		for (int i = 0; i < n; i++)
		{
			out.add("r" + i);
		}
		return out;
	}

	/** The row components on screen, in order (each row sits in a wrapper with its spacing). */
	private static List<Component> rows(RowList<?> l)
	{
		List<Component> out = new ArrayList<>();
		for (Component c : l.getComponent().getComponents())
		{
			if (c instanceof Container && ((Container) c).getComponentCount() > 0 && !(c instanceof JButton)
				&& ((Container) c).getComponent(0) instanceof JLabel)
			{
				out.add(((Container) c).getComponent(0));
			}
		}
		return out;
	}

	private static List<String> texts(RowList<?> l)
	{
		return rows(l).stream().map(c -> ((JLabel) c).getText()).collect(Collectors.toList());
	}

	private static JButton moreButton(RowList<?> l)
	{
		for (Component c : l.getComponent().getComponents())
		{
			if (c instanceof JButton)
			{
				return (JButton) c;
			}
		}
		return null;
	}

	@Test
	public void factoryRunsOncePerNewKey()
	{
		RowList<String> l = list();
		l.setItems(Arrays.asList("a", "b"));
		l.setItems(Arrays.asList("c", "a", "b"));
		assertEquals(Arrays.asList("c", "a", "b"), texts(l));
		assertEquals(Integer.valueOf(1), built.get("a"));
		assertEquals(Integer.valueOf(1), built.get("b"));
		assertEquals(Integer.valueOf(1), built.get("c"));
	}

	@Test
	public void identicalInputChangesNothing()
	{
		RowList<String> l = list();
		l.setItems(Arrays.asList("a", "b"));
		Component[] before = l.getComponent().getComponents();
		l.setItems(new ArrayList<>(Arrays.asList("a", "b")));
		Component[] after = l.getComponent().getComponents();
		assertEquals(before.length, after.length);
		for (int i = 0; i < before.length; i++)
		{
			assertSame(before[i], after[i]);
		}
	}

	@Test
	public void changedVersionRebuildsOnlyThatRow()
	{
		RowList<String> l = list();
		l.setItems(Arrays.asList("a", "b"));
		Component a = rows(l).get(0), b = rows(l).get(1);
		versions.put("b", "6m");
		l.setItems(Arrays.asList("a", "b"));
		assertSame(a, rows(l).get(0));
		assertNotSame(b, rows(l).get(1));
		assertEquals(Integer.valueOf(2), built.get("b"));
		// A rebuilt row isn't new: no highlight.
		assertFalse(RowList.HIGHLIGHT.equals(rows(l).get(1).getBackground()));
	}

	@Test
	public void showMoreGrowsByAPage()
	{
		RowList<String> l = list();
		l.setItems(items(120));
		assertEquals(RowList.PAGE, rows(l).size());
		assertEquals("Show more (70 more)", moreButton(l).getText());
		moreButton(l).doClick();
		assertEquals(100, rows(l).size());
		assertEquals("Show more (20 more)", moreButton(l).getText());
		moreButton(l).doClick();
		assertEquals(120, rows(l).size());
		assertEquals(null, moreButton(l));
		// The first rows were built once, never again.
		assertEquals(Integer.valueOf(1), built.get("r0"));

		l.reset();
		l.setItems(items(120));
		assertEquals(RowList.PAGE, rows(l).size());
	}

	@Test
	public void rowsNotVisibleAreNotBuilt()
	{
		RowList<String> l = list();
		l.setItems(items(1000));
		assertEquals(RowList.PAGE, built.size());
	}

	@Test
	public void newRowsAreHighlightedButNotOnTheFirstRender()
	{
		RowList<String> l = list();
		l.setItems(Arrays.asList("a", "b"));
		for (Component c : rows(l))
		{
			assertFalse(RowList.HIGHLIGHT.equals(c.getBackground()));
		}
		l.setItems(Arrays.asList("c", "a", "b"));
		assertEquals(RowList.HIGHLIGHT, rows(l).get(0).getBackground());
		assertFalse(RowList.HIGHLIGHT.equals(rows(l).get(1).getBackground()));

		// After a reset (tab or item change) nothing counts as new.
		l.reset();
		l.setItems(Arrays.asList("d", "c", "a", "b"));
		assertFalse(RowList.HIGHLIGHT.equals(rows(l).get(0).getBackground()));
		l.stop();
	}

	@Test
	public void anEmptyRenderIsNoBaselineForHighlighting()
	{
		RowList<String> l = list();
		// What a reset feed or a logged-out offers list does: empty first, then the first real load.
		l.setItems(Collections.emptyList());
		l.reset();
		l.setItems(Collections.emptyList());
		l.setItems(Arrays.asList("a", "b"));
		for (Component c : rows(l))
		{
			assertFalse(RowList.HIGHLIGHT.equals(c.getBackground()));
		}
		l.stop();
	}

	@Test
	public void emptyShowsTheMessage()
	{
		RowList<String> l = list();
		l.setEmptyText("Nothing here");
		l.setItems(Collections.emptyList());
		assertEquals(1, l.getComponent().getComponentCount());
		assertEquals("Nothing here", ((javax.swing.text.JTextComponent) l.getComponent().getComponent(0)).getText());
		l.setItems(Collections.singletonList("a"));
		assertEquals(Collections.singletonList("a"), texts(l));
		assertEquals(1, l.getComponent().getComponentCount());
	}

	@Test
	public void newKeys()
	{
		assertEquals(new HashSet<>(Arrays.asList("c", "d")),
			RowList.newKeys(Arrays.asList("a", "b"), Arrays.asList("c", "a", "d")));
		assertTrue(RowList.newKeys(Arrays.asList("a"), Arrays.asList("a")).isEmpty());
	}

	@Test
	public void occurrenceKeysStayUnique()
	{
		List<RowList.Keyed<String>> keyed = RowList.withOccurrenceKeys(Arrays.asList("x", "y", "x"), s -> s);
		assertEquals(Arrays.asList("x|1", "y|1", "x|2"), keyed.stream().map(k -> k.key).collect(Collectors.toList()));
		assertEquals("x", keyed.get(2).value);
	}

	@Test
	public void rowsKeepTheirComponentsAcrossReorder()
	{
		RowList<String> l = list();
		l.setItems(Arrays.asList("a", "b", "c"));
		JComponent b = (JComponent) rows(l).get(1);
		l.setItems(Arrays.asList("b", "c"));
		assertSame(b, rows(l).get(0));
	}
}

package com.hardcoreworldtoolkit.ui;

import static org.junit.Assert.assertEquals;
import java.awt.image.BufferedImage;
import org.junit.Test;

public class SkullIconTest
{
	@Test
	public void bonyWithSeeThroughEyes()
	{
		BufferedImage img = SkullIcon.draw(32, SkullIcon.BONE);
		assertEquals(32, img.getWidth());
		assertEquals(32, img.getHeight());
		// The forehead is bone; an eye socket and the corner of the image are see-through.
		assertEquals(SkullIcon.BONE.getRGB(), img.getRGB(16, 8));
		assertEquals(0, img.getRGB(10, 14) >>> 24);
		assertEquals(0, img.getRGB(0, 0) >>> 24);
	}

	@Test
	public void drawsAtSidebarSize()
	{
		BufferedImage img = SkullIcon.draw(16, SkullIcon.BONE);
		int opaque = 0;
		for (int y = 0; y < 16; y++)
		{
			for (int x = 0; x < 16; x++)
			{
				if ((img.getRGB(x, y) >>> 24) > 0)
				{
					opaque++;
				}
			}
		}
		// Neither blank nor a filled square.
		assertEquals(true, opaque > 60 && opaque < 200);
	}
}

package com.hardcoreworldtoolkit.ui;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import java.time.Instant;
import java.time.ZoneId;
import java.time.ZoneOffset;
import org.junit.Test;

public class TimeTicksTest
{
	private static final ZoneId UTC = ZoneOffset.UTC;
	private static final ZoneId NEW_YORK = ZoneId.of("America/New_York");

	private static long ts(String iso)
	{
		return Instant.parse(iso).getEpochSecond();
	}

	private static void ascendingInRange(TimeTicks t, long t0, long t1)
	{
		for (int i = 0; i < t.ts.length; i++)
		{
			assertTrue(t.ts[i] >= t0 && t.ts[i] <= t1);
			if (i > 0)
			{
				assertTrue(t.ts[i] > t.ts[i - 1]);
			}
		}
	}

	@Test
	public void dayRangeUsesHoursAtLeastThreeApart()
	{
		long t1 = ts("2026-10-07T12:30:00Z"), t0 = t1 - 86_400;
		TimeTicks t = TimeTicks.of(t0, t1, ChartRange.H24, UTC, 8);
		assertArrayEquals(new String[]{"15:00", "18:00", "21:00", "00:00", "03:00", "06:00", "09:00", "12:00"}, t.labels);
		ascendingInRange(t, t0, t1);
		for (int i = 1; i < t.ts.length; i++)
		{
			assertTrue(t.ts[i] - t.ts[i - 1] >= 3 * 3600);
		}
		// Less room: every 6 hours.
		assertArrayEquals(new String[]{"18:00", "00:00", "06:00", "12:00"}, TimeTicks.of(t0, t1, ChartRange.H24, UTC, 4).labels);
	}

	@Test
	public void dayRangeInLocalTime()
	{
		long t1 = ts("2026-10-07T12:30:00Z"), t0 = t1 - 86_400;
		TimeTicks t = TimeTicks.of(t0, t1, ChartRange.H24, NEW_YORK, 4);
		// 12:30 UTC is 08:30 in New York (EDT).
		assertArrayEquals(new String[]{"12:00", "18:00", "00:00", "06:00"}, t.labels);
		ascendingInRange(t, t0, t1);
	}

	@Test
	public void weekUsesWeekdays()
	{
		long t1 = ts("2026-10-07T12:00:00Z"), t0 = t1 - 7 * 86_400;
		TimeTicks t = TimeTicks.of(t0, t1, ChartRange.D7, UTC, 10);
		assertArrayEquals(new String[]{"Thu", "Fri", "Sat", "Sun", "Mon", "Tue", "Wed"}, t.labels);
		assertEquals(ts("2026-10-01T00:00:00Z"), t.ts[0]);
		assertTrue(TimeTicks.of(t0, t1, ChartRange.D7, UTC, 4).ts.length <= 4);
	}

	@Test
	public void monthUsesMondays()
	{
		long t1 = ts("2026-10-07T12:00:00Z"), t0 = t1 - 30 * 86_400;
		TimeTicks t = TimeTicks.of(t0, t1, ChartRange.D30, UTC, 6);
		assertArrayEquals(new String[]{"14 Sep", "21 Sep", "28 Sep", "5 Oct"}, t.labels);
	}

	@Test
	public void quarterEveryFewWeeks()
	{
		long t1 = ts("2026-10-07T12:00:00Z"), t0 = t1 - 90 * 86_400;
		TimeTicks t = TimeTicks.of(t0, t1, ChartRange.D90, UTC, 5);
		assertTrue(t.ts.length >= 2 && t.ts.length <= 5);
		for (int i = 1; i < t.ts.length; i++)
		{
			long gap = t.ts[i] - t.ts[i - 1];
			assertTrue(gap >= 14 * 86_400 && gap % (7 * 86_400) == 0);
		}
		ascendingInRange(t, t0, t1);
	}

	@Test
	public void yearUsesMonths()
	{
		long t1 = ts("2026-10-07T12:00:00Z"), t0 = t1 - 365 * 86_400;
		TimeTicks t = TimeTicks.of(t0, t1, ChartRange.Y1, UTC, 12);
		assertArrayEquals(new String[]{"Nov", "Dec", "Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct"},
			t.labels);
		assertEquals(ts("2025-11-01T00:00:00Z"), t.ts[0]);
		assertArrayEquals(new String[]{"Jan", "Apr", "Jul", "Oct"}, TimeTicks.of(t0, t1, ChartRange.Y1, UTC, 4).labels);
	}

	@Test
	public void maxLabelsIsRespected()
	{
		long t1 = ts("2026-10-07T12:00:00Z");
		for (ChartRange r : ChartRange.values())
		{
			for (int max = 1; max <= 12; max++)
			{
				TimeTicks t = TimeTicks.of(t1 - r.seconds(), t1, r, NEW_YORK, max);
				assertTrue(r + " " + max + ": " + t.ts.length, t.ts.length <= max);
				assertEquals(t.ts.length, t.labels.length);
			}
			assertEquals(0, TimeTicks.of(t1 - r.seconds(), t1, r, UTC, 0).ts.length);
		}
	}

	@Test
	public void acrossDaylightSavingChange()
	{
		// New York leaves DST on 1 Nov 2026 at 02:00 local.
		long t1 = ts("2026-11-01T18:00:00Z"), t0 = t1 - 86_400;
		TimeTicks t = TimeTicks.of(t0, t1, ChartRange.H24, NEW_YORK, 8);
		ascendingInRange(t, t0, t1);
		for (String label : t.labels)
		{
			assertTrue(label, Integer.parseInt(label.substring(0, 2)) % 3 == 0 && label.endsWith(":00"));
		}
	}
}

package com.hardcoreworldtoolkit.ui;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import com.hardcoreworldtoolkit.Onboarding;
import java.awt.Component;
import java.awt.Container;
import java.util.concurrent.atomic.AtomicInteger;
import javax.swing.AbstractButton;
import javax.swing.JLabel;
import javax.swing.SwingUtilities;
import javax.swing.text.JTextComponent;
import org.junit.Test;

public class WelcomeCardTest
{
	private final AtomicInteger connects = new AtomicInteger();
	private final AtomicInteger dismissed = new AtomicInteger();

	private static Container card(WelcomeCard c)
	{
		return (Container) ((Container) c.getComponent()).getComponent(0);
	}

	private static String allText(Component c)
	{
		StringBuilder sb = new StringBuilder();
		if (c instanceof JLabel)
		{
			sb.append(((JLabel) c).getText()).append('\n');
		}
		else if (c instanceof JTextComponent)
		{
			sb.append(((JTextComponent) c).getText()).append('\n');
		}
		else if (c instanceof AbstractButton)
		{
			sb.append('[').append(((AbstractButton) c).getText()).append("]\n");
		}
		if (c instanceof Container)
		{
			for (Component child : ((Container) c).getComponents())
			{
				sb.append(allText(child));
			}
		}
		return sb.toString();
	}

	private static AbstractButton button(Component c, String text)
	{
		if (c instanceof AbstractButton && text.equals(((AbstractButton) c).getText()))
		{
			return (AbstractButton) c;
		}
		if (c instanceof Container)
		{
			for (Component child : ((Container) c).getComponents())
			{
				AbstractButton b = button(child, text);
				if (b != null)
				{
					return b;
				}
			}
		}
		return null;
	}

	@Test
	public void states() throws Exception
	{
		SwingUtilities.invokeAndWait(() ->
		{
			boolean[] answer = {false};
			int[] asked = {0};
			WelcomeCard c = new WelcomeCard(connects::incrementAndGet, () -> { }, dismissed::incrementAndGet, parent ->
			{
				asked[0]++;
				return answer[0];
			});
			assertFalse(c.getComponent().isVisible());

			c.update(Onboarding.Step.CONNECT_AND_IMPORT, true, null);
			assertTrue(c.getComponent().isVisible());
			String text = allText(c.getComponent());
			assertTrue(text, text.contains("[Connect]"));
			assertTrue(text, text.contains(WelcomeCard.SHARED_TEXT));
			// RuneLite's warning is a confirmation on Connect now, not text on the card.
			assertFalse(text, text.contains("submits your IP address to a 3rd-party server"));
			assertFalse(WelcomeCard.SHARED_TEXT, WelcomeCard.SHARED_TEXT.contains("your IP address"));
			assertTrue(WelcomeCard.SHARED_TEXT, WelcomeCard.SHARED_TEXT.contains("IP addresses are never stored"));
			assertFalse(text, text.contains("Import your GE History"));

			// Same state: nothing is rebuilt.
			Component first = card(c).getComponent(0);
			c.update(Onboarding.Step.CONNECT_AND_IMPORT, true, null);
			assertSame(first, card(c).getComponent(0));

			// Declining the warning doesn't connect; accepting does.
			button(c.getComponent(), "Connect").doClick();
			assertEquals(1, asked[0]);
			assertEquals(0, connects.get());
			answer[0] = true;
			button(c.getComponent(), "Connect").doClick();
			assertEquals(2, asked[0]);
			assertEquals(1, connects.get());

			c.update(Onboarding.Step.IMPORT, false, null);
			assertFalse(c.getComponent().isVisible());

			c.update(Onboarding.Step.IMPORTED_NOTICE, false, 12);
			text = allText(c.getComponent());
			assertTrue(text, text.contains("Imported 12 trades from GE History"));
			assertFalse(text, text.contains("Get started"));
			button(c.getComponent(), "x").doClick();
			assertEquals(1, dismissed.get());

			c.update(Onboarding.Step.HIDDEN, false, null);
			assertFalse(c.getComponent().isVisible());
		});
	}
}
